window.XDBANK_OBJ.judge = [{"ty":"judge","ch":1,"kp":"无穷小运算","src":"教材经典","diff":1,"q":"当 \\(x\\to x_0\\) 时，若 \\(\\alpha\\)、\\(\\beta\\) 都是无穷小，则 \\(\\alpha+\\beta\\) 仍是无穷小。","ans":"√","sol":"\\(|\\alpha+\\beta|\\le|\\alpha|+|\\beta|\\to 0\\)，由夹逼可知两个无穷小的和仍是无穷小。","id":"j1"},{"ty":"judge","ch":1,"kp":"极限存在准则","src":"教材经典","diff":1,"q":"单调有界数列必有极限。","ans":"√","sol":"这是单调有界收敛准则：单调递增且有上界（或单调递减且有下界）的数列必收敛。","id":"j2"},{"ty":"judge","ch":1,"kp":"连续概念","src":"教材经典","diff":1,"q":"若 \\(\\lim\\limits_{x\\to x_0}f(x)\\) 存在，则 \\(f(x)\\) 在 \\(x_0\\) 处连续。","ans":"×","sol":"连续还要求极限值等于函数值。如 \\(f(x)=\\dfrac{\\sin x}{x}\\) 在 \\(x=0\\) 处无定义，极限为 1，但不连续。","id":"j3"},{"ty":"judge","ch":1,"kp":"无穷大运算","src":"真题改编","diff":2,"q":"若 \\(\\lim\\limits_{x\\to x_0}f(x)=\\infty\\)，\\(\\lim\\limits_{x\\to x_0}g(x)=\\infty\\)，则 \\(\\lim\\limits_{x\\to x_0}[f(x)+g(x)]=\\infty\\)。","ans":"×","sol":"取 \\(g(x)=-f(x)\\)，则 \\(f+g=0\\)，极限为 0。\\(\\infty+\\infty\\) 属未定式。","id":"j4"},{"ty":"judge","ch":1,"kp":"连续性质","src":"真题改编","diff":2,"q":"若 \\(f(x)\\) 在 \\(x_0\\) 处连续，则 \\(|f(x)|\\) 在 \\(x_0\\) 处也连续。","ans":"√","sol":"由 \\(||f(x)|-|f(x_0)||\\le|f(x)-f(x_0)|\\to 0\\) 得 \\(|f|\\) 在 \\(x_0\\) 连续。注意反之不成立。","id":"j5"},{"ty":"judge","ch":1,"kp":"无穷小与无穷大","src":"吉米多维奇精选","diff":2,"q":"无穷小量与无穷大量的乘积必是无穷小量。","ans":"×","sol":"如 \\(x\\to 0\\) 时 \\(x\\cdot\\dfrac{1}{x}=1\\)，既非无穷小也非无穷大。\\(0\\cdot\\infty\\) 是未定式。","id":"j6"},{"ty":"judge","ch":2,"kp":"可导与连续","src":"教材经典","diff":1,"q":"若 \\(f(x)\\) 在 \\(x_0\\) 处可导，则 \\(f(x)\\) 在 \\(x_0\\) 处连续。","ans":"√","sol":"可导必连续：\\(\\Delta y\\to 0\\) 由 \\(\\Delta y=\\dfrac{\\Delta y}{\\Delta x}\\cdot\\Delta x\\) 且前者极限存在、后者趋于 0 得到。","id":"j7"},{"ty":"judge","ch":2,"kp":"可导与连续","src":"教材经典","diff":1,"q":"若 \\(f(x)\\) 在 \\(x_0\\) 处连续，则 \\(f(x)\\) 在 \\(x_0\\) 处可导。","ans":"×","sol":"如 \\(f(x)=|x|\\) 在 \\(x=0\\) 处连续但不可导。连续是可导的必要而非充分条件。","id":"j8"},{"ty":"judge","ch":2,"kp":"初等函数可导性","src":"教材经典","diff":1,"q":"初等函数在其定义区间内处处可导。","ans":"×","sol":"如 \\(f(x)=x^{2/3}\\) 是初等函数，定义域为 \\(\\mathbb{R}\\)，但在 \\(x=0\\) 处不可导。初等函数在其定义区间内连续，未必处处可导。","id":"j9"},{"ty":"judge","ch":2,"kp":"求导法则","src":"教材经典","diff":1,"q":"\\([f(x)g(x)]'=f'(x)g'(x)\\)。","ans":"×","sol":"乘积法则应为 \\((fg)'=f'g+fg'\\)。反例：\\(f=g=x\\)，左边 \\(2x\\)，右边 \\(1\\)。","id":"j10"},{"ty":"judge","ch":2,"kp":"导数定义","src":"真题改编","diff":2,"q":"若 \\(f'(x_0)\\) 存在，则 \\(\\lim\\limits_{h\\to 0}\\dfrac{f(x_0+h)-f(x_0-h)}{2h}=f'(x_0)\\)。","ans":"√","sol":"原式 \\(=\\dfrac{1}{2}\\left[\\dfrac{f(x_0+h)-f(x_0)}{h}+\\dfrac{f(x_0-h)-f(x_0)}{-h}\\right]\\to\\dfrac{1}{2}[f'(x_0)+f'(x_0)]=f'(x_0)\\)。注意其逆命题不成立。","id":"j11"},{"ty":"judge","ch":2,"kp":"奇偶性导数","src":"吉米多维奇精选","diff":2,"q":"若 \\(f(x)\\) 是偶函数且在 \\(x=0\\) 处可导，则 \\(f'(0)=0\\)。","ans":"√","sol":"由 \\(f(x)=f(-x)\\) 两边求导得 \\(f'(x)=-f'(-x)\\)，令 \\(x=0\\) 得 \\(f'(0)=-f'(0)\\)，故 \\(f'(0)=0\\)。","id":"j12"},{"ty":"judge","ch":3,"kp":"驻点与极值","src":"教材经典","diff":1,"q":"若 \\(f'(x_0)=0\\)，则 \\(f(x_0)\\) 必为极值。","ans":"×","sol":"驻点未必是极值点。如 \\(y=x^3\\) 在 \\(x=0\\) 处 \\(y'=0\\)，但 \\(y'=3x^2\\ge 0\\) 两侧不变号，无极值。","id":"j13"},{"ty":"judge","ch":3,"kp":"罗尔定理","src":"教材经典","diff":1,"q":"若 \\(f(x)\\) 在 \\([a,b]\\) 上连续、\\((a,b)\\) 内可导且 \\(f(a)=f(b)\\)，则至少存在一点 \\(\\xi\\in(a,b)\\) 使 \\(f'(\\xi)=0\\)。","ans":"√","sol":"这就是罗尔定理的结论，三个条件缺一不可，结论是存在性的（至少一点）。","id":"j14"},{"ty":"judge","ch":3,"kp":"拐点判定","src":"教材经典","diff":2,"q":"若 \\(f''(x_0)=0\\)，则点 \\((x_0,f(x_0))\\) 一定是曲线 \\(y=f(x)\\) 的拐点。","ans":"×","sol":"拐点要求 \\(f''\\) 在 \\(x_0\\) 两侧变号。如 \\(y=x^4\\)，\\(y''=12x^2\\ge 0\\) 在 \\(x=0\\) 两侧不变号，\\((0,0)\\) 不是拐点。","id":"j15"},{"ty":"judge","ch":3,"kp":"单调性判定","src":"教材经典","diff":1,"q":"若在 \\((a,b)\\) 内 \\(f'(x)>0\\)，则 \\(f(x)\\) 在 \\((a,b)\\) 上单调增加。","ans":"√","sol":"由拉格朗日中值定理：对任意 \\(x_1&lt;x_2\\)，\\(f(x_2)-f(x_1)=f'(\\xi)(x_2-x_1)>0\\)。","id":"j16"},{"ty":"judge","ch":3,"kp":"单调与导数","src":"真题改编","diff":2,"q":"单调可导函数的导函数必单调。","ans":"×","sol":"如 \\(f(x)=x^3\\) 在 \\(\\mathbb{R}\\) 上单调增加，但 \\(f'(x)=3x^2\\) 在 \\(\\mathbb{R}\\) 上先减后增，并不单调。","id":"j17"},{"ty":"judge","ch":3,"kp":"中值定理","src":"真题改编","diff":2,"q":"拉格朗日中值定理 \\(f(b)-f(a)=f'(\\xi)(b-a)\\) 中的 \\(\\xi\\) 必是唯一的。","ans":"×","sol":"如 \\(f(x)=x^3-3x\\) 在 \\([-2,2]\\) 上：\\(f(2)-f(-2)=0\\)，令 \\(f'(\\xi)=3\\xi^2-3=0\\) 得 \\(\\xi=\\pm 1\\)，有两点。","id":"j18"},{"ty":"judge","ch":4,"kp":"原函数性质","src":"教材经典","diff":1,"q":"同一函数在区间 \\(I\\) 上的任意两个原函数之差为常数。","ans":"√","sol":"设 \\(F'\\) 与 \\(G'\\) 都等于 \\(f\\)，则 \\((F-G)'=0\\)，由拉格朗日中值定理推论 \\(F-G=C\\)。","id":"j19"},{"ty":"judge","ch":4,"kp":"原函数存在","src":"教材经典","diff":1,"q":"连续函数必有原函数。","ans":"√","sol":"连续函数的变上限积分 \\(\\Phi(x)=\\int_a^x f(t)\\,dt\\) 就是它的一个原函数（原函数存在定理）。","id":"j20"},{"ty":"judge","ch":4,"kp":"原函数性质","src":"教材经典","diff":2,"q":"初等函数的原函数一定是初等函数。","ans":"×","sol":"如 \\(e^{-x^2}\\)、\\(\\dfrac{\\sin x}{x}\\) 都连续，但其原函数不是初等函数（\"积不出\"）。","id":"j21"},{"ty":"judge","ch":4,"kp":"不定积分概念","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\int f'(x)\\,dx=f(x)\\)。","ans":"×","sol":"不定积分是全体原函数，应为 \\(\\displaystyle\\int f'(x)\\,dx=f(x)+C\\)，漏掉常数 \\(C\\) 是常见错误。","id":"j22"},{"ty":"judge","ch":4,"kp":"换元法则","src":"真题改编","diff":2,"q":"若 \\(\\displaystyle\\int f(x)\\,dx=F(x)+C\\)，则 \\(\\displaystyle\\int f(2x)\\,dx=F(2x)+C\\)。","ans":"×","sol":"\\(\\displaystyle\\int f(2x)\\,dx=\\dfrac{1}{2}\\int f(2x)\\,d(2x)=\\dfrac{1}{2}F(2x)+C\\)，漏除系数是典型错误。","id":"j23"},{"ty":"judge","ch":4,"kp":"原函数奇偶性","src":"真题改编","diff":3,"q":"偶函数的原函数都是奇函数。","ans":"×","sol":"如 \\(f(x)=x^2\\) 是偶函数，\\(F(x)=x^3+1\\) 是它的原函数但不是奇函数。偶函数的原函数 \\(F(x)+C\\) 中只有使 \\(F(0)+C=0\\) 的那一个才是奇函数。","id":"j24"},{"ty":"judge","ch":5,"kp":"定积分定义","src":"教材经典","diff":1,"q":"定积分 \\(\\int_a^b f(x)\\,dx\\) 的值只与被积函数和积分区间有关，与积分变量用什么字母表示无关。","ans":"√","sol":"<p>定积分是一个确定的数，由被积函数与积分区间唯一确定，把积分变量 \\(x\\) 换成 \\(t\\) 不改变其值。</p>","id":"j25"},{"ty":"judge","ch":5,"kp":"奇偶对称性","src":"教材经典","diff":1,"q":"若 \\(f(x)\\) 在 \\([-a,a]\\) 上连续且为奇函数，则 \\(\\int_{-a}^{a} f(x)\\,dx = 0\\)。","ans":"√","sol":"<p>\\(\\int_{-a}^{0} f(x)dx = -\\int_0^{a} f(x)dx\\)，两者相抵，积分为 0。</p>","id":"j26"},{"ty":"judge","ch":5,"kp":"可积性","src":"教材经典","diff":1,"q":"若 \\(f(x)\\) 在 \\([a,b]\\) 上连续，则 \\(f(x)\\) 在 \\([a,b]\\) 上一定可积。","ans":"√","sol":"<p>闭区间上的连续函数必可积，这是定积分存在定理的基本结论。</p>","id":"j27"},{"ty":"judge","ch":5,"kp":"反常积分","src":"教材经典","diff":2,"q":"反常积分 \\(\\int_1^{+\\infty} \\dfrac{1}{x^2}\\,dx\\) 收敛。","ans":"√","sol":"<p>\\(\\int_1^{+\\infty}\\dfrac{dx}{x^2} = \\left[-\\dfrac{1}{x}\\right]_1^{+\\infty} = 0-(-1) = 1\\)，收敛。</p>","id":"j28"},{"ty":"judge","ch":5,"kp":"奇偶对称性","src":"真题改编","diff":1,"q":"\\(\\int_{-\\pi}^{\\pi} \\sin x\\,dx = 0\\)。","ans":"√","sol":"<p>\\(\\sin x\\) 是奇函数，在对称区间 \\([-\\pi,\\pi]\\) 上的积分为 0。</p>","id":"j29"},{"ty":"judge","ch":5,"kp":"变限积分","src":"真题改编","diff":1,"q":"若 \\(a, b\\) 为常数，则 \\(\\dfrac{d}{dx}\\int_a^b f(x)\\,dx = f(x)\\)。","ans":"×","sol":"<p>\\(\\int_a^b f(x)dx\\) 是定积分，结果为常数，对 \\(x\\) 求导得 0。应是变限积分 \\(\\dfrac{d}{dx}\\int_a^x f(t)dt = f(x)\\)。</p>","id":"j30"},{"ty":"judge","ch":6,"kp":"曲边梯形面积","src":"教材经典","diff":1,"q":"由曲线 \\(y=f(x)\\,(f(x)\\ge 0)\\)、直线 \\(x=a\\)、\\(x=b\\) 与 \\(x\\) 轴围成的曲边梯形面积为 \\(S=\\int_a^b f(x)\\,dx\\)。","ans":"√","sol":"<p>这正是定积分的几何意义（\\(f(x)\\ge 0\\) 时面积等于定积分）。</p>","id":"j31"},{"ty":"judge","ch":6,"kp":"平面图形面积","src":"教材经典","diff":1,"q":"由曲线 \\(y=x^2\\) 与直线 \\(y=x\\) 围成图形的面积为 \\(\\int_0^1 (x-x^2)\\,dx = \\dfrac{1}{6}\\)。","ans":"√","sol":"<p>两曲线交于 \\((0,0)\\)、\\((1,1)\\)，在 \\([0,1]\\) 上 \\(x\\ge x^2\\)，故 \\(S=\\dfrac{1}{2}-\\dfrac{1}{3}=\\dfrac{1}{6}\\)。</p>","id":"j32"},{"ty":"judge","ch":6,"kp":"弧长公式","src":"教材经典","diff":1,"q":"曲线 \\(y=f(x)\\) 在 \\([a,b]\\) 上的弧长公式为 \\(s=\\int_a^b \\sqrt{1+f'(x)^2}\\,dx\\)。","ans":"√","sol":"<p>弧微分 \\(ds=\\sqrt{1+(y')^2}\\,dx\\)，积分即得弧长公式。</p>","id":"j33"},{"ty":"judge","ch":6,"kp":"极坐标面积","src":"教材经典","diff":2,"q":"极坐标下曲边扇形面积公式为 \\(S=\\dfrac{1}{2}\\int_{\\alpha}^{\\beta} r(\\theta)\\,d\\theta\\)。","ans":"×","sol":"<p>正确公式为 \\(S=\\dfrac{1}{2}\\int_{\\alpha}^{\\beta} r^2(\\theta)\\,d\\theta\\)，被积函数是 \\(r\\) 的平方。</p>","id":"j34"},{"ty":"judge","ch":6,"kp":"旋转体体积","src":"真题改编","diff":2,"q":"曲线 \\(y=x^2\\) 在 \\([0,1]\\) 上绕 \\(x\\) 轴旋转一周所得旋转体体积为 \\(\\dfrac{\\pi}{4}\\)。","ans":"×","sol":"<p>应为 \\(V=\\pi\\int_0^1 (x^2)^2 dx = \\pi\\int_0^1 x^4 dx = \\dfrac{\\pi}{5}\\)，不是 \\(\\dfrac{\\pi}{4}\\)。</p>","id":"j35"},{"ty":"judge","ch":6,"kp":"柱壳法","src":"吉米多维奇精选","diff":2,"q":"由 \\(0\\le y\\le g(x)\\)、\\(a\\le x\\le b\\)（\\(0\\le a&lt;b\\)）确定的平面图形绕 \\(y\\) 轴旋转所得体积可用柱壳法 \\(V=2\\pi\\int_a^b x\\,g(x)\\,dx\\) 计算。","ans":"√","sol":"<p>取竖条为薄壳，半径 \\(x\\)、高 \\(g(x)\\)、厚 \\(dx\\)，壳体积 \\(2\\pi x\\,g(x)\\,dx\\)，积分即得。</p>","id":"j36"},{"ty":"judge","ch":7,"kp":"二阶齐次方程","src":"教材经典","diff":1,"q":"微分方程 \\(y''+y=0\\) 的通解是 \\(y=C_1\\cos x + C_2\\sin x\\)。","ans":"√","sol":"<p>特征方程 \\(r^2+1=0\\)，\\(r=\\pm i\\)，通解 \\(y=C_1\\cos x+C_2\\sin x\\)。</p>","id":"j37"},{"ty":"judge","ch":7,"kp":"初值问题","src":"教材经典","diff":1,"q":"微分方程 \\(y'=2x\\) 满足 \\(y(0)=0\\) 的特解是 \\(y=x^2\\)。","ans":"√","sol":"<p>积分得 \\(y=x^2+C\\)，代入 \\(y(0)=0\\) 得 \\(C=0\\)。</p>","id":"j38"},{"ty":"judge","ch":7,"kp":"可分离变量","src":"教材经典","diff":1,"q":"方程 \\(\\dfrac{dy}{dx}=\\dfrac{y}{x}\\) 的通解为 \\(y=Cx\\)。","ans":"√","sol":"<p>分离变量 \\(\\dfrac{dy}{y}=\\dfrac{dx}{x}\\)，积分得 \\(\\ln|y|=\\ln|x|+C_1\\)，即 \\(y=Cx\\)。</p>","id":"j39"},{"ty":"judge","ch":7,"kp":"解的结构","src":"教材经典","diff":2,"q":"若 \\(y_1, y_2\\) 是二阶齐次线性微分方程的两个解，则 \\(y=C_1y_1+C_2y_2\\)（\\(C_1,C_2\\) 为任意常数）一定是该方程的通解。","ans":"×","sol":"<p>还需 \\(y_1, y_2\\) 线性无关，否则两个解成比例，\\(y\\) 实质上只含一个任意常数，不是通解。</p>","id":"j40"},{"ty":"judge","ch":7,"kp":"特征方程","src":"真题改编","diff":1,"q":"方程 \\(y''-2y'+y=0\\) 的特征方程有两个不相等的实根。","ans":"×","sol":"<p>特征方程 \\(r^2-2r+1=0\\)，即 \\((r-1)^2=0\\)，\\(r=1\\) 为二重根。</p>","id":"j41"},{"ty":"judge","ch":7,"kp":"待定特解","src":"真题改编","diff":2,"q":"方程 \\(y''+4y=e^x\\) 的特解可设为 \\(y^*=ae^x\\)。","ans":"√","sol":"<p>\\(\\lambda=1\\) 不是特征根（特征根为 \\(\\pm 2i\\)），故可设 \\(y^*=ae^x\\)。代入得 \\(a(1+4)=1\\)，\\(a=\\dfrac{1}{5}\\)。</p>","id":"j42"},{"ty":"judge","ch":8,"kp":"向量数量积","src":"教材经典","diff":1,"q":"若 \\(\\vec{a}\\cdot\\vec{b}=0\\)，则必有 \\(\\vec{a}\\perp\\vec{b}\\)。","ans":"×","sol":"<p>当 \\(\\vec{a},\\vec{b}\\) 均为非零向量时才有此结论；零向量与任何向量的数量积为 0，但谈不上垂直。</p>","id":"j43"},{"ty":"judge","ch":8,"kp":"向量向量积","src":"教材经典","diff":1,"q":"\\(\\vec{a}\\times\\vec{b}\\) 是与 \\(\\vec{a}\\)、\\(\\vec{b}\\) 都垂直的向量。","ans":"√","sol":"<p>向量积 \\(\\vec{a}\\times\\vec{b}\\) 的方向按右手法则垂直于 \\(\\vec{a}\\) 与 \\(\\vec{b}\\) 所确定的平面。</p>","id":"j44"},{"ty":"judge","ch":8,"kp":"单位向量","src":"教材经典","diff":1,"q":"若 \\((x,y,z)\\) 是单位向量的坐标，则 \\(x^2+y^2+z^2=1\\)。","ans":"√","sol":"<p>单位向量模长为 1，即 \\(\\sqrt{x^2+y^2+z^2}=1\\)。</p>","id":"j45"},{"ty":"judge","ch":8,"kp":"混合积","src":"教材经典","diff":1,"q":"三个非零向量 \\(\\vec{a},\\vec{b},\\vec{c}\\) 共面的充要条件是混合积 \\([\\vec{a}\\,\\vec{b}\\,\\vec{c}]=0\\)。","ans":"√","sol":"<p>混合积的绝对值等于以三向量为棱的平行六面体体积，共面时体积为 0。</p>","id":"j46"},{"ty":"judge","ch":8,"kp":"直线与平面","src":"真题改编","diff":2,"q":"若直线的方向向量与某平面的法向量平行，则该直线与平面垂直。","ans":"√","sol":"<p>方向向量平行于法向量，说明直线沿法线方向进入平面，即直线与平面垂直。</p>","id":"j47"},{"ty":"judge","ch":8,"kp":"平面位置关系","src":"真题改编","diff":2,"q":"两平面 \\(A_1x+B_1y+C_1z+D_1=0\\) 与 \\(A_2x+B_2y+C_2z+D_2=0\\) 平行的充要条件是 \\(\\dfrac{A_1}{A_2}=\\dfrac{B_1}{B_2}=\\dfrac{C_1}{C_2}=\\dfrac{D_1}{D_2}\\)。","ans":"×","sol":"<p>平行的充要条件只是 \\(\\dfrac{A_1}{A_2}=\\dfrac{B_1}{B_2}=\\dfrac{C_1}{C_2}\\)；若连 \\(D_1:D_2\\) 也相等则两平面重合。</p>","id":"j48"},{"ty":"judge","ch":9,"kp":"可微充分条件","src":"教材经典","diff":1,"q":"若函数 \\(z=f(x,y)\\) 的两个偏导数 \\(f_x, f_y\\) 在点 \\((x_0,y_0)\\) 处连续，则 \\(f\\) 在该点可微。","ans":"√","sol":"<p>偏导数连续是可微的充分条件，这是判定可微性的常用定理。</p>","id":"j49"},{"ty":"judge","ch":9,"kp":"驻点与极值","src":"教材经典","diff":1,"q":"函数 \\(z=f(x,y)\\) 的驻点一定是极值点。","ans":"×","sol":"<p>反例：\\(z=xy\\) 在 \\((0,0)\\) 处 \\(z_x=z_y=0\\) 是驻点，但 \\(f(x,x)=x^2>0\\)，\\(f(x,-x)=-x^2<0\\)，原点不是极值点（马鞍点）。</p>","id":"j50"},{"ty":"judge","ch":9,"kp":"可微的性质","src":"教材经典","diff":1,"q":"若 \\(z=f(x,y)\\) 在点 \\((x_0,y_0)\\) 处可微，则 \\(f\\) 在该点必连续，且两个偏导数必存在。","ans":"√","sol":"<p>可微 ⇒ 连续且偏导存在，且 \\(dz=f_x\\,dx+f_y\\,dy\\)。注意反之均不成立。</p>","id":"j51"},{"ty":"judge","ch":9,"kp":"条件极值","src":"教材经典","diff":2,"q":"用拉格朗日乘数法求得的驻点一定是目标函数的条件极值点。","ans":"×","sol":"<p>拉格朗日乘数法只给出条件极值的候选点（必要条件），该驻点是否为极值点还需结合实际问题意义或进一步判别。</p>","id":"j52"},{"ty":"judge","ch":9,"kp":"偏导与连续","src":"真题改编","diff":2,"q":"若 \\(f_x(x_0,y_0)\\) 与 \\(f_y(x_0,y_0)\\) 都存在，则 \\(f\\) 在点 \\((x_0,y_0)\\) 处必连续。","ans":"×","sol":"<p>反例：\\(f(x,y)=\\dfrac{xy}{x^2+y^2}\\)（补充定义 \\(f(0,0)=0\\)），在原点两偏导数均为 0，但 \\(\\lim\\limits_{(x,y)\\to(0,0)}f(x,y)\\) 不存在。多元函数偏导数存在推不出连续，与一元情形不同。</p>","id":"j53"},{"ty":"judge","ch":9,"kp":"方向导数","src":"真题改编","diff":2,"q":"若 \\(f(x,y)\\) 在点 \\(P_0\\) 处可微，则它在 \\(P_0\\) 处沿任一方向 \\(\\boldsymbol{l}\\) 的方向导数都存在，且 \\(\\dfrac{\\partial f}{\\partial l}=f_x\\cos\\alpha+f_y\\cos\\beta\\)，其中 \\((\\cos\\alpha,\\cos\\beta)\\) 为 \\(\\boldsymbol{l}\\) 的方向余弦。","ans":"√","sol":"<p>可微保证沿任意方向的方向导数存在，且 \\(\\dfrac{\\partial f}{\\partial l}=\\operatorname{grad}f\\cdot\\boldsymbol{e}_l\\)。</p>","id":"j54"},{"ty":"judge","ch":10,"kp":"对称性","src":"教材经典","diff":1,"q":"设闭区域 \\(D\\) 关于 \\(y\\) 轴对称，若被积函数 \\(f(x,y)\\) 关于 \\(x\\) 为奇函数，则 \\(\\displaystyle\\iint_D f(x,y)\\,d\\sigma=0\\)。","ans":"√","sol":"<p>左右两半区域上的积分互相抵消，这是二重积分对称性的基本结论。</p>","id":"j55"},{"ty":"judge","ch":10,"kp":"比较定理","src":"教材经典","diff":1,"q":"若 \\(f, g\\) 在 \\(D\\) 上连续且 \\(f(x,y)\\le g(x,y)\\)，则 \\(\\displaystyle\\iint_D f\\,d\\sigma\\le\\iint_D g\\,d\\sigma\\)。","ans":"√","sol":"<p>这就是二重积分的比较（保序）性质，可直接用于积分值的估计。</p>","id":"j56"},{"ty":"judge","ch":10,"kp":"几何意义","src":"教材经典","diff":1,"q":"当 \\(f(x,y)\\ge 0\\) 时，\\(\\displaystyle\\iint_D f(x,y)\\,d\\sigma\\) 表示以 \\(D\\) 为底、曲面 \\(z=f(x,y)\\) 为顶的曲顶柱体的体积。","ans":"√","sol":"<p>这正是二重积分的几何意义；\\(f\\) 变号时积分表示体积的代数和。</p>","id":"j57"},{"ty":"judge","ch":10,"kp":"积分意义","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\iint_D d\\sigma\\) 等于闭区域 \\(D\\) 的面积。","ans":"√","sol":"<p>被积函数恒为 1，积分即为区域的测度（面积）。</p>","id":"j58"},{"ty":"judge","ch":10,"kp":"极坐标面积元","src":"真题改编","diff":1,"q":"在极坐标系中，面积元素为 \\(d\\sigma=dr\\,d\\theta\\)。","ans":"×","sol":"<p>极坐标变换 \\(x=r\\cos\\theta,\\ y=r\\sin\\theta\\) 的雅可比行列式为 \\(r\\)，故面积元素 \\(d\\sigma=r\\,dr\\,d\\theta\\)，漏掉因子 \\(r\\) 是常见错误。</p>","id":"j59"},{"ty":"judge","ch":10,"kp":"积分为零","src":"真题改编","diff":3,"q":"若 \\(f\\) 在 \\(D\\) 上可积且 \\(\\displaystyle\\iint_D f\\,d\\sigma=0\\)，则必有 \\(f\\) 在 \\(D\\) 上恒为零。","ans":"×","sol":"<p>\\(f\\) 不连续时结论不真：例如 \\(f\\) 仅在 \\(D\\) 内一条线段上取值 1、其余处为 0，积分显然为 0 但 \\(f\\not\\equiv 0\\)。只有 \\(f\\) 连续时才能由积分为零推出 \\(f\\equiv 0\\)。</p>","id":"j60"},{"ty":"judge","ch":11,"kp":"第一类线积分","src":"教材经典","diff":1,"q":"对弧长的曲线积分 \\(\\displaystyle\\int_{L} f(x,y)\\,ds\\) 的值与曲线 \\(L\\) 的方向（起点到终点）无关。","ans":"√","sol":"<p>第一类曲线积分是对弧长的积分，\\(ds\\) 不因方向改变而变号，与方向无关；这是与第二类曲线积分的本质区别。</p>","id":"j61"},{"ty":"judge","ch":11,"kp":"两类线积分","src":"教材经典","diff":2,"q":"对坐标的曲线积分当曲线方向反向时积分值变号，而对弧长的曲线积分不变号。","ans":"√","sol":"<p>\\(\\displaystyle\\int_{L^-}P\\,dx+Q\\,dy=-\\int_{L^+}P\\,dx+Q\\,dy\\)，而 \\(\\displaystyle\\int_{L^-}f\\,ds=\\int_{L^+}f\\,ds\\)。</p>","id":"j62"},{"ty":"judge","ch":11,"kp":"两类线积分","src":"教材经典","diff":2,"q":"设 \\(L\\) 为光滑曲线且取定方向，\\((\\cos\\alpha,\\cos\\beta)\\) 为其单位切向量的方向余弦，则 \\(\\displaystyle\\int_L P\\,dx+Q\\,dy=\\int_L (P\\cos\\alpha+Q\\cos\\beta)\\,ds\\)。","ans":"√","sol":"<p>这是两类曲线积分之间的联系，本质是 \\(dx=\\cos\\alpha\\,ds,\\ dy=\\cos\\beta\\,ds\\)。</p>","id":"j63"},{"ty":"judge","ch":11,"kp":"曲面积分与侧","src":"教材经典","diff":1,"q":"第一类曲面积分 \\(\\displaystyle\\iint_\\Sigma f(x,y,z)\\,dS\\) 与曲面选取的侧无关，而第二类曲面积分改变曲面的侧时变号。","ans":"√","sol":"<p>\\(dS\\) 是面积元素恒正；\\(d y\\,dz,\\ d z\\,dx,\\ dx\\,dy\\) 等带有符号，与法向量指向有关，故改变侧积分变号。</p>","id":"j64"},{"ty":"judge","ch":11,"kp":"高斯公式","src":"教材经典","diff":2,"q":"高斯公式中 \\(\\Sigma\\) 必须是空间闭区域 \\(\\Omega\\) 的整个边界曲面，且取外侧。","ans":"√","sol":"<p>若 \\(\\Sigma\\) 不封闭，需添加辅助面使其封闭；取内侧时公式要添负号。条件不满足时不能直接套用。</p>","id":"j65"},{"ty":"judge","ch":11,"kp":"路径无关","src":"真题改编","diff":3,"q":"若 \\(\\dfrac{\\partial P}{\\partial y}=\\dfrac{\\partial Q}{\\partial x}\\) 在区域 \\(D\\) 内处处成立，则对 \\(D\\) 内任意分段光滑闭曲线 \\(C\\) 都有 \\(\\displaystyle\\oint_C P\\,dx+Q\\,dy=0\\)。","ans":"×","sol":"<p>还要求 \\(D\\) 是单连通区域。反例：\\(P=-\\dfrac{y}{x^2+y^2},\\ Q=\\dfrac{x}{x^2+y^2}\\) 在圆环域内满足条件，但沿围绕原点的正向圆周积分等于 \\(2\\pi\\ne 0\\)。</p>","id":"j66"},{"ty":"judge","ch":12,"kp":"条件收敛","src":"教材经典","diff":1,"q":"级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{(-1)^n}{\\sqrt n}\\) 条件收敛，但不绝对收敛。","ans":"√","sol":"<p>由莱布尼茨判别法它收敛；而 \\(\\sum\\dfrac{1}{\\sqrt n}\\) 是 \\(p=\\dfrac12\\le1\\) 的 \\(p\\)-级数，发散，故不绝对收敛。</p>","id":"j67"},{"ty":"judge","ch":12,"kp":"级数性质","src":"教材经典","diff":2,"q":"收敛级数任意加括号后所得级数仍收敛，且其和不变。","ans":"√","sol":"<p>加括号后的部分和数列是原部分和数列的子列，故收敛到同一和。注意其逆不真。</p>","id":"j68"},{"ty":"judge","ch":12,"kp":"逐项求导","src":"教材经典","diff":2,"q":"若幂级数 \\(\\sum a_n x^n\\) 的收敛半径为 \\(R\\)，则逐项求导、逐项积分后所得幂级数的收敛半径仍为 \\(R\\)。","ans":"√","sol":"<p>逐项求导与逐项积分不改变收敛半径，只可能改变区间端点处的收敛性。</p>","id":"j69"},{"ty":"judge","ch":12,"kp":"比值判别法","src":"教材经典","diff":1,"q":"若 \\(u_n>0\\) 且 \\(\\displaystyle\\lim_{n\\to\\infty}\\dfrac{u_{n+1}}{u_n}=\\rho>1\\)，则 \\(\\sum u_n\\) 发散。","ans":"√","sol":"<p>此时从某项起 \\(u_{n+1}>u_n\\)，通项不趋于 0，违反收敛必要条件，故发散。</p>","id":"j70"},{"ty":"judge","ch":12,"kp":"级数性质","src":"真题改编","diff":2,"q":"若 \\(\\displaystyle\\sum_{n=1}^{\\infty}a_n\\) 收敛，则 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\left(a_n+\\dfrac{1}{n}\\right)\\) 也收敛。","ans":"×","sol":"<p>若新级数收敛，与收敛级数 \\(\\sum a_n\\) 逐项相减得 \\(\\sum\\dfrac1n\\) 收敛，矛盾。故新级数必发散。</p>","id":"j71"},{"ty":"judge","ch":12,"kp":"级数性质","src":"真题改编","diff":2,"q":"若级数加括号后所得级数收敛，则原级数必收敛。","ans":"×","sol":"<p>反例：\\(1-1+1-1+\\cdots\\) 发散，但按两项加括号得 \\((1-1)+(1-1)+\\cdots=0\\) 收敛。</p>","id":"j72"}];

window.XDBANK_OBJ.choice = [{"ty":"choice","ch":1,"kp":"极限计算","src":"小测第一单元","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{x^{2}\\sin\\dfrac{1}{x}}{|\\sin x|}=\\)（　　）","opts":["0","1","-1","不存在"],"ans":0,"sol":"\\(\\left|x^2\\sin\\frac{1}{x}\\right|\\le x^2\\)，而 \\(|\\sin x|\\sim|x|\\)，故 \\(0\\le\\left|\\dfrac{x^2\\sin\\frac1x}{|\\sin x|}\\right|\\le\\dfrac{x^2}{|\\sin x|}\\to 0\\)，由夹逼准则极限为 0。选 A。","id":"c1"},{"ty":"choice","ch":1,"kp":"数列极限","src":"小测第一单元","diff":2,"q":"\\(\\lim\\limits_{n\\to\\infty}\\sqrt{n}\\left(\\sqrt{n+2}-\\sqrt{n+1}\\right)=\\)（　　）","opts":["1","0","-1","\\(\\dfrac{1}{2}\\)"],"ans":3,"sol":"有理化：原式 \\(=\\dfrac{\\sqrt{n}}{\\sqrt{n+2}+\\sqrt{n+1}}=\\dfrac{1}{\\sqrt{1+\\frac{2}{n}}+\\sqrt{1+\\frac{1}{n}}}\\to\\dfrac{1}{2}\\)。选 D。","id":"c2"},{"ty":"choice","ch":1,"kp":"等价无穷小","src":"小测第一单元","diff":2,"q":"若 \\(\\lim\\limits_{x\\to 0}\\dfrac{\\varphi(x)}{\\sin x}=1\\)，则当 \\(x\\to 0\\) 时，函数 \\(\\varphi(x)\\) 与（　　）是等价无穷小。","opts":["\\(\\sin|x|\\)","\\(\\ln(1-x)\\)","\\(1-\\cos\\sqrt{|x|}\\)","\\(\\sqrt{1+2x}-1\\)"],"ans":3,"sol":"由条件 \\(\\varphi(x)\\sim\\sin x\\sim x\\)。A：\\(\\sin|x|\\ge 0\\) 与 \\(\\sin x\\) 符号不统一，比值无极限；B：\\(\\ln(1-x)\\sim-x\\)；C：\\(1-\\cos\\sqrt{|x|}\\sim\\dfrac{|x|}{2}\\)；D：\\(\\sqrt{1+2x}-1\\sim x\\)。选 D。","id":"c3"},{"ty":"choice","ch":1,"kp":"间断点","src":"小测第一单元","diff":2,"q":"函数 \\(f(x)=\\lim\\limits_{n\\to\\infty}\\dfrac{\\sin\\pi x}{1+(2x)^{2n}}\\) 的间断点有（　　）个。","opts":["4","3","2","1"],"ans":2,"sol":"\\(|x|<\\dfrac12\\) 时 \\(f=\\sin\\pi x\\)；\\(|x|>\\dfrac12\\) 时 \\(f=0\\)；\\(x=\\pm\\dfrac12\\) 时分母 \\(=2\\)，\\(f=\\pm\\dfrac12\\)。在 \\(x=\\dfrac12\\) 处左极限 1、右极限 0，在 \\(x=-\\dfrac12\\) 处左极限 0、右极限 \\(-1\\)，均为跳跃间断点，共 2 个。选 C。","id":"c4"},{"ty":"choice","ch":1,"kp":"无穷小性质","src":"小测第一单元","diff":1,"q":"\\(\\lim\\limits_{x\\to\\infty}\\dfrac{3\\sin x}{x^{2}}=\\)（　　）","opts":["-3","0","3","不存在"],"ans":1,"sol":"\\(x^2\\to\\infty\\) 为无穷大，\\(3\\sin x\\) 为有界变量，无穷大乘有界变量仍是无穷小，极限为 0。选 B。","id":"c5"},{"ty":"choice","ch":1,"kp":"极限计算","src":"小测第一单元","diff":1,"q":"\\(\\lim\\limits_{x\\to 7}\\dfrac{x^{2}-3x-28}{x^{2}-5x-14}=\\)（　　）","opts":["\\(\\dfrac{11}{9}\\)","0","2","4"],"ans":0,"sol":"分子 \\(=(x-7)(x+4)\\)，分母 \\(=(x-7)(x+2)\\)，约去 \\(x-7\\) 得 \\(\\dfrac{x+4}{x+2}=\\dfrac{11}{9}\\)。选 A。","id":"c6"},{"ty":"choice","ch":1,"kp":"无穷小概念","src":"小测第一单元","diff":1,"q":"当 \\(x\\to 0\\) 时，下列变量中是无穷小量的是（　　）","opts":["\\(\\sin\\dfrac{1}{x}\\)","\\(\\dfrac{\\sin x}{x}\\)","\\(2^{-x}-1\\)","\\(\\ln|x|\\)"],"ans":2,"sol":"A 振荡无极限；B 趋于 1；C \\(=e^{-x\\ln 2}-1\\sim -x\\ln 2\\to 0\\) 是无穷小；D \\(\\to-\\infty\\)。选 C。","id":"c7"},{"ty":"choice","ch":1,"kp":"无穷大运算","src":"小测第一单元","diff":2,"q":"如果 \\(\\lim\\limits_{x\\to x_0}f(x)=\\infty\\)，\\(\\lim\\limits_{x\\to x_0}g(x)=\\infty\\)，则必有（　　）","opts":["\\(\\lim[f(x)+g(x)]=\\infty\\)","\\(\\lim[f(x)-g(x)]=0\\)","\\(\\lim\\dfrac{1}{f(x)+g(x)}=0\\)","\\(\\lim kf(x)=\\infty\\)（\\(k\\) 为非零常数）"],"ans":3,"sol":"\\(\\infty\\pm\\infty\\) 是未定式，A、B、C 未必成立（如 \\(g(x)=-f(x)\\) 时 \\(f+g=0\\)）。而 \\(|kf(x)|=|k|\\cdot|f(x)|\\to\\infty\\)，D 必成立。选 D。","id":"c8"},{"ty":"choice","ch":1,"kp":"重要极限","src":"小测第一单元","diff":1,"q":"\\(\\lim\\limits_{x\\to 1}\\dfrac{\\sin(x-1)}{x^{2}-1}=\\)（　　）","opts":["1","2","0","\\(\\dfrac{1}{2}\\)"],"ans":3,"sol":"\\(\\sin(x-1)\\sim x-1\\)，原式 \\(=\\lim\\limits_{x\\to1}\\dfrac{x-1}{(x-1)(x+1)}=\\dfrac{1}{2}\\)。选 D。","id":"c9"},{"ty":"choice","ch":1,"kp":"重要极限","src":"小测第一单元","diff":2,"q":"下列等式中成立的是（　　）","opts":["\\(\\lim\\limits_{n\\to\\infty}\\left(1+\\dfrac{2}{n}\\right)^{n}=e\\)","\\(\\lim\\limits_{n\\to\\infty}\\left(1+\\dfrac{1}{n}\\right)^{n+2}=e\\)","\\(\\lim\\limits_{n\\to\\infty}\\left(1+\\dfrac{1}{2n}\\right)^{n}=e\\)","\\(\\lim\\limits_{n\\to\\infty}\\left(1+\\dfrac{1}{n}\\right)^{2n}=e\\)"],"ans":1,"sol":"B：\\(\\left(1+\\frac1n\\right)^{n+2}=\\left(1+\\frac1n\\right)^{n}\\left(1+\\frac1n\\right)^2\\to e\\)。A 趋于 \\(e^2\\)，C 趋于 \\(e^{1/2}\\)，D 趋于 \\(e^2\\)。选 B。","id":"c10"},{"ty":"choice","ch":1,"kp":"极限计算","src":"小测第二三单元","diff":1,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{\\sin x-x}{x\\cos x-1}=\\)（　　）","opts":["1","不存在","0","\\(\\infty\\)"],"ans":2,"sol":"分子 \\(\\sin x-x\\sim-\\dfrac{x^3}{6}\\to 0\\)；分母 \\(x\\cos x-1\\to-1\\ne 0\\)。非未定式，极限 \\(=\\dfrac{0}{-1}=0\\)。（洛必达验证：\\(\\dfrac{\\cos x-1}{\\cos x-x\\sin x}\\to\\dfrac{0}{-1}=0\\)。）选 C。","id":"c11"},{"ty":"choice","ch":1,"kp":"无穷小阶数","src":"教材经典","diff":2,"q":"当 \\(x\\to 0\\) 时，\\(x-\\sin x\\) 是 \\(x\\) 的（　　）阶无穷小。","opts":["一","二","三","四"],"ans":2,"sol":"由泰勒公式 \\(\\sin x=x-\\dfrac{x^3}{6}+o(x^3)\\)，故 \\(x-\\sin x\\sim\\dfrac{x^3}{6}\\)，为三阶无穷小。选 C。","id":"c12"},{"ty":"choice","ch":1,"kp":"间断点分类","src":"教材经典","diff":1,"q":"\\(\\lim\\limits_{x\\to 0}x\\sin\\dfrac{1}{x}=0\\)，故 \\(x=0\\) 是 \\(f(x)=x\\sin\\dfrac{1}{x}\\) 的（　　）","opts":["可去间断点","跳跃间断点","振荡间断点","连续点"],"ans":0,"sol":"\\(f\\) 在 \\(x=0\\) 处无定义但极限存在（为 0），补充定义 \\(f(0)=0\\) 后即连续，故 \\(x=0\\) 是可去间断点（第一类）。选 A。","id":"c13"},{"ty":"choice","ch":1,"kp":"间断点分类","src":"真题改编","diff":2,"q":"函数 \\(f(x)=e^{1/x}\\) 在 \\(x=0\\) 处（　　）","opts":["极限存在","是可去间断点","是第二类间断点","是第一类间断点"],"ans":2,"sol":"\\(x\\to 0^+\\) 时 \\(e^{1/x}\\to+\\infty\\)，\\(x\\to 0^-\\) 时 \\(e^{1/x}\\to 0\\)。右极限为无穷大，属第二类（无穷）间断点。选 C。","id":"c14"},{"ty":"choice","ch":1,"kp":"连续与极限","src":"真题改编","diff":2,"q":"设 \\(f(x)\\) 在 \\(x=0\\) 处连续，且 \\(\\lim\\limits_{x\\to 0}\\dfrac{f(x)}{x}=2\\)，则 \\(f(0)=\\)（　　）","opts":["0","1","2","不存在"],"ans":0,"sol":"分母 \\(x\\to 0\\) 而比值极限存在，故必有 \\(f(x)\\to 0\\)；又 \\(f\\) 在 \\(x=0\\) 连续，得 \\(f(0)=0\\)。（进而 \\(f'(0)=\\lim\\dfrac{f(x)-f(0)}{x}=2\\)。）选 A。","id":"c15"},{"ty":"choice","ch":1,"kp":"等价无穷小","src":"吉米多维奇精选","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{\\tan x-\\sin x}{x^{3}}=\\)（　　）","opts":["0","\\(\\dfrac{1}{2}\\)","1","\\(\\infty\\)"],"ans":1,"sol":"\\(\\tan x-\\sin x=\\tan x(1-\\cos x)\\sim x\\cdot\\dfrac{x^2}{2}=\\dfrac{x^3}{2}\\)，极限为 \\(\\dfrac12\\)。注意不能直接把 \\(\\tan x\\sim x\\)、\\(\\sin x\\sim x\\) 相减得 0。选 B。","id":"c16"},{"ty":"choice","ch":1,"kp":"指数极限","src":"吉米多维奇精选","diff":2,"q":"\\(\\lim\\limits_{x\\to 0^{+}}x^{x}=\\)（　　）","opts":["0","1","\\(e\\)","不存在"],"ans":1,"sol":"\\(x^x=e^{x\\ln x}\\)，而 \\(x\\ln x=\\dfrac{\\ln x}{1/x}\\xrightarrow{\\text{洛必达}}\\dfrac{1/x}{-1/x^2}=-x\\to 0\\)，故原极限 \\(=e^0=1\\)。选 B。","id":"c17"},{"ty":"choice","ch":2,"kp":"导数定义","src":"小测第二三单元","diff":2,"q":"设 \\(f'(x_0)\\) 存在，则 \\(\\lim\\limits_{h\\to 0}\\dfrac{f(x_0+h)-f(x_0-2h)}{h}=\\)（　　）","opts":["\\(3f'(x_0)\\)","\\(2f'(x_0)\\)","\\(f'(x_0)\\)","\\(-3f'(x_0)\\)"],"ans":0,"sol":"原式 \\(=\\dfrac{f(x_0+h)-f(x_0)}{h}+\\dfrac{f(x_0)-f(x_0-2h)}{h}\\)，后项 \\(=2\\cdot\\dfrac{f(x_0-2h+2h)-f(x_0)}{2h}\\to 2f'(x_0)\\)，合计 \\(3f'(x_0)\\)。选 A。","id":"c18"},{"ty":"choice","ch":2,"kp":"导数计算","src":"小测第二三单元","diff":1,"q":"设 \\(f(x)=6\\sqrt{x}\\)，则 \\(f'(25)=\\)（　　）","opts":["\\(\\dfrac{3}{5}\\)","\\(\\dfrac{6}{25}\\)","\\(\\dfrac{6}{5}\\)","\\(\\dfrac{3}{25}\\)"],"ans":0,"sol":"\\(f'(x)=3x^{-1/2}=\\dfrac{3}{\\sqrt{x}}\\)，\\(f'(25)=\\dfrac{3}{5}\\)。选 A。","id":"c19"},{"ty":"choice","ch":2,"kp":"左右导数","src":"小测第二三单元","diff":3,"q":"设 \\(f(x)=\\begin{cases}\\dfrac{2x^{3}}{3}, & x\\le 1\\\\ x^{2}+1, & x>1\\end{cases}\\)，则 \\(f(x)\\) 在 \\(x=1\\) 处（　　）","opts":["左右导数都不存在","左导数不存在，右导数存在","左右导数都存在","左导数存在，右导数不存在"],"ans":3,"sol":"\\(f(1)=\\dfrac23\\)。左导数：\\(\\lim\\limits_{x\\to 1^-}\\dfrac{\\frac23x^3-\\frac23}{x-1}=\\dfrac23\\lim(x^2+x+1)=2\\) 存在；右差商：\\(\\dfrac{x^2+1-\\frac23}{x-1}=\\dfrac{x^2-\\frac13}{x-1}\\)，\\(x\\to 1^+\\) 时分子 \\(\\to\\dfrac23\\)、分母 \\(\\to 0^+\\)，趋于 \\(+\\infty\\)，右导数不存在。选 D。","id":"c20"},{"ty":"choice","ch":2,"kp":"隐函数求导","src":"小测第二三单元","diff":2,"q":"曲线 \\(x\\cos y+e^{y}=1\\) 在点 \\((0,0)\\) 处的切线方程为 \\(y=\\)（　　）","opts":["\\(2x\\)","\\(-x\\)","\\(x\\)","\\(-2x\\)"],"ans":1,"sol":"两边对 \\(x\\) 求导：\\(\\cos y-x\\sin y\\cdot y'+e^y y'=0\\)。代入 \\((0,0)\\)：\\(1+y'=0\\)，\\(y'=-1\\)，切线为 \\(y=-x\\)。选 B。","id":"c21"},{"ty":"choice","ch":2,"kp":"高阶导数","src":"小测第二三单元","diff":2,"q":"设 \\(y=x^{n}e^{3x}\\)（\\(n\\) 为正整数），则 \\(y^{(n)}(0)=\\)（　　）","opts":["\\(n!\\)","\\(n!\\cdot 3\\)","\\(n!\\cdot 3^{n}\\)","\\(n!\\cdot(-3)^{n}\\)"],"ans":0,"sol":"由莱布尼茨公式 \\(y^{(n)}=\\sum\\limits_{k=0}^{n}\\binom{n}{k}(x^n)^{(k)}(e^{3x})^{(n-k)}\\)，在 \\(x=0\\) 处仅 \\(k=n\\) 项非零：\\((x^n)^{(n)}=n!\\)，\\((e^{3x})^{(0)}\\big|_{x=0}=1\\)，故 \\(y^{(n)}(0)=n!\\)。<strong>注意：原小测判定答案 C（\\(n!\\cdot 3^n\\)）有误</strong>——若对 \\(e^{3x}\\) 求 \\(n\\) 阶得 \\(3^n\\)，则对应项含 \\((x^n)^{(0)}=x^n\\)，在 \\(x=0\\) 处为零。以 \\(n!\\) 为准。选 A。","id":"c22"},{"ty":"choice","ch":2,"kp":"导数计算","src":"小测第二三单元","diff":1,"q":"设 \\(f(x)=\\dfrac{1}{4x^{2}}\\)，则 \\(f'(2)=\\)（　　）","opts":["\\(-\\dfrac{1}{16}\\)","\\(\\dfrac{1}{16}\\)","\\(-\\dfrac{1}{8}\\)","\\(\\dfrac{1}{8}\\)"],"ans":0,"sol":"\\(f'(x)=-\\dfrac{1}{2}x^{-3}=-\\dfrac{1}{2x^3}\\)，\\(f'(2)=-\\dfrac{1}{16}\\)。选 A。","id":"c23"},{"ty":"choice","ch":2,"kp":"导数计算","src":"教材经典","diff":2,"q":"设 \\(y=\\ln\\left(x+\\sqrt{1+x^{2}}\\right)\\)，则 \\(y'=\\)（　　）","opts":["\\(\\dfrac{1}{\\sqrt{1+x^{2}}}\\)","\\(\\sqrt{1+x^{2}}\\)","\\(\\dfrac{1}{x+\\sqrt{1+x^{2}}}\\)","\\(\\dfrac{2x}{\\sqrt{1+x^{2}}}\\)"],"ans":0,"sol":"\\(y'=\\dfrac{1+\\frac{x}{\\sqrt{1+x^2}}}{x+\\sqrt{1+x^2}}=\\dfrac{1}{\\sqrt{1+x^2}}\\)。选 A。","id":"c24"},{"ty":"choice","ch":2,"kp":"切线方程","src":"教材经典","diff":1,"q":"抛物线 \\(y=x^{2}\\) 上切线平行于直线 \\(y=4x-1\\) 的点是（　　）","opts":["\\((2,4)\\)","\\((4,16)\\)","\\((1,1)\\)","\\((-2,4)\\)"],"ans":0,"sol":"\\(y'=2x=4\\) 得 \\(x=2\\)，\\(y=4\\)，该点为 \\((2,4)\\)。选 A。","id":"c25"},{"ty":"choice","ch":2,"kp":"微分","src":"教材经典","diff":2,"q":"函数 \\(y=e^{\\sqrt{x}}\\) 的微分 \\(dy=\\)（　　）","opts":["\\(e^{\\sqrt{x}}\\,dx\\)","\\(\\dfrac{e^{\\sqrt{x}}}{2\\sqrt{x}}\\,dx\\)","\\(\\dfrac{e^{\\sqrt{x}}}{\\sqrt{x}}\\,dx\\)","\\(\\dfrac{1}{2}e^{\\sqrt{x}}\\,dx\\)"],"ans":1,"sol":"\\(y'=e^{\\sqrt{x}}\\cdot\\dfrac{1}{2\\sqrt{x}}\\)，故 \\(dy=\\dfrac{e^{\\sqrt{x}}}{2\\sqrt{x}}\\,dx\\)（\\(x>0\\)）。选 B。","id":"c26"},{"ty":"choice","ch":2,"kp":"导数定义","src":"真题改编","diff":2,"q":"设 \\(f(x)\\) 在 \\(x=a\\) 处可导，则 \\(\\lim\\limits_{h\\to 0}\\dfrac{f(a+h)-f(a-3h)}{h}=\\)（　　）","opts":["\\(2f'(a)\\)","\\(3f'(a)\\)","\\(4f'(a)\\)","\\(f'(a)\\)"],"ans":2,"sol":"原式 \\(=\\dfrac{f(a+h)-f(a)}{h}+3\\cdot\\dfrac{f(a-3h+3h)-f(a)}{3h}\\to f'(a)+3f'(a)=4f'(a)\\)。选 C。","id":"c27"},{"ty":"choice","ch":2,"kp":"隐函数求导","src":"真题改编","diff":2,"q":"方程 \\(e^{y}+xy=e\\) 确定 \\(y=y(x)\\)，则 \\(y'(0)=\\)（　　）","opts":["\\(-\\dfrac{1}{e}\\)","\\(\\dfrac{1}{e}\\)","\\(-e\\)","\\(e\\)"],"ans":0,"sol":"\\(x=0\\) 时 \\(e^{y}=e\\)，\\(y=1\\)。方程两边对 \\(x\\) 求导：\\(e^y y'+y+xy'=0\\)，代入得 \\(e\\cdot y'+1=0\\)，\\(y'=-\\dfrac{1}{e}\\)。选 A。","id":"c28"},{"ty":"choice","ch":2,"kp":"导数定义","src":"吉米多维奇精选","diff":2,"q":"设 \\(f(x)=\\begin{cases}x^{2}\\sin\\dfrac{1}{x}, & x\\ne 0,\\\\ 0, & x=0,\\end{cases}\\) 则 \\(f'(0)=\\)（　　）","opts":["0","1","不存在","极限不存在"],"ans":0,"sol":"\\(f'(0)=\\lim\\limits_{x\\to0}\\dfrac{x^2\\sin\\frac1x-0}{x}=\\lim\\limits_{x\\to0}x\\sin\\dfrac{1}{x}=0\\)（无穷小乘有界变量），故 \\(f\\) 在 \\(x=0\\) 处可导且 \\(f'(0)=0\\)。选 A。","id":"c29"},{"ty":"choice","ch":3,"kp":"拐点","src":"小测第二三单元","diff":2,"q":"设 \\(y=x^{3}-3x\\)，则曲线的拐点为（　　）","opts":["\\((0,0)\\)","\\((1,-2)\\)","\\((-1,2)\\)","\\((0,1)\\)"],"ans":0,"sol":"\\(y'=3x^2-3\\)，\\(y''=6x\\)；\\(y''\\) 在 \\(x=0\\) 两侧变号（左负右正），且 \\(y(0)=0\\)，故拐点为 \\((0,0)\\)。\\((\\pm1,\\mp2)\\) 是极值点而非拐点。（原题附 \\(f''\\) 图形已丢失，改为解析式版本。）选 A。","id":"c30"},{"ty":"choice","ch":3,"kp":"极值必要条件","src":"小测第二三单元","diff":2,"q":"函数 \\(f(x)\\) 在点 \\(x=a\\) 取得极大值，则（　　）","opts":["\\(f'(a)=0\\) 且 \\(f''(a)<0\\)","\\(f'(a)=0\\)","\\(f'(a)=0\\) 或 \\(f(x)\\) 在 \\(x=a\\) 不可导","\\(f''(a)<0\\)"],"ans":2,"sol":"由费马引理，可导的极值点处 \\(f'(a)=0\\)；但极值点也可能不可导，如 \\(y=-|x|\\) 在 \\(x=0\\) 取极大值。A、D 只是充分条件而非必要条件，B 漏掉了不可导情形。选 C。","id":"c31"},{"ty":"choice","ch":3,"kp":"极值判定","src":"小测第二三单元","diff":2,"q":"函数 \\(y=(x^{2}-1)^{3}+1\\) 的极值点是（　　）","opts":["\\(x=-1\\)","\\(x=1\\)","不存在","\\(x=0\\)"],"ans":3,"sol":"\\(y'=6x(x^2-1)^2\\)，驻点 \\(x=0,\\pm1\\)。在 \\(x=\\pm1\\) 两侧 \\(y'\\ge 0\\) 不变号，不是极值点；在 \\(x=0\\) 处 \\(y'\\) 由正变负，为极大值点。选 D。","id":"c32"},{"ty":"choice","ch":3,"kp":"极值计算","src":"教材经典","diff":2,"q":"函数 \\(y=x^{2}e^{-x}\\) 的极大值为（　　）","opts":["0","\\(\\dfrac{1}{e}\\)","\\(\\dfrac{4}{e^{2}}\\)","不存在"],"ans":2,"sol":"\\(y'=x(2-x)e^{-x}\\)，\\(x=2\\) 处 \\(y'\\) 由正变负，取极大值 \\(y(2)=\\dfrac{4}{e^2}\\)；\\(x=0\\) 处由负变正为极小值。选 C。","id":"c33"},{"ty":"choice","ch":3,"kp":"方程的根","src":"教材经典","diff":2,"q":"方程 \\(x^{3}-3x+1=0\\) 在区间 \\((0,1)\\) 内实根的个数为（　　）","opts":["0","1","2","3"],"ans":1,"sol":"设 \\(f=x^3-3x+1\\)，\\(f(0)=1>0\\)，\\(f(1)=-1<0\\)，由零点定理有根；\\(f'(x)=3x^2-3<0\\) 于 \\((0,1)\\)，\\(f\\) 严格递减，故恰有一个根。选 B。","id":"c34"},{"ty":"choice","ch":3,"kp":"极值与不可导","src":"教材经典","diff":1,"q":"函数 \\(y=x^{2/3}\\) 在 \\(x=0\\) 处（　　）","opts":["取极大值","取极小值","不可导但不取极值","可导"],"ans":1,"sol":"\\(y'=\\dfrac{2}{3}x^{-1/3}\\)，\\(x=0\\) 处不可导；\\(x<0\\) 时 \\(y'<0\\)、\\(x>0\\) 时 \\(y'>0\\)，由负变正，取极小值 \\(y=0\\)。选 B。","id":"c35"},{"ty":"choice","ch":3,"kp":"拐点","src":"真题改编","diff":2,"q":"曲线 \\(y=x+\\dfrac{1}{x}\\) 的拐点情况是（　　）","opts":["恰有一个拐点","恰有两个拐点","无拐点","无法确定"],"ans":2,"sol":"\\(y''=\\dfrac{2}{x^3}\\)，\\(x>0\\) 时为负（凸）、\\(x<0\\) 时为正（凹），但 \\(x=0\\) 不在定义域内，凹凸性的改变不对应曲线上的点，故无拐点。选 C。","id":"c36"},{"ty":"choice","ch":3,"kp":"单调性应用","src":"真题改编","diff":1,"q":"当 \\(x>0\\) 时，下列不等式恒成立的是（　　）","opts":["\\(e^{x}<1+x\\)","\\(e^{x}>1+x\\)","\\(\\ln(1+x)>x\\)","\\(\\sin x>x\\)"],"ans":1,"sol":"设 \\(g=e^x-1-x\\)，\\(g(0)=0\\)，\\(g'=e^x-1>0\\)（\\(x>0\\)），故 \\(g>0\\)，即 \\(e^x>1+x\\)。C 应为 \\(\\ln(1+x)&lt;x\\)，D 应为 \\(\\sin x&lt;x\\)。选 B。","id":"c37"},{"ty":"choice","ch":3,"kp":"洛必达法则","src":"吉米多维奇精选","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\left(\\dfrac{1}{x}-\\dfrac{1}{e^{x}-1}\\right)=\\)（　　）","opts":["\\(\\dfrac{1}{2}\\)","0","1","\\(\\infty\\)"],"ans":0,"sol":"通分：\\(\\dfrac{e^x-1-x}{x(e^x-1)}\\)，分子 \\(\\sim\\dfrac{x^2}{2}\\)，分母 \\(\\sim x^2\\)，极限为 \\(\\dfrac12\\)（\\(\\infty-\\infty\\) 型未定式）。选 A。","id":"c38"},{"ty":"choice","ch":4,"kp":"有理函数积分","src":"小测第四单元","diff":1,"q":"\\(\\displaystyle\\int\\frac{4\\,dx}{x^{2}-4x+5}=\\)（　　）","opts":["\\(\\ln\\dfrac{x-5}{x+1}+C\\)","\\(\\ln\\dfrac{x-1}{x-5}+C\\)","\\(4\\arctan(x-2)+C\\)","\\(\\ln\\dfrac{x-5}{x-1}+C\\)"],"ans":2,"sol":"\\(x^2-4x+5=(x-2)^2+1\\)，原式 \\(=\\displaystyle\\int\\dfrac{4\\,d(x-2)}{(x-2)^2+1}=4\\arctan(x-2)+C\\)。选 C。","id":"c39"},{"ty":"choice","ch":4,"kp":"原函数概念","src":"小测第四单元","diff":3,"q":"设 \\(F(x)\\) 为 \\(f(x)\\) 的一个原函数，且 \\(F(0)=1\\)。当 \\(x\\ge 0\\) 时有 \\(f(x)F(x)=(\\sin 2x)^{2}\\)，\\(F(x)\\ge 0\\)，则 \\(f(x)=\\)（　　）","opts":["\\(\\dfrac{(\\cos 2x)^{2}}{\\sqrt{x-\\frac{1}{4}\\sin 4x+1}}\\)","\\(\\dfrac{(\\sin 2x)^{2}}{\\sqrt{x-\\frac{1}{4}\\sin 4x+1}}\\)","\\(\\dfrac{(\\cos 2x)^{2}}{\\sqrt{x-\\frac{1}{4}\\sin 4x}}\\)","\\(\\dfrac{(\\sin 2x)^{2}}{\\sqrt{x-\\frac{1}{4}\\sin 4x}}\\)"],"ans":1,"sol":"\\((F^2)'=2fF=2(\\sin 2x)^2=1-\\cos 4x\\)，故 \\(F^2=x-\\dfrac14\\sin 4x+C\\)；由 \\(F(0)=1\\) 得 \\(C=1\\)，\\(F=\\sqrt{x-\\frac14\\sin 4x+1}\\)，于是 \\(f=F'=\\dfrac{(\\sin 2x)^2}{\\sqrt{x-\\frac14\\sin 4x+1}}\\)。选 B。","id":"c40"},{"ty":"choice","ch":4,"kp":"三角有理式","src":"小测第四单元","diff":2,"q":"\\(\\displaystyle\\int\\frac{1-\\tan x}{1+\\tan x}\\,dx=\\)（　　）","opts":["\\(\\ln|\\sec 2x+\\tan 2x|+\\ln|\\cos 2x|+C\\)","\\(\\ln|\\cos x+\\sin x|+C\\)","\\(\\ln|1+\\tan 2x|-2\\ln|\\sec x|+C\\)","\\(\\ln|1+\\sin 2x|+C\\)"],"ans":1,"sol":"\\(\\dfrac{1-\\tan x}{1+\\tan x}=\\dfrac{\\cos x-\\sin x}{\\cos x+\\sin x}\\)，分子恰为分母的导数，故原式 \\(=\\ln|\\cos x+\\sin x|+C\\)。选 B。","id":"c41"},{"ty":"choice","ch":4,"kp":"换元积分","src":"小测第四单元","diff":2,"q":"\\(\\displaystyle\\int\\cos\\sqrt{x}\\,dx=\\)（　　）","opts":["\\(2\\left(\\sqrt{x}\\sin\\sqrt{x}-\\cos\\sqrt{x}\\right)+C\\)","\\(2\\left(\\sqrt{x}\\sin\\sqrt{x}+\\cos\\sqrt{x}\\right)+C\\)","\\(\\sin\\sqrt{x}+C\\)","\\(\\dfrac{1}{2}\\left(\\sqrt{x}\\sin\\sqrt{x}+\\cos\\sqrt{x}\\right)+C\\)"],"ans":1,"sol":"令 \\(t=\\sqrt{x}\\)，\\(dx=2t\\,dt\\)，原式 \\(=2\\displaystyle\\int t\\cos t\\,dt=2(t\\sin t+\\cos t)+C=2(\\sqrt{x}\\sin\\sqrt{x}+\\cos\\sqrt{x})+C\\)。选 B。","id":"c42"},{"ty":"choice","ch":4,"kp":"有理函数积分","src":"小测第四单元","diff":2,"q":"\\(\\displaystyle\\int\\frac{4}{x^{2}-6x+5}\\,dx=\\)（　　）","opts":["\\(\\ln\\dfrac{x-5}{x-1}+C\\)","\\(\\ln\\dfrac{x+5}{x-1}+C\\)","\\(\\ln\\dfrac{x+5}{x+1}+C\\)","\\(\\ln\\dfrac{x-1}{x+5}+C\\)"],"ans":0,"sol":"\\(\\dfrac{4}{(x-1)(x-5)}=\\dfrac{1}{x-5}-\\dfrac{1}{x-1}\\)，原式 \\(=\\ln|x-5|-\\ln|x-1|+C=\\ln\\left|\\dfrac{x-5}{x-1}\\right|+C\\)。选 A。","id":"c43"},{"ty":"choice","ch":4,"kp":"有理函数积分","src":"小测第四单元","diff":3,"q":"不定积分 \\(\\displaystyle\\int\\frac{1}{x(x^{8}+4)}\\,dx=\\)（　　）","opts":["\\(\\dfrac{1}{32}\\ln\\dfrac{x^{8}}{x^{8}+4}+c\\)","\\(\\dfrac{1}{8}\\ln\\dfrac{x^{8}}{x^{8}+4}+c\\)","\\(\\dfrac{1}{16}\\ln\\dfrac{x^{8}}{x^{8}+4}+c\\)","\\(\\dfrac{1}{64}\\ln\\dfrac{x^{8}}{x^{8}+4}+c\\)"],"ans":0,"sol":"\\(\\dfrac{1}{x(x^8+4)}=\\dfrac{1}{4}\\left(\\dfrac{1}{x}-\\dfrac{x^7}{x^8+4}\\right)\\)，原式 \\(=\\dfrac14\\left(\\ln|x|-\\dfrac18\\ln(x^8+4)\\right)+c=\\dfrac{1}{32}\\ln\\dfrac{x^8}{x^8+4}+c\\)。选 A。","id":"c44"},{"ty":"choice","ch":4,"kp":"有理函数积分","src":"小测第四单元","diff":2,"q":"积分 \\(\\displaystyle\\int\\frac{x+5}{x^{2}-6x+13}\\,dx=\\)（　　）","opts":["\\(\\dfrac{1}{2}\\ln|x^{2}-6x+13|+8\\arctan\\dfrac{x-3}{2}+C\\)","\\(\\dfrac{1}{2}\\ln|x^{2}-6x+13|+4\\arctan\\dfrac{x-3}{4}+C\\)","\\(\\dfrac{1}{2}\\ln|x^{2}-6x+13|+4\\arctan\\dfrac{x-3}{2}+C\\)","\\(\\dfrac{1}{2}\\ln|x^{2}-6x+13|+8\\arctan\\dfrac{x-3}{4}+C\\)"],"ans":2,"sol":"\\(x^2-6x+13=(x-3)^2+4\\)，\\(x+5=(x-3)+8\\)。\\(\\displaystyle\\int\\dfrac{x-3}{(x-3)^2+4}dx=\\dfrac12\\ln(x^2-6x+13)\\)，\\(\\displaystyle\\int\\dfrac{8\\,dx}{(x-3)^2+4}=8\\cdot\\dfrac12\\arctan\\dfrac{x-3}{2}=4\\arctan\\dfrac{x-3}{2}\\)。选 C。","id":"c45"},{"ty":"choice","ch":4,"kp":"换元积分","src":"小测第四单元","diff":1,"q":"\\(\\displaystyle\\int\\frac{e^{x}\\,dx}{1+e^{2x}}=\\)（　　）","opts":["\\(\\arctan e^{x}+C\\)","\\(2\\arctan e^{x}+C\\)","\\(\\dfrac{1}{2}\\arctan e^{x}+C\\)","\\(3\\arctan e^{x}+C\\)"],"ans":0,"sol":"令 \\(u=e^x\\)，\\(du=e^x dx\\)，原式 \\(=\\displaystyle\\int\\dfrac{du}{1+u^2}=\\arctan(e^x)+C\\)。选 A。","id":"c46"},{"ty":"choice","ch":4,"kp":"不定积分概念","src":"小测第四单元","diff":2,"q":"设 \\(\\displaystyle\\int f(x)\\,dx=x^{2}+C\\)，则 \\(\\displaystyle\\int xf(1-x^{2})\\,dx=\\)（　　）","opts":["\\(-2(1-x^{2})^{2}+C\\)","\\(\\dfrac{1}{2}(1-x^{2})^{2}+C\\)","\\(2(1-x^{2})^{2}+C\\)","\\(-\\dfrac{1}{2}(1-x^{2})^{2}+C\\)"],"ans":3,"sol":"由 \\(f(x)=2x\\) 得 \\(f(1-x^2)=2(1-x^2)\\)，\\(\\displaystyle\\int 2x(1-x^2)dx=x^2-\\dfrac{x^4}{2}+C=-\\dfrac12(1-x^2)^2+C\\)。选 D。","id":"c47"},{"ty":"choice","ch":4,"kp":"微分运算","src":"小测第四单元","diff":1,"q":"\\(\\displaystyle\\int\\left(\\frac{1}{\\cos^{2}x}+1\\right)d\\cos x=\\)（　　）","opts":["\\(\\csc x+\\cos x+c\\)","\\(-\\sec x+\\cos x+c\\)","\\(\\csc x-\\cos x+c\\)","\\(\\sec x+x+c\\)"],"ans":1,"sol":"令 \\(u=\\cos x\\)，\\(\\dfrac{1}{\\cos^2x}=\\dfrac{1}{u^2}\\)，原式 \\(=\\displaystyle\\int(u^{-2}+1)\\,du=-\\dfrac{1}{u}+u+c=-\\sec x+\\cos x+c\\)。选 B。","id":"c48"},{"ty":"choice","ch":4,"kp":"换元积分","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\int xe^{x^{2}}\\,dx=\\)（　　）","opts":["\\(e^{x^{2}}+C\\)","\\(\\dfrac{1}{2}e^{x^{2}}+C\\)","\\(2e^{x^{2}}+C\\)","\\(xe^{x^{2}}+C\\)"],"ans":1,"sol":"\\(\\displaystyle\\int xe^{x^2}dx=\\dfrac12\\displaystyle\\int e^{x^2}d(x^2)=\\dfrac12 e^{x^2}+C\\)。选 B。","id":"c49"},{"ty":"choice","ch":4,"kp":"三角积分","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\int\\sin^{2}x\\,dx=\\)（　　）","opts":["\\(\\dfrac{x}{2}-\\dfrac{\\sin 2x}{4}+C\\)","\\(\\dfrac{x}{2}+\\dfrac{\\sin 2x}{4}+C\\)","\\(\\dfrac{2}{3}\\sin^{3}x+C\\)","\\(x-\\cos^{2}x+C\\)"],"ans":0,"sol":"\\(\\sin^2x=\\dfrac{1-\\cos 2x}{2}\\)，原式 \\(=\\dfrac{x}{2}-\\dfrac{\\sin 2x}{4}+C\\)。选 A。","id":"c50"},{"ty":"choice","ch":4,"kp":"分部积分","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\int x\\arctan x\\,dx=\\)（　　）","opts":["\\(\\dfrac{x^{2}+1}{2}\\arctan x-\\dfrac{x}{2}+C\\)","\\(\\dfrac{x^{2}}{2}\\arctan x+C\\)","\\(x\\arctan x-\\ln(1+x^{2})+C\\)","\\(\\dfrac{x^{2}-1}{2}\\arctan x+C\\)"],"ans":0,"sol":"分部：原式 \\(=\\dfrac{x^2}{2}\\arctan x-\\dfrac12\\displaystyle\\int\\dfrac{x^2}{1+x^2}dx=\\dfrac{x^2}{2}\\arctan x-\\dfrac12(x-\\arctan x)+C=\\dfrac{x^2+1}{2}\\arctan x-\\dfrac{x}{2}+C\\)。选 A。","id":"c51"},{"ty":"choice","ch":4,"kp":"原函数与分部","src":"真题改编","diff":2,"q":"设 \\(e^{-x}\\) 是 \\(f(x)\\) 的一个原函数，则 \\(\\displaystyle\\int xf(x)\\,dx=\\)（　　）","opts":["\\((x+1)e^{-x}+C\\)","\\((x-1)e^{-x}+C\\)","\\(-(x+1)e^{-x}+C\\)","\\(xe^{-x}+C\\)"],"ans":0,"sol":"\\(f(x)=(e^{-x})'=-e^{-x}\\)，\\(\\displaystyle\\int x(-e^{-x})dx=\\displaystyle\\int x\\,d(e^{-x})=xe^{-x}-\\displaystyle\\int e^{-x}dx=xe^{-x}+e^{-x}+C=(x+1)e^{-x}+C\\)。选 A。","id":"c52"},{"ty":"choice","ch":4,"kp":"换元积分","src":"吉米多维奇精选","diff":2,"q":"\\(\\displaystyle\\int\\frac{dx}{1+\\sqrt{x}}=\\)（　　）","opts":["\\(2\\sqrt{x}-2\\ln(1+\\sqrt{x})+C\\)","\\(\\sqrt{x}-\\ln(1+\\sqrt{x})+C\\)","\\(2\\sqrt{x}+2\\ln(1+\\sqrt{x})+C\\)","\\(2\\ln(1+\\sqrt{x})+C\\)"],"ans":0,"sol":"令 \\(t=\\sqrt{x}\\)，\\(dx=2t\\,dt\\)，原式 \\(=2\\displaystyle\\int\\dfrac{t}{1+t}dt=2\\displaystyle\\int\\left(1-\\dfrac{1}{1+t}\\right)dt=2t-2\\ln(1+t)+C=2\\sqrt{x}-2\\ln(1+\\sqrt{x})+C\\)。选 A。","id":"c53"},{"ty":"choice","ch":4,"kp":"换元积分","src":"吉米多维奇精选","diff":2,"q":"\\(\\displaystyle\\int\\frac{dx}{e^{x}+1}=\\)（　　）","opts":["\\(x-\\ln(e^{x}+1)+C\\)","\\(\\ln(e^{x}+1)+C\\)","\\(x+\\ln(e^{x}+1)+C\\)","\\(\\dfrac{e^{-x}}{(1+e^{-x})^{2}}+C\\)"],"ans":0,"sol":"分子加减 \\(e^x\\)：\\(\\dfrac{1}{e^x+1}=1-\\dfrac{e^x}{e^x+1}\\)，原式 \\(=x-\\ln(e^x+1)+C\\)。验证求导：\\(1-\\dfrac{e^x}{e^x+1}=\\dfrac{1}{e^x+1}\\) ✓。选 A。","id":"c54"},{"ty":"choice","ch":5,"kp":"奇偶对称性","src":"小测第五单元","diff":1,"q":"\\(\\int_{-1}^{1} x^3\\cos x^3\\,dx =\\)（　　）","opts":["\\(0\\)","\\(2\\)","\\(1\\)","\\(3\\)"],"ans":0,"sol":"<p>\\(x^3\\) 为奇函数，\\(\\cos(x^3)\\) 为偶函数，二者之积 \\(x^3\\cos(x^3)\\) 为奇函数，故对称区间上积分为 0。</p>","id":"c55"},{"ty":"choice","ch":5,"kp":"积分比较","src":"小测第五单元","diff":1,"q":"设 \\(I_1=\\int_0^1 \\ln(1+x)\\,dx\\)，\\(I_2=\\int_0^1 \\ln(1+x^2)\\,dx\\)，则（　　）","opts":["\\(I_1=I_2\\)","\\(I_1>I_2\\)","\\(I_1^2=I_2\\)","\\(I_1&lt;I_2\\)"],"ans":1,"sol":"<p>在 \\((0,1)\\) 内 \\(x>x^2\\)，故 \\(\\ln(1+x)>\\ln(1+x^2)\\)，由定积分保序性得 \\(I_1>I_2\\)。</p>","id":"c56"},{"ty":"choice","ch":5,"kp":"换元积分","src":"小测第五单元","diff":1,"q":"\\(\\int_0^1 x(1-x)^3\\,dx =\\)（　　）","opts":["\\(\\dfrac{1}{20}\\)","\\(1\\)","\\(\\dfrac{1}{12}\\)","\\(0\\)"],"ans":0,"sol":"<p>令 \\(u=1-x\\)：\\(\\int_0^1 (1-u)u^3\\,du = \\dfrac{1}{4}-\\dfrac{1}{5} = \\dfrac{1}{20}\\)。</p>","id":"c57"},{"ty":"choice","ch":5,"kp":"函数连续性","src":"小测第五单元","diff":2,"q":"已知 \\(F(x)=\\begin{cases}\\dfrac{\\int_0^x t f(t)\\,dt}{x^2}, & x\\ne 0\\\\ c, & x=0\\end{cases}\\)，其中 \\(f(x)\\) 在 \\(x=0\\) 处连续且 \\(f(0)=0\\)。若 \\(F(x)\\) 在 \\(x=0\\) 处连续，则 \\(c=\\)（　　）","opts":["\\(0\\)","\\(-1\\)","不存在","\\(1\\)"],"ans":0,"sol":"<p>由洛必达法则：\\(\\lim\\limits_{x\\to0}\\dfrac{\\int_0^x tf(t)dt}{x^2} = \\lim\\limits_{x\\to0}\\dfrac{xf(x)}{2x} = \\dfrac{f(0)}{2} = 0\\)，故 \\(c=0\\)。</p>","id":"c58"},{"ty":"choice","ch":5,"kp":"积分等式","src":"小测第五单元","diff":2,"q":"已知函数 \\(f(x)=x+3\\int_0^1 f(x)\\,dx\\)，则 \\(f(x)=\\)（　　）","opts":["\\(x-\\dfrac{3}{4}\\)","\\(x+\\dfrac{1}{2}\\)","\\(x+1\\)","\\(x-1\\)"],"ans":0,"sol":"<p>设 \\(a=\\int_0^1 f(x)dx\\)，两边在 \\([0,1]\\) 上积分：\\(a = \\dfrac{1}{2}+3a\\)，解得 \\(a=-\\dfrac{1}{4}\\)，故 \\(f(x)=x-\\dfrac{3}{4}\\)。</p>","id":"c59"},{"ty":"choice","ch":5,"kp":"换元积分","src":"小测第五单元","diff":2,"q":"若 \\(\\int f(x)\\,dx=\\cos 2x+C\\)，则 \\(\\int_0^{\\sqrt{\\pi}} x f(x^2)\\,dx=\\)（　　）","opts":["\\(2\\)","\\(0\\)","\\(1\\)","\\(\\pi\\)"],"ans":1,"sol":"<p>\\(f(x)=-2\\sin 2x\\)。令 \\(u=x^2\\)，\\(du=2x\\,dx\\)，原式 \\(=\\int_0^{\\pi} -\\sin 2u\\,du = \\left[\\dfrac{\\cos 2u}{2}\\right]_0^{\\pi} = 0\\)。</p>","id":"c60"},{"ty":"choice","ch":5,"kp":"变限积分极值","src":"小测第五单元","diff":2,"q":"设函数 \\(I(x)=\\int_0^x t e^{-t^2}\\,dt\\)，则 \\(I(x)\\)（　　）","opts":["有极大值 \\(0\\)","有极大值 \\(\\dfrac{1}{2}\\)","有极小值 \\(-\\dfrac{1}{2}\\)","有极小值 \\(0\\)"],"ans":3,"sol":"<p>\\(I'(x)=xe^{-x^2}\\)，在 \\(x=0\\) 左侧为负、右侧为正，故 \\(x=0\\) 为极小值点，\\(I(0)=0\\)。</p>","id":"c61"},{"ty":"choice","ch":5,"kp":"定积分几何意义","src":"小测第五单元","diff":1,"q":"定积分 \\(\\int_0^{R} \\sqrt{R^2-x^2}\\,dx\\) 的值为（　　）\\((R>0)\\)","opts":["\\(\\dfrac{\\pi R^2}{4}\\)","\\(2\\pi R\\)","\\(\\pi R^2\\)","\\(0\\)"],"ans":0,"sol":"<p>被积函数是圆 \\(x^2+y^2=R^2\\) 的上半圆，\\([0,R]\\) 上积分为四分之一圆面积，即 \\(\\dfrac{\\pi R^2}{4}\\)。</p>","id":"c62"},{"ty":"choice","ch":5,"kp":"分部积分","src":"小测第五单元","diff":2,"q":"若 \\(f(x)=\\int_1^x \\dfrac{\\ln t}{t}\\,dt\\)，则 \\(\\int_1^{e} x f'(x)\\,dx=\\)（　　）","opts":["\\(0\\)","\\(e\\)","\\(-e\\)","\\(1\\)"],"ans":3,"sol":"<p>\\(f'(x)=\\dfrac{\\ln x}{x}\\)，原式 \\(=\\int_1^e \\ln x\\,dx = [x\\ln x - x]_1^e = (e-e)-(0-1) = 1\\)。</p>","id":"c63"},{"ty":"choice","ch":5,"kp":"反常积分","src":"小测第五单元","diff":1,"q":"\\(\\int_0^{+\\infty} x e^{-x}\\,dx=\\)（　　）","opts":["\\(+\\infty\\)","\\(2\\)","\\(0\\)","\\(1\\)"],"ans":3,"sol":"<p>分部积分：\\(\\int_0^{+\\infty} xe^{-x}dx = [-xe^{-x}]_0^{+\\infty} + \\int_0^{+\\infty} e^{-x}dx = 0+1 = 1\\)。</p>","id":"c64"},{"ty":"choice","ch":5,"kp":"变限积分求导","src":"教材经典","diff":2,"q":"\\(\\dfrac{d}{dx}\\displaystyle\\int_x^{x^2} e^{-t^2}\\,dt =\\)（　　）","opts":["\\(2x\\,e^{-x^4} - e^{-x^2}\\)","\\(e^{-x^4} - e^{-x^2}\\)","\\(2x\\,e^{-x^4}\\)","\\(-e^{-x^2}\\)"],"ans":0,"sol":"<p>由变限积分求导公式与链式法则：\\(e^{-x^4}\\cdot(x^2)' - e^{-x^2}\\cdot(x)' = 2x\\,e^{-x^4} - e^{-x^2}\\)。</p>","id":"c65"},{"ty":"choice","ch":5,"kp":"华里士公式","src":"教材经典","diff":2,"q":"\\(\\int_0^{\\pi/2} \\sin^2 x\\,dx =\\)（　　）","opts":["\\(\\dfrac{\\pi}{2}\\)","\\(1\\)","\\(\\dfrac{\\pi}{4}\\)","\\(\\dfrac{1}{2}\\)"],"ans":2,"sol":"<p>\\(\\int_0^{\\pi/2}\\sin^2 x\\,dx = \\dfrac{1}{2}\\cdot\\dfrac{\\pi}{2} = \\dfrac{\\pi}{4}\\)（华里士公式），也可用倍角公式 \\(\\sin^2x=\\dfrac{1-\\cos 2x}{2}\\) 计算。</p>","id":"c66"},{"ty":"choice","ch":5,"kp":"奇偶对称性","src":"教材经典","diff":1,"q":"\\(\\int_{-1}^{1} (x^2 + x)\\,dx =\\)（　　）","opts":["\\(\\dfrac{2}{3}\\)","\\(0\\)","\\(\\dfrac{1}{3}\\)","\\(2\\)"],"ans":0,"sol":"<p>\\(x\\) 为奇函数，积分为 0；\\(\\int_{-1}^{1} x^2\\,dx = \\dfrac{2}{3}\\)。</p>","id":"c67"},{"ty":"choice","ch":5,"kp":"反常积分","src":"教材经典","diff":1,"q":"\\(\\int_0^{+\\infty} \\dfrac{1}{1+x^2}\\,dx =\\)（　　）","opts":["\\(\\dfrac{\\pi}{2}\\)","\\(\\pi\\)","\\(1\\)","发散"],"ans":0,"sol":"<p>\\(\\left[\\arctan x\\right]_0^{+\\infty} = \\dfrac{\\pi}{2}-0 = \\dfrac{\\pi}{2}\\)。</p>","id":"c68"},{"ty":"choice","ch":5,"kp":"变限积分求导","src":"真题改编","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{\\int_0^x \\sin t^2\\,dt}{x^3} =\\)（　　）","opts":["\\(1\\)","\\(\\dfrac{1}{3}\\)","\\(0\\)","\\(3\\)"],"ans":1,"sol":"<p>由洛必达法则与变限积分求导：\\(\\lim\\limits_{x\\to0}\\dfrac{\\sin x^2}{3x^2} = \\dfrac{1}{3}\\)。</p>","id":"c69"},{"ty":"choice","ch":5,"kp":"积分比较","src":"真题改编","diff":2,"q":"比较大小：\\(I_1=\\int_0^1 e^x\\,dx\\) 与 \\(I_2=\\int_0^1 e^{x^2}\\,dx\\)，则（　　）","opts":["\\(I_1 > I_2\\)","\\(I_1 < I_2\\)","\\(I_1 = I_2\\)","\\(I_1^2 = I_2\\)"],"ans":0,"sol":"<p>在 \\([0,1]\\) 上 \\(x\\ge x^2\\)，故 \\(e^x\\ge e^{x^2}\\) 且不恒相等，由保序性 \\(I_1 > I_2\\)。</p>","id":"c70"},{"ty":"choice","ch":6,"kp":"平面图形面积","src":"教材经典","diff":1,"q":"正弦曲线 \\(y=\\sin x\\) 在 \\([0,\\pi]\\) 上与 \\(x\\) 轴围成图形的面积为（　　）","opts":["\\(1\\)","\\(\\pi\\)","\\(2\\)","\\(\\dfrac{\\pi}{2}\\)"],"ans":2,"sol":"<p>\\(S=\\int_0^{\\pi}\\sin x\\,dx = [-\\cos x]_0^{\\pi} = 2\\)。</p>","id":"c71"},{"ty":"choice","ch":6,"kp":"椭圆面积","src":"教材经典","diff":2,"q":"椭圆 \\(\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1\\;(a,b>0)\\) 所围面积为（　　）","opts":["\\(\\pi a^2 b^2\\)","\\(\\pi ab\\)","\\(\\dfrac{\\pi ab}{2}\\)","\\(4ab\\)"],"ans":1,"sol":"<p>由对称性 \\(S=4\\int_0^a \\dfrac{b}{a}\\sqrt{a^2-x^2}\\,dx = 4\\cdot\\dfrac{b}{a}\\cdot\\dfrac{\\pi a^2}{4} = \\pi ab\\)。</p>","id":"c72"},{"ty":"choice","ch":6,"kp":"旋转体体积","src":"教材经典","diff":1,"q":"曲线 \\(y=x^2\\) 在 \\([0,1]\\) 上绕 \\(x\\) 轴旋转一周所得旋转体体积为（　　）","opts":["\\(\\dfrac{\\pi}{3}\\)","\\(\\dfrac{2\\pi}{5}\\)","\\(\\dfrac{\\pi}{5}\\)","\\(\\pi\\)"],"ans":2,"sol":"<p>\\(V=\\pi\\int_0^1 (x^2)^2 dx = \\pi\\int_0^1 x^4 dx = \\dfrac{\\pi}{5}\\)。</p>","id":"c73"},{"ty":"choice","ch":6,"kp":"平面图形面积","src":"真题改编","diff":1,"q":"由曲线 \\(y=x^2\\) 与直线 \\(y=x\\) 围成平面图形的面积为（　　）","opts":["\\(\\dfrac{1}{3}\\)","\\(\\dfrac{1}{6}\\)","\\(\\dfrac{1}{2}\\)","\\(\\dfrac{2}{3}\\)"],"ans":1,"sol":"<p>交点 \\((0,0)\\)、\\((1,1)\\)：\\(S=\\int_0^1 (x-x^2)dx = \\dfrac{1}{2}-\\dfrac{1}{3} = \\dfrac{1}{6}\\)。</p>","id":"c74"},{"ty":"choice","ch":6,"kp":"平面图形面积","src":"真题改编","diff":2,"q":"由曲线 \\(y=x^2\\) 与曲线 \\(y=2-x^2\\) 围成图形的面积为（　　）","opts":["\\(\\dfrac{8}{3}\\)","\\(\\dfrac{4}{3}\\)","\\(\\dfrac{2}{3}\\)","\\(3\\)"],"ans":0,"sol":"<p>交点 \\(x=\\pm 1\\)：\\(S=\\int_{-1}^{1}[(2-x^2)-x^2]\\,dx = \\int_{-1}^{1}(2-2x^2)dx = 4-\\dfrac{4}{3} = \\dfrac{8}{3}\\)。</p>","id":"c75"},{"ty":"choice","ch":6,"kp":"参数方程面积","src":"吉米多维奇精选","diff":3,"q":"摆线 \\(x=a(t-\\sin t)\\)、\\(y=a(1-\\cos t)\\)\\((a>0)\\) 的一拱 \\(0\\le t\\le 2\\pi\\) 与 \\(x\\) 轴围成图形的面积为（　　）","opts":["\\(\\pi a^2\\)","\\(2\\pi a^2\\)","\\(4\\pi a^2\\)","\\(3\\pi a^2\\)"],"ans":3,"sol":"<p>\\(S=\\int_0^{2\\pi} a^2(1-\\cos t)^2 dt = a^2\\int_0^{2\\pi}(1-2\\cos t+\\cos^2 t)dt = a^2(2\\pi+\\pi) = 3\\pi a^2\\)。</p>","id":"c76"},{"ty":"choice","ch":7,"kp":"一阶线性方程","src":"小测第七单元","diff":1,"q":"微分方程 \\((10x+y)\\,dx + x\\,dy=0\\) 的通解为（　　）","opts":["\\(y=\\dfrac{5x^2-C}{x}\\)","\\(y=\\dfrac{C-10x^2}{x}\\)","\\(y=\\dfrac{10x^2-C}{x}\\)","\\(y=\\dfrac{C-5x^2}{x}\\)"],"ans":3,"sol":"<p>化为 \\(y'+\\dfrac{y}{x}=-10\\)，乘积分因子 \\(x\\)：\\((xy)'=-10x\\)，\\(xy=-5x^2+C\\)，即 \\(y=\\dfrac{C-5x^2}{x}\\)。</p>","id":"c77"},{"ty":"choice","ch":7,"kp":"一阶线性方程","src":"小测第七单元","diff":1,"q":"微分方程 \\(xy'+y=e^x\\) 的通解为（　　）","opts":["\\(y=\\dfrac{e^{-x}+C}{x}\\)","\\(y=\\dfrac{e^x+C}{x}\\)","\\(y=\\dfrac{e^x+C}{x^3}\\)","\\(y=\\dfrac{e^x+C}{x^2}\\)"],"ans":1,"sol":"<p>左端即 \\((xy)'\\)：\\(xy=e^x+C\\)，故 \\(y=\\dfrac{e^x+C}{x}\\)。</p>","id":"c78"},{"ty":"choice","ch":7,"kp":"可分离变量","src":"小测第七单元","diff":1,"q":"微分方程 \\(y'+3y=0\\) 的通解为（　　）","opts":["\\(y=e^{-3x+C}+C\\)","\\(y=Ce^{-3x}\\)","\\(y=e^{-3x}+C\\)","\\(y=x^3+C\\)"],"ans":1,"sol":"<p>特征方程 \\(r+3=0\\)，\\(r=-3\\)，通解 \\(y=Ce^{-3x}\\)。</p>","id":"c79"},{"ty":"choice","ch":7,"kp":"一阶线性方程","src":"小测第七单元","diff":1,"q":"微分方程 \\(xy'+y=\\sin x\\) 的通解为（　　）","opts":["\\(y=\\dfrac{-\\cos x+C}{x^3}\\)","\\(y=\\dfrac{\\cos x+C}{x}\\)","\\(y=\\dfrac{-\\cos x+C}{x^2}\\)","\\(y=\\dfrac{-\\cos x+C}{x}\\)"],"ans":3,"sol":"<p>\\((xy)'=\\sin x\\)，\\(xy=-\\cos x+C\\)，故 \\(y=\\dfrac{-\\cos x+C}{x}\\)。</p>","id":"c80"},{"ty":"choice","ch":7,"kp":"二阶齐次方程","src":"小测第七单元","diff":2,"q":"微分方程 \\(y''+4y'+5y=0\\) 的通解为（　　）","opts":["\\(y=c_1e^{-2x}+c_2\\sin x\\)","\\(y=c_1\\sin x+c_2\\cos x\\)","\\(y=c_1e^{-2x}+c_2\\cos x\\)","\\(y=e^{-2x}(c_1\\sin x+c_2\\cos x)\\)"],"ans":3,"sol":"<p>特征方程 \\(r^2+4r+5=0\\)，\\(r=-2\\pm i\\)，通解 \\(y=e^{-2x}(c_1\\sin x+c_2\\cos x)\\)。</p>","id":"c81"},{"ty":"choice","ch":7,"kp":"待定特解","src":"小测第七单元","diff":2,"q":"微分方程 \\(y''+2y'+y=e^{-x}\\) 的特解可设为（　　）","opts":["\\(ae^{-x}\\)","\\(ax^2e^{-x}\\)","\\(axe^{-x}\\)","\\(ax^3e^{-x}\\)"],"ans":1,"sol":"<p>特征根 \\(r=-1\\) 为二重根，而 \\(\\lambda=-1\\) 恰为重根，特解应设 \\(y^*=ax^2e^{-x}\\)。</p>","id":"c82"},{"ty":"choice","ch":7,"kp":"解的结构","src":"小测第七单元","diff":2,"q":"设非齐次线性微分方程 \\(y'+p(x)y=q(x)\\) 有两个不同的解 \\(y_1, y_2\\)，\\(C\\) 为任意常数，则该方程的通解是（　　）","opts":["\\(C(y_1+y_2)\\)","\\(y_1+C(y_1+y_2)\\)","\\(C(y_1-y_2)\\)","\\(y_1+C(y_1-y_2)\\)"],"ans":3,"sol":"<p>\\(y_1-y_2\\) 是对应齐次方程的非零解，可作齐次通解的基础；通解 \\(=\\) 一个特解 \\(+\\) 齐次通解，即 \\(y_1+C(y_1-y_2)\\)。</p>","id":"c83"},{"ty":"choice","ch":7,"kp":"待定特解","src":"小测第七单元","diff":2,"q":"微分方程 \\(y''-6y'+9y=e^{3x}\\) 的特解可设为（　　）","opts":["\\(ax^3e^{3x}\\)","\\(axe^{3x}\\)","\\(ae^{3x}\\)","\\(ax^2e^{3x}\\)"],"ans":3,"sol":"<p>特征方程 \\(r^2-6r+9=0\\)，\\(r=3\\) 为二重根，且 \\(\\lambda=3\\) 为重根，特解设 \\(y^*=ax^2e^{3x}\\)。</p>","id":"c84"},{"ty":"choice","ch":7,"kp":"高阶方程","src":"小测第七单元","diff":2,"q":"在下列微分方程中，以 \\(y=C_1e^x+C_2\\cos 3x+C_3\\sin 3x\\)（\\(C_1,C_2,C_3\\) 为任意常数）为通解的是（　　）","opts":["\\(y'''-y''+9y'-9y=0\\)","\\(y'''-y''-9y'+9y=0\\)","\\(y'''+y''-9y'-9y=0\\)","\\(y'''+y''+9y'+9y=0\\)"],"ans":0,"sol":"<p>特征根为 \\(1, \\pm 3i\\)，特征方程 \\((r-1)(r^2+9)=r^3-r^2+9r-9=0\\)，对应 \\(y'''-y''+9y'-9y=0\\)。</p>","id":"c85"},{"ty":"choice","ch":7,"kp":"可降阶方程","src":"小测第七单元","diff":2,"q":"为解二阶微分方程 \\(3yy''+(y')^3=0\\)（方程中不含 \\(x\\)），应降阶成一阶方程（　　）","opts":["\\(3x\\dfrac{dp}{dx}+p^3=0\\)","\\(3yp\\dfrac{dp}{dx}+p^3=0\\)","\\(3yp\\dfrac{dp}{dy}+p^3=0\\)","\\(3y\\dfrac{dp}{dx}+p^3=0\\)"],"ans":2,"sol":"<p>方程不显含 \\(x\\)，令 \\(p=y'\\)，则 \\(y''=p\\dfrac{dp}{dy}\\)，代入得 \\(3yp\\dfrac{dp}{dy}+p^3=0\\)。</p>","id":"c86"},{"ty":"choice","ch":7,"kp":"二阶齐次方程","src":"教材经典","diff":1,"q":"微分方程 \\(y''-4y=0\\) 的通解为（　　）","opts":["\\((C_1+C_2x)e^{2x}\\)","\\(C_1e^{2x}\\)","\\(C_1\\cos 2x+C_2\\sin 2x\\)","\\(C_1e^{2x}+C_2e^{-2x}\\)"],"ans":3,"sol":"<p>特征方程 \\(r^2-4=0\\)，\\(r=\\pm 2\\)，通解 \\(y=C_1e^{2x}+C_2e^{-2x}\\)。</p>","id":"c87"},{"ty":"choice","ch":7,"kp":"二阶齐次方程","src":"教材经典","diff":1,"q":"微分方程 \\(y''-5y'+6y=0\\) 的通解为（　　）","opts":["\\(C_1e^{2x}+C_2e^{3x}\\)","\\(C_1e^{-2x}+C_2e^{-3x}\\)","\\(C_1e^{2x}+C_2e^{-3x}\\)","\\((C_1+C_2x)e^{3x}\\)"],"ans":0,"sol":"<p>特征方程 \\(r^2-5r+6=0\\)，\\(r=2,3\\)，通解 \\(y=C_1e^{2x}+C_2e^{3x}\\)。</p>","id":"c88"},{"ty":"choice","ch":7,"kp":"可分离变量","src":"教材经典","diff":2,"q":"微分方程 \\(xy'-y\\ln y=0\\)（\\(y>1\\)）的通解为（　　）","opts":["\\(y=Ce^x\\)","\\(y=e^x+C\\)","\\(y=e^{Cx}\\)","\\(y=Cx\\)"],"ans":2,"sol":"<p>分离变量 \\(\\dfrac{dy}{y\\ln y}=\\dfrac{dx}{x}\\)，积分得 \\(\\ln\\ln y=\\ln x+C_1\\)，即 \\(\\ln y=Cx\\)，\\(y=e^{Cx}\\)。</p>","id":"c89"},{"ty":"choice","ch":7,"kp":"待定特解","src":"真题改编","diff":2,"q":"方程 \\(y''-2y'=x\\) 的特解可设为（　　）","opts":["\\(ax+b\\)","\\(x(ax+b)\\)","\\(ax^2\\)","\\(axe^{x}\\)"],"ans":1,"sol":"<p>特征根 \\(r=0,2\\)；右端为一次多项式，\\(\\lambda=0\\) 是单根，故特解应设 \\(y^*=x(ax+b)\\)。</p>","id":"c90"},{"ty":"choice","ch":7,"kp":"初值问题","src":"真题改编","diff":2,"q":"方程 \\(y''+2y'-3y=0\\) 满足 \\(y(0)=1\\)、\\(y'(0)=5\\) 的特解为（　　）","opts":["\\(y=e^x+e^{-3x}\\)","\\(y=2e^x+e^{-3x}\\)","\\(y=e^x-e^{-3x}\\)","\\(y=2e^x-e^{-3x}\\)"],"ans":3,"sol":"<p>特征根 \\(r=1,-3\\)，\\(y=C_1e^x+C_2e^{-3x}\\)。由 \\(C_1+C_2=1\\)、\\(C_1-3C_2=5\\) 解得 \\(C_1=2, C_2=-1\\)。</p>","id":"c91"},{"ty":"choice","ch":7,"kp":"二阶齐次方程","src":"真题改编","diff":1,"q":"通解为 \\(y=(C_1+C_2x)e^{2x}\\) 的微分方程是（　　）","opts":["\\(y''-4y'+4y=0\\)","\\(y''-4y'=0\\)","\\(y''+4y=0\\)","\\(y''-2y'+4y=0\\)"],"ans":0,"sol":"<p>通解形式对应二重特征根 \\(r=2\\)，特征方程 \\((r-2)^2=r^2-4r+4=0\\)。</p>","id":"c92"},{"ty":"choice","ch":8,"kp":"平面位置关系","src":"小测第八单元","diff":1,"q":"平面 \\(3x+z-4=0\\) 与平面 \\(2x+y-6z=0\\)（　　）","opts":["垂直","相交但不垂直","平行但不重合","重合"],"ans":0,"sol":"<p>法向量 \\(\\vec{n}_1=(3,0,1)\\)、\\(\\vec{n}_2=(2,1,-6)\\)，\\(\\vec{n}_1\\cdot\\vec{n}_2=6+0-6=0\\)，两平面垂直。</p>","id":"c93"},{"ty":"choice","ch":8,"kp":"直线位置关系","src":"小测第八单元","diff":2,"q":"直线 \\(\\begin{cases}x-2y+z-4=0\\\\2x+y+z-6=0\\end{cases}\\) 与直线 \\(\\begin{cases}4x+7y+z+10=0\\\\3x-y+2z-6=0\\end{cases}\\)（　　）","opts":["平行","重合","相交但不垂直","垂直"],"ans":0,"sol":"<p>\\(\\vec{s}_1=(1,-2,1)\\times(2,1,1)=(-3,1,5)\\)，\\(\\vec{s}_2=(4,7,1)\\times(3,-1,2)=(15,-5,-25)=-5\\vec{s}_1\\)。取两点验证不共线（向量 \\((-\\tfrac{36}{5},0,\\tfrac{44}{5})\\) 与 \\(\\vec{s}_1\\) 不平行），故两直线平行。</p>","id":"c94"},{"ty":"choice","ch":8,"kp":"平面方程","src":"小测第八单元","diff":2,"q":"过点 \\((2,1,1)\\) 和 \\(y\\) 轴的平面方程为（　　）","opts":["\\(z-2x=0\\)","\\(x-2y=0\\)","\\(x-2z=0\\)","\\(y-2z=0\\)"],"ans":2,"sol":"<p>平面含 \\(y\\) 轴，即含原点且法向量与 \\((0,1,0)\\) 垂直。\\(\\vec{n}=(2,1,1)\\times(0,1,0)=(-1,0,2)\\)，方程 \\(-x+2z=0\\)。</p>","id":"c95"},{"ty":"choice","ch":8,"kp":"直线方程","src":"小测第八单元","diff":1,"q":"过点 \\((2,0,-3)\\) 与点 \\((1,3,-2)\\) 的直线方程为（　　）","opts":["\\(\\dfrac{x-2}{1}=\\dfrac{y}{3}=\\dfrac{z+3}{1}\\)","\\(\\dfrac{x-2}{-1}=\\dfrac{y}{3}=\\dfrac{z+3}{1}\\)","\\(\\dfrac{x-2}{3}=\\dfrac{y}{3}=\\dfrac{z+3}{1}\\)","\\(\\dfrac{x-2}{-1}=\\dfrac{y}{3}=\\dfrac{z+3}{3}\\)"],"ans":1,"sol":"<p>方向向量 \\(\\vec{s}=(1,3,-2)-(2,0,-3)=(-1,3,1)\\)，取点 \\((2,0,-3)\\)，得对称式 \\(\\dfrac{x-2}{-1}=\\dfrac{y}{3}=\\dfrac{z+3}{1}\\)。</p>","id":"c96"},{"ty":"choice","ch":8,"kp":"投影","src":"小测第八单元","diff":2,"q":"点 \\((1,1,1)\\) 在平面 \\(x+2y-z+1=0\\) 上的投影为（　　）","opts":["\\((-\\dfrac{1}{2},0,-\\dfrac{3}{2})\\)","\\((\\dfrac{1}{2},0,\\dfrac{3}{2})\\)","\\((1,-1,0)\\)","\\((\\dfrac{1}{2},-1,-\\dfrac{1}{2})\\)"],"ans":1,"sol":"<p>代入平面得 \\(1+2-1+1=3>0\\)，投影 \\(=P-\\dfrac{3}{6}(1,2,-1)=(1,1,1)-(\\dfrac{1}{2},1,-\\dfrac{1}{2})=(\\dfrac{1}{2},0,\\dfrac{3}{2})\\)。</p>","id":"c97"},{"ty":"choice","ch":8,"kp":"点到平面距离","src":"小测第八单元","diff":1,"q":"点 \\((1,2,1)\\) 到平面 \\(x+2y+2z-8=0\\) 的距离为（　　）","opts":["\\(\\dfrac{1}{3}\\)","\\(\\dfrac{2}{3}\\)","\\(\\dfrac{4}{3}\\)","\\(1\\)"],"ans":0,"sol":"<p>\\(d=\\dfrac{|1+4+2-8|}{\\sqrt{1+4+4}}=\\dfrac{1}{3}\\)。</p>","id":"c98"},{"ty":"choice","ch":8,"kp":"方向余弦","src":"小测第八单元","diff":2,"q":"设点 \\(A\\) 位于第一卦限，向径 \\(\\overrightarrow{OA}\\) 与 \\(x\\) 轴、\\(y\\) 轴的夹角依次为 \\(\\dfrac{\\pi}{3},\\dfrac{\\pi}{4}\\)，且 \\(|OA|=6\\)，则点 \\(A\\) 的坐标为（　　）","opts":["\\((3,3,3\\sqrt{2})\\)","\\((3,3\\sqrt{2},3)\\)","\\((3\\sqrt{2},3,3)\\)","\\((3\\sqrt{2},3\\sqrt{2},3)\\)"],"ans":1,"sol":"<p>由 \\(\\cos^2\\alpha+\\cos^2\\beta+\\cos^2\\gamma=1\\)：\\(\\cos^2\\gamma=1-\\dfrac{1}{4}-\\dfrac{1}{2}=\\dfrac{1}{4}\\)，第一卦限取 \\(\\cos\\gamma=\\dfrac{1}{2}\\)。\\(A=6(\\dfrac{1}{2},\\dfrac{\\sqrt{2}}{2},\\dfrac{1}{2})=(3,3\\sqrt{2},3)\\)。</p>","id":"c99"},{"ty":"choice","ch":8,"kp":"异面直线距离","src":"小测第八单元","diff":3,"q":"异面直线 \\(l_1:\\dfrac{x-9}{4}=\\dfrac{y+2}{-3}=\\dfrac{z}{1}\\) 与 \\(l_2:\\dfrac{x}{2}=\\dfrac{y+7}{-9}=\\dfrac{z-2}{-2}\\) 之间的距离为（　　）","opts":["8","9","6","7"],"ans":3,"sol":"<p>\\(P_1=(9,-2,0)\\)、\\(P_2=(0,-7,2)\\)、\\(\\vec{s}_1=(4,-3,1)\\)、\\(\\vec{s}_2=(2,-9,-2)\\)。\\(\\vec{s}_1\\times\\vec{s}_2=(15,10,-30)\\)，\\(|\\vec{s}_1\\times\\vec{s}_2|=35\\)；\\((\\overrightarrow{P_1P_2})\\cdot(\\vec{s}_1\\times\\vec{s}_2)=-245\\)。距离 \\(=\\dfrac{245}{35}=7\\)。</p>","id":"c100"},{"ty":"choice","ch":8,"kp":"向量垂直","src":"小测第八单元","diff":1,"q":"若向量 \\(\\vec{a}=(m,2,-3)\\) 与 \\(\\vec{b}=(-1,6,m)\\) 垂直，则 \\(m=\\)（　　）","opts":["4","2","1","3"],"ans":3,"sol":"<p>\\(\\vec{a}\\cdot\\vec{b}=-m+12-3m=12-4m=0\\)，解得 \\(m=3\\)。</p>","id":"c101"},{"ty":"choice","ch":8,"kp":"直线与平面","src":"小测第八单元","diff":2,"q":"直线 \\(\\begin{cases}x-y+2z-3=0\\\\x=y\\end{cases}\\) 与平面 \\(x+y-6=0\\)（　　）","opts":["重合","平行","相交但不垂直","垂直"],"ans":3,"sol":"<p>方向向量 \\(\\vec{s}=(1,-1,2)\\times(1,-1,0)=(2,2,0)\\)，与平面法向量 \\(\\vec{n}=(1,1,0)\\) 平行，故直线与平面垂直。</p>","id":"c102"},{"ty":"choice","ch":8,"kp":"向量向量积","src":"教材经典","diff":2,"q":"设 \\(\\vec{a}=(1,2,3)\\)，\\(\\vec{b}=(1,1,0)\\)，则 \\(\\vec{a}\\times\\vec{b}=\\)（　　）","opts":["\\((-3,3,-1)\\)","\\((3,-3,1)\\)","\\((3,3,-1)\\)","\\((-3,-3,1)\\)"],"ans":0,"sol":"<p>\\(\\vec{a}\\times\\vec{b}=(2\\cdot0-3\\cdot1,\\; 3\\cdot1-1\\cdot0,\\; 1\\cdot1-2\\cdot1)=(-3,3,-1)\\)。</p>","id":"c103"},{"ty":"choice","ch":8,"kp":"平面方程","src":"教材经典","diff":1,"q":"过点 \\((2,-3,1)\\) 且以 \\(\\vec{n}=(1,-2,3)\\) 为法向量的平面方程为（　　）","opts":["\\(x-2y+3z+11=0\\)","\\(x+2y-3z-11=0\\)","\\(x-2y+3z-11=0\\)","\\(x-2y+3z=0\\)"],"ans":2,"sol":"<p>点法式：\\((x-2)-2(y+3)+3(z-1)=0\\)，整理得 \\(x-2y+3z-11=0\\)。</p>","id":"c104"},{"ty":"choice","ch":8,"kp":"向量夹角","src":"真题改编","diff":2,"q":"向量 \\(\\vec{a}=(2,1,-1)\\) 与 \\(\\vec{b}=(1,-1,2)\\) 的夹角为（　　）","opts":["\\(\\arccos\\dfrac{1}{6}\\)","\\(\\arccos\\left(-\\dfrac{1}{6}\\right)\\)","\\(\\dfrac{\\pi}{2}\\)","\\(\\arccos\\dfrac{1}{3}\\)"],"ans":1,"sol":"<p>\\(\\vec{a}\\cdot\\vec{b}=2-1-2=-1\\)，\\(|\\vec{a}|=|\\vec{b}|=\\sqrt{6}\\)，\\(\\cos\\theta=\\dfrac{-1}{6}\\)，故 \\(\\theta=\\arccos(-\\dfrac{1}{6})\\)。</p>","id":"c105"},{"ty":"choice","ch":8,"kp":"点到平面距离","src":"真题改编","diff":2,"q":"点 \\((2,1,0)\\) 到平面 \\(3x+4y+5z-6=0\\) 的距离为（　　）","opts":["\\(\\dfrac{2\\sqrt{2}}{5}\\)","\\(\\dfrac{4}{5}\\)","\\(\\dfrac{\\sqrt{2}}{5}\\)","\\(2\\)"],"ans":0,"sol":"<p>\\(d=\\dfrac{|6+4+0-6|}{\\sqrt{9+16+25}}=\\dfrac{4}{5\\sqrt{2}}=\\dfrac{2\\sqrt{2}}{5}\\)。</p>","id":"c106"},{"ty":"choice","ch":8,"kp":"直线与平面","src":"真题改编","diff":2,"q":"直线 \\(\\dfrac{x-1}{2}=\\dfrac{y}{-1}=\\dfrac{z+1}{3}\\) 与平面 \\(2x-y+3z-7=0\\) 的位置关系是（　　）","opts":["垂直","相交但不垂直","平行","直线在平面内"],"ans":1,"sol":"<p>\\(\\vec{s}=(2,-1,3)\\)，\\(\\vec{n}=(2,-1,3)\\)，\\(\\vec{s}\\cdot\\vec{n}=4+1+9=14\\ne 0\\)，不平行；\\(\\vec{s}\\) 与 \\(\\vec{n}\\) 不成比例，不垂直，故相交但不垂直。</p>","id":"c107"},{"ty":"choice","ch":8,"kp":"向量积应用","src":"吉米多维奇精选","diff":2,"q":"以点 \\(A(1,1,0)\\)、\\(B(0,1,1)\\)、\\(C(1,0,1)\\) 为顶点的三角形面积为（　　）","opts":["\\(\\dfrac{\\sqrt{3}}{3}\\)","\\(\\sqrt{3}\\)","\\(\\dfrac{1}{2}\\)","\\(\\dfrac{\\sqrt{3}}{2}\\)"],"ans":3,"sol":"<p>\\(\\overrightarrow{AB}=(-1,0,1)\\)、\\(\\overrightarrow{AC}=(0,-1,1)\\)，\\(\\overrightarrow{AB}\\times\\overrightarrow{AC}=(1,1,1)\\)，面积 \\(=\\dfrac{1}{2}|\\overrightarrow{AB}\\times\\overrightarrow{AC}|=\\dfrac{\\sqrt{3}}{2}\\)。</p>","id":"c108"},{"ty":"choice","ch":9,"kp":"偏导数计算","src":"小测第9单元","diff":2,"q":"设 \\(z=x^{y}\\)，则 \\(\\dfrac{\\partial z}{\\partial y}\\) 与 \\(\\dfrac{\\partial^{2}z}{\\partial y\\,\\partial x}\\) 分别为","opts":["\\(x^{y}\\ln x,\\ x^{y-1}+yx^{y-1}\\ln x\\)","\\(yx^{y-1},\\ x^{y-1}+yx^{y-1}\\ln x\\)","\\(yx^{y-1},\\ x^{y-1}+x^{y-1}\\ln x\\)","\\(x^{y}\\ln x,\\ x^{y}\\ln x\\)"],"ans":0,"sol":"<p>\\(\\dfrac{\\partial z}{\\partial y}=x^y\\ln x\\)；\\(\\dfrac{\\partial^{2}z}{\\partial y\\,\\partial x}=\\dfrac{\\partial}{\\partial x}\\left(x^y\\ln x\\right)=yx^{y-1}\\ln x+x^{y-1}=x^{y-1}+yx^{y-1}\\ln x\\)。选 A。</p>","id":"c109"},{"ty":"choice","ch":9,"kp":"链式法则","src":"小测第9单元","diff":2,"q":"设 \\(z=u^{2}\\ln v\\)，而 \\(u=\\dfrac{x}{y}\\)，\\(v=3x-2y\\)，则 \\(\\dfrac{\\partial z}{\\partial y}=\\)（　　）","opts":["\\(2u\\ln v+\\dfrac{u^{2}}{v}\\)","以上都不对","\\(\\dfrac{2u\\ln v}{y}+\\dfrac{3u^{2}}{v}\\)","\\(-2u^{2}\\left(\\dfrac{\\ln v}{y}+\\dfrac{1}{v}\\right)\\)"],"ans":3,"sol":"<p>链式法则：\\(\\dfrac{\\partial z}{\\partial y}=\\dfrac{\\partial z}{\\partial u}\\cdot\\dfrac{\\partial u}{\\partial y}+\\dfrac{\\partial z}{\\partial v}\\cdot\\dfrac{\\partial v}{\\partial y}=2u\\ln v\\cdot\\left(-\\dfrac{u}{y}\\right)+\\dfrac{u^2}{v}\\cdot(-2)=-2u^{2}\\left(\\dfrac{\\ln v}{y}+\\dfrac{1}{v}\\right)\\)。选 D。</p>","id":"c110"},{"ty":"choice","ch":9,"kp":"全微分","src":"小测第9单元","diff":2,"q":"设 \\(z=e^{\\sin xy}\\)，则 \\(dz=\\)（　　）","opts":["\\(e^{\\sin xy}\\sin(xy)\\cdot y\\,dx\\)","\\(e^{\\sin xy}\\cos(xy)\\,(y\\,dx+x\\,dy)\\)","\\(e^{\\sin xy}\\cos(xy)\\cdot x\\,dy\\)","\\(e^{\\sin xy}\\sin(xy)\\,(y\\,dx+x\\,dy)\\)"],"ans":1,"sol":"<p>\\(z_x=e^{\\sin xy}\\cos(xy)\\cdot y\\)，\\(z_y=e^{\\sin xy}\\cos(xy)\\cdot x\\)，故 \\(dz=e^{\\sin xy}\\cos(xy)(y\\,dx+x\\,dy)\\)。选 B。</p>","id":"c111"},{"ty":"choice","ch":9,"kp":"定义域","src":"小测第9单元","diff":2,"q":"函数 \\(z=\\arcsin\\dfrac{1}{x^{2}+y^{2}}+\\sqrt{1-x^{2}-y^{2}}\\) 的定义域为（　　）","opts":["一个点","空集","圆域","圆周"],"ans":3,"sol":"<p>\\(\\arcsin\\dfrac{1}{x^2+y^2}\\) 要求 \\(\\dfrac{1}{x^2+y^2}\\le 1\\) 即 \\(x^2+y^2\\ge1\\)；根号要求 \\(x^2+y^2\\le1\\)。交集为 \\(x^2+y^2=1\\)，即圆周。选 D。</p>","id":"c112"},{"ty":"choice","ch":9,"kp":"隐函数微分","src":"小测第9单元","diff":2,"q":"函数 \\(z=z(x,y)\\) 由方程 \\(z^{3}-3xyz+x^{3}=0\\) 确定，则 \\((dz)_{x=1,\\,y=0}=\\)（　　）","opts":["\\(-dx-dy\\)","\\(-\\dfrac{2}{3}dx-dy\\)","\\(-dx+dy\\)","\\(-\\dfrac{2}{3}dx+dy\\)"],"ans":0,"sol":"<p>代入 \\(x=1,y=0\\) 得 \\(z^3+1=0\\)，\\(z=-1\\)。方程两边微分：\\(3z^2dz-3(yz\\,dx+xz\\,dy+xy\\,dz)+3x^2dx=0\\)，代入得 \\(3dz+3\\,dy+3\\,dx=0\\)，即 \\(dz=-dx-dy\\)。选 A。</p>","id":"c113"},{"ty":"choice","ch":9,"kp":"无条件极值","src":"小测第9单元","diff":2,"q":"设 \\(f(x,y)=e^{2x}(x+y^{2}+2y)\\)，下列说法正确的是（　　）","opts":["在 \\((\\frac12,-1)\\) 处取得极大值 \\(-\\dfrac{e}{2}\\)","在 \\((\\frac12,-1)\\) 处取得极小值 \\(-\\dfrac{e}{2}\\)","在 \\((\\frac12,0)\\) 处取得极小值 \\(\\dfrac{e}{2}\\)","在 \\((\\frac12,0)\\) 处取得极大值 \\(\\dfrac{e}{2}\\)"],"ans":1,"sol":"<p>\\(f_y=e^{2x}(2y+2)=0\\Rightarrow y=-1\\)；\\(f_x=e^{2x}(2x+2y^2+4y+1)=0\\Rightarrow x=\\frac12\\)。\\(A=f_{xx}=e^{2x}(4x+4y^2+8y+4)\\big|=2e\\)，\\(C=f_{yy}=2e\\)，\\(B=f_{xy}=e^{2x}(4y+4)=0\\)，\\(AC-B^2=4e^2>0\\) 且 \\(A>0\\)，取极小值 \\(f(\\frac12,-1)=e\\left(\\frac12+1-2\\right)=-\\dfrac e2\\)。选 B。</p>","id":"c114"},{"ty":"choice","ch":9,"kp":"二重极限","src":"小测第9单元","diff":1,"q":"\\(\\displaystyle\\lim_{(x,y)\\to(0,0)}\\frac{xy}{x^{2}+y^{2}}=\\)（　　）","opts":["不存在","\\(\\dfrac{1}{2}\\)","\\(1\\)","\\(0\\)"],"ans":0,"sol":"<p>沿 \\(y=x\\) 趋于原点时极限为 \\(\\dfrac12\\)，沿 \\(y=0\\) 时极限为 \\(0\\)，沿不同路径极限不同，故二重极限不存在。选 A。</p>","id":"c115"},{"ty":"choice","ch":9,"kp":"偏导数计算","src":"小测第9单元","diff":1,"q":"设 \\(z=y^{x}\\)，则 \\(\\left(\\dfrac{\\partial z}{\\partial x}+\\dfrac{\\partial z}{\\partial y}\\right)_{(2,1)}=\\)（　　）","opts":["\\(1+\\ln 2\\)","\\(1\\)","\\(0\\)","\\(2\\)"],"ans":3,"sol":"<p>\\(z_x=y^x\\ln y\\big|_{(2,1)}=1\\cdot\\ln 1=0\\)，\\(z_y=xy^{x-1}\\big|_{(2,1)}=2\\)，两者之和为 \\(2\\)。选 D。</p>","id":"c116"},{"ty":"choice","ch":9,"kp":"高阶偏导","src":"小测第9单元","diff":2,"q":"设 \\(z=f(x^{2}+y^{2})\\)，其中 \\(f\\) 二阶可导，则 \\(\\dfrac{\\partial^{2}z}{\\partial y^{2}}=\\)（　　）","opts":["\\(2f''\\)","\\(2f'+2yf''\\)","\\(2f'\\)","\\(2f'+4y^{2}f''\\)"],"ans":3,"sol":"<p>\\(z_y=2yf'\\)，再对 \\(y\\) 求导：\\(z_{yy}=2f'+2y\\cdot f''\\cdot 2y=2f'+4y^2f''\\)。选 D。</p>","id":"c117"},{"ty":"choice","ch":9,"kp":"连续与偏导","src":"小测第9单元","diff":3,"q":"设 \\(f(x,y)=\\begin{cases}\\dfrac{x^{2}y}{x^{4}+y^{2}}, & x^{2}+y^{2}\\ne 0\\\\[2pt] 0, & x^{2}+y^{2}=0\\end{cases}\\)，则在 \\((0,0)\\) 处 \\(f\\)（　　）","opts":["不连续，偏导数不存在","连续，偏导数存在","不连续，偏导数存在","连续，偏导数不存在"],"ans":2,"sol":"<p>沿路径 \\(y=kx^2\\)，\\(f\\to\\dfrac{k}{1+k^2}\\) 随 \\(k\\) 变化，故在原点不连续；而 \\(f(x,0)\\equiv0\\)、\\(f(0,y)\\equiv0\\)，故 \\(f_x(0,0)=f_y(0,0)=0\\) 都存在。选 C。</p>","id":"c118"},{"ty":"choice","ch":9,"kp":"全微分","src":"教材经典","diff":1,"q":"函数 \\(z=\\ln(x^{2}+y^{2})\\) 在点 \\((1,1)\\) 处的全微分为","opts":["\\(dx+dy\\)","\\(2dx+2dy\\)","\\(\\dfrac{dx+dy}{2}\\)","\\(dx-dy\\)"],"ans":0,"sol":"<p>\\(z_x=\\dfrac{2x}{x^2+y^2}\\big|_{(1,1)}=1\\)，\\(z_y=\\dfrac{2y}{x^2+y^2}\\big|_{(1,1)}=1\\)，故 \\(dz=dx+dy\\)。选 A。</p>","id":"c119"},{"ty":"choice","ch":9,"kp":"无条件极值","src":"教材经典","diff":2,"q":"函数 \\(f(x,y)=x^{3}+y^{3}-3xy\\) 的极小值为","opts":["\\(-1\\)","\\(1\\)","\\(0\\)","\\(-3\\)"],"ans":0,"sol":"<p>\\(f_x=3x^2-3y=0,\\ f_y=3y^2-3x=0\\) 得驻点 \\((0,0)\\) 与 \\((1,1)\\)。\\(A=f_{xx}=6x,\\ B=-3,\\ C=6y\\)，\\(AC-B^2=36xy-9\\)。在 \\((1,1)\\)：\\(AC-B^2=27>0\\) 且 \\(A=6>0\\)，取极小值 \\(f(1,1)=2-3=-1\\)；在 \\((0,0)\\)：\\(AC-B^2=-9<0\\) 非极值。选 A。</p>","id":"c120"},{"ty":"choice","ch":9,"kp":"复合函数求导","src":"教材经典","diff":2,"q":"设 \\(z=f\\left(x^{2}-y^{2},\\ e^{xy}\\right)\\)，其中 \\(f\\) 具有一阶连续偏导数，则 \\(\\dfrac{\\partial z}{\\partial x}=\\)（　　）","opts":["\\(2x f_1'+y e^{xy}f_2'\\)","\\(2x f_1'-y e^{xy}f_2'\\)","\\(x^{2} f_1'+e^{xy}f_2'\\)","\\(2x f_1'+e^{xy}f_2'\\)"],"ans":0,"sol":"<p>链式法则：\\(\\dfrac{\\partial z}{\\partial x}=f_1'\\cdot 2x+f_2'\\cdot y e^{xy}=2x f_1'+y e^{xy}f_2'\\)。选 A。</p>","id":"c121"},{"ty":"choice","ch":9,"kp":"切平面","src":"真题改编","diff":2,"q":"曲面 \\(z=x^{2}+y^{2}\\) 在点 \\((1,1,2)\\) 处的切平面方程为","opts":["\\(2x+2y-z-2=0\\)","\\(2x+2y-z+2=0\\)","\\(x+y-2z=0\\)","\\(2x+2y+z-6=0\\)"],"ans":0,"sol":"<p>\\(z_x=2x=2\\)，\\(z_y=2y=2\\)，切平面为 \\(2(x-1)+2(y-1)-(z-2)=0\\)，即 \\(2x+2y-z-2=0\\)。选 A。</p>","id":"c122"},{"ty":"choice","ch":9,"kp":"方向导数","src":"真题改编","diff":2,"q":"函数 \\(z=x^{2}+y^{2}\\) 在点 \\((1,2)\\) 处沿从点 \\((1,2)\\) 到点 \\((2,4)\\) 方向的方向导数为","opts":["\\(2\\sqrt{5}\\)","\\(\\dfrac{2}{\\sqrt{5}}\\)","\\(10\\)","\\(4\\sqrt{5}\\)"],"ans":0,"sol":"<p>梯度 \\(\\left.\\operatorname{grad}z\\right|_{(1,2)}=(2,4)\\)；方向 \\((1,2)\\) 的单位向量 \\(\\dfrac{(1,2)}{\\sqrt5}\\)。方向导数 \\(=\\dfrac{2+8}{\\sqrt5}=2\\sqrt5\\)。选 A。</p>","id":"c123"},{"ty":"choice","ch":9,"kp":"闭区域最值","src":"真题改编","diff":3,"q":"函数 \\(z=x^{2}-xy+y^{2}\\) 在闭区域 \\(D=\\{(x,y)\\mid|x|+|y|\\le1\\}\\) 上的最大值为","opts":["\\(1\\)","\\(\\dfrac{1}{4}\\)","\\(2\\)","\\(\\dfrac{1}{3}\\)"],"ans":0,"sol":"<p>驻点满足 \\(2x-y=0,\\ 2y-x=0\\) 得 \\((0,0)\\)，\\(z(0,0)=0\\)。边界 \\(x+y=1\\ (x,y\\ge0)\\) 上 \\(z=3x^2-3x+1\\)，在端点 \\(x=0,1\\) 处取最大值 1（在 \\(x=\\frac12\\) 处仅 \\(\\frac14\\)）。由对称性其余三边最大值同为 1，故最大值为 1。选 A。</p>","id":"c124"},{"ty":"choice","ch":10,"kp":"交换次序","src":"小测第10单元","diff":2,"q":"若二重积分 \\(\\displaystyle\\iint_D f(x,y)\\,d\\sigma\\) 可化为二次积分 \\(\\displaystyle\\int_{0}^{1}dy\\int_{y+1}^{2}f(x,y)\\,dx\\)，则积分域 \\(D\\) 可表示为（　　）","opts":["\\(\\{(x,y)\\mid 1\\le x\\le 2,\\ x-1\\le y\\le 1\\}\\)","\\(\\{(x,y)\\mid 0\\le x\\le 1,\\ x-1\\le y\\le 0\\}\\)","\\(\\{(x,y)\\mid 0\\le x\\le 1,\\ x-1\\le y\\le 1\\}\\)","\\(\\{(x,y)\\mid 1\\le x\\le 2,\\ 0\\le y\\le x-1\\}\\)"],"ans":3,"sol":"<p>区域为 \\(0\\le y\\le1,\\ y+1\\le x\\le2\\)，即 \\(1\\le x\\le2,\\ 0\\le y\\le x-1\\)。选 D。</p>","id":"c125"},{"ty":"choice","ch":10,"kp":"直角坐标计算","src":"小测第10单元","diff":3,"q":"设 \\(D\\) 是以 \\((0,0),(1,0),(1,2)\\) 和 \\((0,1)\\) 为顶点的梯形闭区域，则 \\(\\displaystyle\\iint_D (1+x)\\cos y\\,d\\sigma=\\)（　　）","opts":["\\(\\cos 1-2\\cos 2+\\sin 2-\\sin 1\\)","\\(\\cos 1+2\\cos 2+\\sin 2-\\sin 1\\)","\\(\\cos 1-2\\cos 2+\\sin 2+\\sin 1\\)","\\(\\cos 1-2\\cos 2-\\sin 2-\\sin 1\\)"],"ans":0,"sol":"<p>区域为 \\(0\\le x\\le1,\\ 0\\le y\\le1+x\\)。\\(\\displaystyle\\int_0^1(1+x)\\sin(1+x)\\,dx\\)，令 \\(u=1+x\\)：\\(\\displaystyle\\int_1^2 u\\sin u\\,du=\\left[-u\\cos u\\right]_1^2+\\left[\\sin u\\right]_1^2=\\cos1-2\\cos2+\\sin2-\\sin1\\)。选 A。</p>","id":"c126"},{"ty":"choice","ch":10,"kp":"对称性","src":"小测第10单元","diff":2,"q":"设 \\(D=\\{(x,y)\\mid x^{2}+y^{2}\\le R^{2}\\}\\)，则 \\(\\displaystyle\\iint_D (x^{2}+5x-7y+8)\\,d\\sigma=\\)（　　）","opts":["\\(\\dfrac{\\pi}{4}R^{3}+8\\pi R^{2}\\)","\\(\\dfrac{\\pi}{4}R^{4}+8\\pi R^{2}\\)","\\(\\dfrac{\\pi}{4}R^{4}-8\\pi R^{2}\\)","\\(8\\pi R^{2}\\)"],"ans":1,"sol":"<p>由对称性 \\(\\displaystyle\\iint_D 5x\\,d\\sigma=\\iint_D(-7y)\\,d\\sigma=0\\)；由轮换对称 \\(\\displaystyle\\iint_D x^2\\,d\\sigma=\\dfrac12\\iint_D r^2\\,d\\sigma=\\dfrac{\\pi R^4}{4}\\)；\\(\\displaystyle\\iint_D 8\\,d\\sigma=8\\pi R^2\\)。合计 \\(\\dfrac{\\pi}{4}R^4+8\\pi R^2\\)。选 B。</p>","id":"c127"},{"ty":"choice","ch":10,"kp":"极坐标","src":"小测第10单元","diff":2,"q":"极坐标下的二次积分 \\(\\displaystyle\\int_{0}^{\\frac{\\pi}{2}}d\\theta\\int_{0}^{\\cos\\theta}f(r\\cos\\theta,r\\sin\\theta)\\,r\\,dr\\) 可写成（　　）","opts":["\\(\\displaystyle\\int_{0}^{1}dy\\int_{0}^{\\sqrt{1-y^{2}}}f(x,y)\\,dx\\)","\\(\\displaystyle\\int_{0}^{1}dx\\int_{0}^{1}f(x,y)\\,dy\\)","\\(\\displaystyle\\int_{0}^{1}dy\\int_{0}^{\\sqrt{y-y^{2}}}f(x,y)\\,dx\\)","\\(\\displaystyle\\int_{0}^{1}dx\\int_{0}^{\\sqrt{x-x^{2}}}f(x,y)\\,dy\\)"],"ans":3,"sol":"<p>区域为 \\(0\\le\\theta\\le\\dfrac\\pi2,\\ 0\\le r\\le\\cos\\theta\\)，即圆 \\(x^2+y^2\\le x\\) 的上半部分：\\(0\\le x\\le1,\\ 0\\le y\\le\\sqrt{x-x^2}\\)。选 D。</p>","id":"c128"},{"ty":"choice","ch":10,"kp":"极坐标计算","src":"小测第10单元","diff":2,"q":"设 \\(D=\\{(x,y)\\mid x^{2}+y^{2}\\le 1\\}\\)，则 \\(\\displaystyle\\iint_D \\sqrt{x^{2}+y^{2}}\\,d\\sigma=\\)（　　）","opts":["\\(\\pi\\)","\\(\\dfrac{2\\pi}{3}\\)","\\(\\dfrac{\\pi}{3}\\)","\\(\\dfrac{4\\pi}{3}\\)"],"ans":1,"sol":"<p>极坐标下 \\(\\displaystyle\\int_0^{2\\pi}\\!\\!d\\theta\\int_0^1 r\\cdot r\\,dr=2\\pi\\cdot\\dfrac13=\\dfrac{2\\pi}{3}\\)。选 B。</p>","id":"c129"},{"ty":"choice","ch":10,"kp":"极坐标计算","src":"小测第10单元","diff":2,"q":"积分 \\(\\displaystyle\\int_{0}^{1}dx\\int_{0}^{\\sqrt{1-x^{2}}}(x^{2}+y^{2})\\,dy=\\)（　　）","opts":["\\(\\dfrac{\\pi}{8}\\)","\\(\\dfrac{3\\pi}{8}\\)","\\(\\dfrac{\\pi}{6}\\)","\\(\\dfrac{5\\pi}{8}\\)"],"ans":0,"sol":"<p>积分域为第一象限的四分之一单位圆盘，极坐标：\\(\\displaystyle\\int_0^{\\frac\\pi2}\\!\\!d\\theta\\int_0^1 r^2\\cdot r\\,dr=\\dfrac\\pi2\\cdot\\dfrac14=\\dfrac\\pi8\\)。选 A。</p>","id":"c130"},{"ty":"choice","ch":10,"kp":"对称性","src":"小测第10单元","diff":1,"q":"设 \\(D=\\{(x,y)\\mid |x|\\le\\pi,\\ |y|\\le 1\\}\\)，则 \\(\\displaystyle\\iint_D (x^{2}y+\\sin x)\\,d\\sigma=\\)（　　）","opts":["\\(\\dfrac{\\pi}{2}\\)","\\(8\\pi\\)","\\(4\\pi\\)","\\(0\\)"],"ans":3,"sol":"<p>\\(D\\) 关于 \\(x\\) 轴对称且 \\(x^2y\\) 关于 \\(y\\) 为奇函数，该项积分为 0；\\(D\\) 关于 \\(y\\) 轴对称且 \\(\\sin x\\) 关于 \\(x\\) 为奇函数，该项积分为 0。故积分为 0。选 D。</p>","id":"c131"},{"ty":"choice","ch":10,"kp":"交换次序","src":"小测第10单元","diff":2,"q":"积分 \\(\\displaystyle\\int_{0}^{3}dx\\int_{x}^{3}e^{-y^{2}}\\,dy=\\)（　　）","opts":["\\(e^{-9}\\)","\\(1\\)","\\(\\dfrac{1}{2}(1-e^{-9})\\)","\\(\\dfrac{1}{2}(e^{9}-1)\\)"],"ans":2,"sol":"<p>交换次序：区域为 \\(0\\le y\\le3,\\ 0\\le x\\le y\\)，\\(\\displaystyle\\int_0^3 y\\,e^{-y^2}dy=\\left[-\\dfrac12e^{-y^2}\\right]_0^3=\\dfrac{1-e^{-9}}{2}\\)。选 C。</p>","id":"c132"},{"ty":"choice","ch":10,"kp":"对称性","src":"小测第10单元","diff":2,"q":"设区域 \\(D:\\ x^{2}+y^{2}\\le 2x\\)，则 \\(\\displaystyle\\iint_D \\left(y^{3}e^{x^{4}+y^{4}}+3\\right)d\\sigma=\\)（　　）","opts":["\\(2\\pi\\)","\\(5\\pi\\)","\\(4\\pi\\)","\\(3\\pi\\)"],"ans":3,"sol":"<p>\\(D\\) 是圆心 \\((1,0)\\)、半径 1 的圆盘，关于 \\(x\\) 轴对称；\\(y^3e^{x^4+y^4}\\) 关于 \\(y\\) 为奇函数，积分为 0。剩余 \\(3\\cdot|D|=3\\pi\\)。选 D。</p>","id":"c133"},{"ty":"choice","ch":10,"kp":"曲面面积","src":"小测第10单元","diff":3,"q":"抛物面 \\(x^{2}+y^{2}-z=0\\) 介于平面 \\(z=4\\) 和 \\(z=0\\) 之间的面积为（　　）","opts":["\\(\\dfrac{\\pi}{6}(15\\sqrt{15}+1)\\)","\\(\\dfrac{\\pi}{6}(17\\sqrt{17}-1)\\)","\\(\\dfrac{\\pi}{6}(17\\sqrt{17}+1)\\)","\\(\\dfrac{\\pi}{6}(15\\sqrt{15}-1)\\)"],"ans":1,"sol":"<p>\\(z=x^2+y^2\\)，\\(dS=\\sqrt{1+4x^2+4y^2}\\,d\\sigma\\)，投影区域 \\(x^2+y^2\\le4\\)。\\(S=\\displaystyle\\int_0^{2\\pi}\\!\\!d\\theta\\int_0^2 r\\sqrt{1+4r^2}\\,dr=2\\pi\\cdot\\dfrac{1}{12}(1+4r^2)^{3/2}\\Big|_0^2=\\dfrac{\\pi}{6}(17\\sqrt{17}-1)\\)。选 B。</p>","id":"c134"},{"ty":"choice","ch":10,"kp":"交换次序","src":"教材经典","diff":2,"q":"二次积分 \\(\\displaystyle\\int_{0}^{1}dx\\int_{x^{2}}^{1}f(x,y)\\,dy\\) 交换积分次序后为","opts":["\\(\\displaystyle\\int_{0}^{1}dy\\int_{0}^{\\sqrt{y}}f(x,y)\\,dx\\)","\\(\\displaystyle\\int_{0}^{1}dy\\int_{\\sqrt{y}}^{1}f(x,y)\\,dx\\)","\\(\\displaystyle\\int_{0}^{1}dy\\int_{0}^{y^{2}}f(x,y)\\,dx\\)","\\(\\displaystyle\\int_{0}^{1}dy\\int_{y}^{\\sqrt{y}}f(x,y)\\,dx\\)"],"ans":0,"sol":"<p>区域为 \\(0\\le x\\le1,\\ x^2\\le y\\le1\\)，改写为 \\(0\\le y\\le1,\\ 0\\le x\\le\\sqrt y\\)。选 A。</p>","id":"c135"},{"ty":"choice","ch":10,"kp":"三重积分","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\iiint_\\Omega (x+y+z)\\,dV\\)，其中 \\(\\Omega:\\ x^{2}+y^{2}+z^{2}\\le1\\)，等于","opts":["\\(0\\)","\\(1\\)","\\(\\dfrac{4\\pi}{3}\\)","\\(\\pi\\)"],"ans":0,"sol":"<p>球体 \\(\\Omega\\) 关于三个坐标面都对称，\\(x\\)、\\(y\\)、\\(z\\) 分别是对应变量的奇函数，三项积分均为 0。选 A。</p>","id":"c136"},{"ty":"choice","ch":10,"kp":"积分估值","src":"教材经典","diff":1,"q":"估计 \\(I=\\displaystyle\\iint_D (x+y+1)\\,d\\sigma\\) 的值，其中 \\(D:\\ 0\\le x\\le1,\\ 0\\le y\\le1\\)，则","opts":["\\(1\\le I\\le3\\)","\\(0\\le I\\le3\\)","\\(2\\le I\\le4\\)","\\(1\\le I\\le2\\)"],"ans":0,"sol":"<p>\\(f=x+y+1\\) 在 \\(D\\) 上最小值为 1（原点处）、最大值为 3，且 \\(D\\) 的面积为 1，由估值定理得 \\(1\\le I\\le3\\)。选 A。</p>","id":"c137"},{"ty":"choice","ch":10,"kp":"体积计算","src":"真题改编","diff":2,"q":"由曲面 \\(z=4-x^{2}-y^{2}\\) 与平面 \\(z=0\\) 围成的立体体积为","opts":["\\(8\\pi\\)","\\(4\\pi\\)","\\(16\\pi\\)","\\(\\dfrac{32\\pi}{3}\\)"],"ans":0,"sol":"<p>投影区域 \\(x^2+y^2\\le4\\)，\\(V=\\displaystyle\\int_0^{2\\pi}\\!\\!d\\theta\\int_0^2 (4-r^2)r\\,dr=2\\pi\\left[2r^2-\\dfrac{r^4}{4}\\right]_0^2=2\\pi(8-4)=8\\pi\\)。选 A。</p>","id":"c138"},{"ty":"choice","ch":10,"kp":"极坐标计算","src":"真题改编","diff":2,"q":"\\(\\displaystyle\\iint_D e^{-x^{2}-y^{2}}\\,d\\sigma\\)，其中 \\(D:\\ x^{2}+y^{2}\\le1\\)，等于","opts":["\\(\\pi(1-e^{-1})\\)","\\(\\pi(e-1)\\)","\\(\\dfrac{\\pi}{2}(1-e^{-1})\\)","\\(1-e^{-1}\\)"],"ans":0,"sol":"<p>极坐标：\\(\\displaystyle\\int_0^{2\\pi}\\!\\!d\\theta\\int_0^1 e^{-r^2}r\\,dr=2\\pi\\cdot\\left[-\\dfrac12e^{-r^2}\\right]_0^1=\\pi(1-e^{-1})\\)。选 A。</p>","id":"c139"},{"ty":"choice","ch":10,"kp":"对称性","src":"吉米多维奇精选","diff":2,"q":"设 \\(D:\\ x^{2}+y^{2}\\le1\\)，则 \\(\\displaystyle\\iint_D (|x|+|y|)\\,d\\sigma=\\)（　　）","opts":["\\(\\dfrac{8}{3}\\)","\\(\\dfrac{4}{3}\\)","\\(2\\)","\\(\\pi\\)"],"ans":0,"sol":"<p>由对称性，积分 \\(=4\\displaystyle\\iint_{D_1}(x+y)\\,d\\sigma\\)（\\(D_1\\) 为第一象限部分），且 \\(\\displaystyle\\iint_{D_1}x\\,d\\sigma=\\int_0^1 x\\sqrt{1-x^2}\\,dx=\\dfrac13\\)。故积分为 \\(4\\times\\dfrac23=\\dfrac83\\)。选 A。</p>","id":"c140"},{"ty":"choice","ch":11,"kp":"第一类线积分","src":"教材经典","diff":1,"q":"设 \\(L\\) 为圆周 \\(x^{2}+y^{2}=a^{2}\\)，则 \\(\\displaystyle\\oint_L (x^{2}+y^{2})\\,ds=\\)（　　）","opts":["\\(2\\pi a^{3}\\)","\\(\\pi a^{3}\\)","\\(2\\pi a^{2}\\)","\\(0\\)"],"ans":0,"sol":"<p>在 \\(L\\) 上 \\(x^2+y^2=a^2\\) 为常数，故积分 \\(=a^2\\cdot 2\\pi a=2\\pi a^3\\)。选 A。</p>","id":"c141"},{"ty":"choice","ch":11,"kp":"第二类线积分","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\int_L y\\,dx-x\\,dy\\)，其中 \\(L\\) 为抛物线 \\(y=x^{2}\\) 上从 \\((0,0)\\) 到 \\((1,1)\\) 的一段弧，其值为","opts":["\\(-\\dfrac{1}{3}\\)","\\(\\dfrac{1}{3}\\)","\\(-1\\)","\\(1\\)"],"ans":0,"sol":"<p>代入 \\(y=x^2,\\ dy=2x\\,dx\\)：\\(\\displaystyle\\int_0^1\\left(x^2-x\\cdot2x\\right)dx=-\\int_0^1x^2\\,dx=-\\dfrac13\\)。选 A。</p>","id":"c142"},{"ty":"choice","ch":11,"kp":"第一类面积分","src":"教材经典","diff":2,"q":"设 \\(\\Sigma\\) 为锥面 \\(z=\\sqrt{x^{2}+y^{2}}\\) 被平面 \\(z=1\\) 所截的部分，则 \\(\\displaystyle\\iint_\\Sigma (x^{2}+y^{2})\\,dS=\\)（　　）","opts":["\\(\\dfrac{\\sqrt{2}\\,\\pi}{2}\\)","\\(\\dfrac{\\pi}{2}\\)","\\(\\sqrt{2}\\,\\pi\\)","\\(\\pi\\)"],"ans":0,"sol":"<p>\\(z_x=\\dfrac{x}{\\sqrt{x^2+y^2}}\\)，\\(dS=\\sqrt{1+z_x^2+z_y^2}\\,d\\sigma=\\sqrt2\\,dx\\,dy\\)；投影为单位圆盘。\\(\\displaystyle\\iint_\\Sigma(x^2+y^2)\\,dS=\\sqrt2\\iint_{x^2+y^2\\le1}(x^2+y^2)\\,d\\sigma=\\sqrt2\\cdot\\dfrac\\pi2=\\dfrac{\\sqrt2\\,\\pi}{2}\\)。选 A。</p>","id":"c143"},{"ty":"choice","ch":11,"kp":"格林公式","src":"真题改编","diff":2,"q":"设 \\(L\\) 为椭圆 \\(\\dfrac{x^{2}}{a^{2}}+\\dfrac{y^{2}}{b^{2}}=1\\) 取正向，则 \\(\\displaystyle\\oint_L x\\,dy-y\\,dx=\\)（　　）","opts":["\\(2\\pi ab\\)","\\(\\pi ab\\)","\\(-2\\pi ab\\)","\\(0\\)"],"ans":0,"sol":"<p>由格林公式，\\(\\displaystyle\\oint_L x\\,dy-y\\,dx=\\iint_D (1+1)\\,d\\sigma=2\\times\\pi ab=2\\pi ab\\)。选 A。</p>","id":"c144"},{"ty":"choice","ch":11,"kp":"斯托克斯公式","src":"吉米多维奇精选","diff":3,"q":"设 \\(\\Gamma\\) 为平面 \\(x+y+z=1\\) 与三个坐标面的交线（三角形边界），从 \\(z\\) 轴正向看去取逆时针方向，则 \\(\\displaystyle\\oint_\\Gamma z\\,dx+x\\,dy+y\\,dz=\\)（　　）","opts":["\\(\\dfrac{3}{2}\\)","\\(1\\)","\\(\\dfrac{1}{2}\\)","\\(3\\)"],"ans":0,"sol":"<p>由斯托克斯公式，\\(\\operatorname{rot}\\boldsymbol{F}=(1,1,1)\\)；三角形位于所给平面上，面积为 \\(\\dfrac{\\sqrt3}{2}\\)，单位法向量 \\(\\dfrac{(1,1,1)}{\\sqrt3}\\)。积分为 \\(\\dfrac{\\sqrt3}{2}\\cdot(1,1,1)\\cdot\\dfrac{(1,1,1)}{\\sqrt3}=\\dfrac{3}{2}\\)。选 A。</p>","id":"c145"},{"ty":"choice","ch":11,"kp":"第二类线积分","src":"吉米多维奇精选","diff":3,"q":"计算曲线积分 \\(\\displaystyle\\int_\\Gamma xyz\\,dz\\)，其中 \\(\\Gamma:\\ x=a\\cos t,\\ y=a\\sin t,\\ z=kt\\ (a>0,\\ 0\\le t\\le2\\pi)\\)，其值为","opts":["\\(-\\dfrac{\\pi a^{2}k^{2}}{2}\\)","\\(\\dfrac{\\pi a^{2}k^{2}}{2}\\)","\\(\\pi a^{2}k^{2}\\)","\\(0\\)"],"ans":0,"sol":"<p>\\(\\displaystyle\\int_0^{2\\pi}a^2k^2\\,t\\cos t\\sin t\\,dt=\\dfrac{a^2k^2}{2}\\int_0^{2\\pi}t\\sin2t\\,dt=\\dfrac{a^2k^2}{2}\\left(\\left[-\\dfrac{t\\cos2t}{2}\\right]_0^{2\\pi}+\\dfrac12\\int_0^{2\\pi}\\cos2t\\,dt\\right)=\\dfrac{a^2k^2}{2}(-\\pi)=-\\dfrac{\\pi a^2k^2}{2}\\)。选 A。</p>","id":"c146"},{"ty":"choice","ch":12,"kp":"幂级数求和","src":"小测第12单元","diff":2,"q":"幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}nx^{n-1}\\) 在区间 \\((-1,1)\\) 内的和函数为（　　）","opts":["\\(\\dfrac{1}{1-x}\\)","\\(\\dfrac{x}{1-x}\\)","\\(\\dfrac{1}{(1-x)^{2}}\\)","\\(-\\dfrac{1}{(1-x)^{2}}\\)"],"ans":2,"sol":"<p>\\(\\displaystyle\\sum_{n=1}^{\\infty}x^n=\\dfrac{x}{1-x}\\)，逐项求导得 \\(\\displaystyle\\sum_{n=1}^{\\infty}nx^{n-1}=\\left(\\dfrac{x}{1-x}\\right)'=\\dfrac{1}{(1-x)^2}\\)。选 C。</p>","id":"c147"},{"ty":"choice","ch":12,"kp":"收敛半径","src":"小测第12单元","diff":1,"q":"幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{2^{n}}{n}(x+1)^{n}\\) 的收敛半径 \\(R=\\)（　　）","opts":["\\(1\\)","\\(2\\)","\\(+\\infty\\)","\\(\\dfrac{1}{2}\\)"],"ans":3,"sol":"<p>\\(\\displaystyle\\lim_{n\\to\\infty}\\left|\\dfrac{a_{n+1}}{a_n}\\right|=\\lim\\dfrac{2^{n+1}}{n+1}\\cdot\\dfrac{n}{2^n}=2\\)，故 \\(R=\\dfrac12\\)。选 D。</p>","id":"c148"},{"ty":"choice","ch":12,"kp":"级数性质","src":"小测第12单元","diff":2,"q":"下列结论正确的是（　　）","opts":["若 \\(\\lim\\limits_{n\\to\\infty}(u_{n+1}-u_n)=0\\)，则 \\(\\sum u_n\\) 收敛","若 \\(\\lim\\limits_{n\\to\\infty}u_n=0\\)，则 \\(\\sum u_n\\) 收敛","若 \\(\\sum u_n\\) 发散，则 \\(\\lim\\limits_{n\\to\\infty}u_n\\ne0\\)","若 \\(\\sum u_n\\) 收敛，则 \\(\\lim\\limits_{n\\to\\infty}u_n=0\\)"],"ans":3,"sol":"<p>通项趋于 0 是收敛的必要条件，D 正确。A、B 的反例为 \\(u_n=\\dfrac1n\\)；C 的反例也是调和级数（发散但通项趋于 0）。选 D。</p>","id":"c149"},{"ty":"choice","ch":12,"kp":"幂级数展开","src":"小测第12单元","diff":3,"q":"函数 \\(\\dfrac{1}{1-x}\\) 按 \\((x+1)\\) 的幂级数展开式是（　　）","opts":["\\(\\displaystyle\\sum_{n=0}^{\\infty}\\dfrac{(-1)^{n}}{2^{n+1}}(x+1)^{n},\\ x\\in(-3,1)\\)","\\(\\displaystyle\\sum_{n=0}^{\\infty}\\dfrac{(x+1)^{n}}{2^{n+1}},\\ x\\in(-3,1)\\)","\\(\\displaystyle\\sum_{n=0}^{\\infty}\\dfrac{(-1)^{n}}{2^{n}}(x+1)^{n},\\ x\\in(-3,1)\\)","\\(\\displaystyle\\sum_{n=0}^{\\infty}\\dfrac{(x+1)^{n}}{2^{n}},\\ x\\in(-3,1)\\)"],"ans":1,"sol":"<p>令 \\(t=x+1\\)，则 \\(1-x=2-t\\)，\\(\\dfrac{1}{1-x}=\\dfrac12\\cdot\\dfrac{1}{1-t/2}=\\displaystyle\\sum_{n=0}^{\\infty}\\dfrac{t^n}{2^{n+1}}\\)，其中 \\(|t/2|<1\\) 即 \\(-3&lt;x<1\\)。选 B。（验证：\\(x=0\\) 时和为 \\(\\sum\\dfrac{1}{2^{n+1}}=1\\)，与 \\(f(0)=1\\) 相符。）</p>","id":"c150"},{"ty":"choice","ch":12,"kp":"绝对条件收敛","src":"小测第12单元","diff":3,"q":"已知级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}(-1)^{n}\\sqrt{n}\\sin\\dfrac{1}{n^{\\alpha}}\\) 绝对收敛，级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}(-1)^{n}\\dfrac{1}{n^{2-\\alpha}}\\) 条件收敛，则 \\(\\alpha\\) 的范围是（　　）","opts":["\\(\\alpha>\\dfrac{3}{2}\\)","\\(\\dfrac{3}{2}\\le\\alpha<2\\)","\\(\\alpha<2\\)","\\(\\dfrac{3}{2}<\\alpha<2\\)"],"ans":3,"sol":"<p>当 \\(n\\to\\infty\\) 时 \\(\\sqrt n\\sin\\dfrac{1}{n^\\alpha}\\sim n^{\\frac12-\\alpha}\\)，绝对收敛要求 \\(\\dfrac12-\\alpha<-1\\) 即 \\(\\alpha>\\dfrac32\\)；\\(\\sum(-1)^n\\dfrac{1}{n^{2-\\alpha}}\\) 条件收敛要求 \\(0<2-\\alpha\\le1\\) 即 \\(1\\le\\alpha<2\\)。取交集得 \\(\\dfrac32<\\alpha<2\\)。选 D。</p>","id":"c151"},{"ty":"choice","ch":12,"kp":"几何级数","src":"小测第12单元","diff":1,"q":"若级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{a}{q^{n}}\\) 收敛（\\(a\\) 为常数），则 \\(q\\) 满足条件是（　　）","opts":["\\(q=1\\)","\\(|q|>1\\)","\\(|q|<1\\)","\\(q=-1\\)"],"ans":1,"sol":"<p>这是公比为 \\(\\dfrac1q\\) 的几何级数，收敛要求 \\(\\left|\\dfrac1q\\right|<1\\) 即 \\(|q|>1\\)。选 B。</p>","id":"c152"},{"ty":"choice","ch":12,"kp":"交错级数","src":"小测第12单元","diff":2,"q":"设 \\(u_n=(-1)^{n}\\tan\\dfrac{1}{n}\\)，则（　　）","opts":["\\(\\sum u_n\\) 收敛，而 \\(\\sum u_n^{2}\\) 发散","\\(\\sum u_n\\) 与 \\(\\sum u_n^{2}\\) 都发散","\\(\\sum u_n\\) 发散，而 \\(\\sum u_n^{2}\\) 收敛","\\(\\sum u_n\\) 与 \\(\\sum u_n^{2}\\) 都收敛"],"ans":3,"sol":"<p>\\(\\tan\\dfrac1n\\) 单调递减趋于 0，由莱布尼茨判别法 \\(\\sum u_n\\) 收敛；\\(u_n^2=\\tan^2\\dfrac1n\\sim\\dfrac{1}{n^2}\\)，故 \\(\\sum u_n^2\\) 收敛。选 D。</p>","id":"c153"},{"ty":"choice","ch":12,"kp":"级数性质","src":"小测第12单元","diff":3,"q":"若级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}a_{n}\\) 收敛，则下列级数中必收敛的是（　　）","opts":["\\(\\displaystyle\\sum_{n=1}^{\\infty}(-1)^{n}a_{n}\\)","\\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{a_{n}+a_{n+1}}{2}\\)","\\(\\displaystyle\\sum_{n=1}^{\\infty}a_{n}a_{n+1}\\)","\\(\\displaystyle\\sum_{n=1}^{\\infty}|a_{n}|\\)"],"ans":1,"sol":"<p>\\(\\displaystyle\\sum\\dfrac{a_n+a_{n+1}}{2}=\\dfrac12\\sum a_n+\\dfrac12\\sum a_{n+1}\\)，收敛级数的线性组合仍收敛。A、C、D 取 \\(a_n=\\dfrac{(-1)^n}{n}\\) 均发散或不确定。选 B。</p>","id":"c154"},{"ty":"choice","ch":12,"kp":"收敛半径","src":"小测第12单元","diff":2,"q":"设幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}a_{n}x^{n}\\) 的收敛半径为 \\(R\\)（\\(0&lt;R<+\\infty\\)），则幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}a_{n}\\left(\\dfrac{x}{2}\\right)^{n}\\) 的收敛半径为（　　）","opts":["\\(\\dfrac{2}{R}\\)","\\(\\dfrac{R}{2}\\)","\\(R\\)","\\(2R\\)"],"ans":3,"sol":"<p>新级数即 \\(\\displaystyle\\sum \\dfrac{a_n}{2^n}x^n\\)，系数缩小 \\(2^n\\) 倍，收敛半径扩大 2 倍，为 \\(2R\\)。选 D。</p>","id":"c155"},{"ty":"choice","ch":12,"kp":"收敛半径","src":"小测第12单元","diff":3,"q":"已知幂级数 \\(\\displaystyle\\sum_{n=0}^{\\infty}a_{n}(x+2)^{n}\\) 在 \\(x=0\\) 处发散，在 \\(x=-4\\) 处收敛，则幂级数 \\(\\displaystyle\\sum_{n=0}^{\\infty}na_{n}x^{n}\\) 的收敛半径为（　　）","opts":["\\(1\\)","\\(2\\)","\\(+\\infty\\)","不能确定"],"ans":1,"sol":"<p>对 \\(\\sum a_n(x+2)^n\\)，中心为 \\(-2\\)；\\(x=-4\\) 与 \\(x=0\\) 到中心的距离均为 2。在左端点收敛得 \\(R\\ge2\\)，在右端点发散得 \\(R\\le2\\)，故 \\(R=2\\)。而 \\(\\sum na_nx^n\\) 与 \\(\\sum a_nx^n\\) 的收敛半径相同，为 2。选 B。</p>","id":"c156"},{"ty":"choice","ch":12,"kp":"数项级数求和","src":"教材经典","diff":1,"q":"级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{1}{n(n+1)}\\) 的和为","opts":["\\(1\\)","\\(2\\)","\\(\\dfrac{1}{2}\\)","发散"],"ans":0,"sol":"<p>裂项 \\(\\dfrac{1}{n(n+1)}=\\dfrac1n-\\dfrac{1}{n+1}\\)，部分和 \\(S_N=1-\\dfrac{1}{N+1}\\to1\\)。选 A。</p>","id":"c157"},{"ty":"choice","ch":12,"kp":"交错级数","src":"教材经典","diff":2,"q":"级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{(-1)^{n}}{n^{p}}\\) 条件收敛的充分必要条件是","opts":["\\(0&lt;p\\le1\\)","\\(p>1\\)","\\(p\\le0\\)","\\(p>0\\)"],"ans":0,"sol":"<p>\\(p>1\\) 时绝对收敛；\\(0&lt;p\\le1\\) 时由莱布尼茨判别法收敛但 \\(\\sum\\dfrac{1}{n^p}\\) 发散，为条件收敛；\\(p\\le0\\) 时通项不趋于 0，发散。选 A。</p>","id":"c158"},{"ty":"choice","ch":12,"kp":"傅里叶级数","src":"教材经典","diff":2,"q":"设 \\(f(x)=x^{2}\\ (-\\pi\\le x<\\pi)\\) 展开成傅里叶级数，则该级数在 \\(x=\\pi\\) 处收敛于","opts":["\\(\\pi^{2}\\)","\\(0\\)","\\(-\\pi^{2}\\)","\\(\\dfrac{\\pi^{2}}{2}\\)"],"ans":0,"sol":"<p>由狄利克雷收敛定理，在端点 \\(x=\\pi\\) 处收敛于 \\(\\dfrac{f(\\pi^-)+f(-\\pi^+)}{2}=\\dfrac{\\pi^2+\\pi^2}{2}=\\pi^2\\)。选 A。</p>","id":"c159"},{"ty":"choice","ch":12,"kp":"比较判别法","src":"真题改编","diff":2,"q":"级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{n\\cos^{2}n}{n^{3}+1}\\) 的敛散性为","opts":["收敛","发散","条件收敛","不能确定"],"ans":0,"sol":"<p>\\(0\\le\\dfrac{n\\cos^2n}{n^3+1}\\le\\dfrac{n}{n^3}=\\dfrac{1}{n^2}\\)，由比较判别法及 \\(p\\)-级数（\\(p=2\\)）收敛知原级数收敛。选 A。</p>","id":"c160"},{"ty":"choice","ch":12,"kp":"收敛域","src":"真题改编","diff":2,"q":"幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{(-1)^{n}}{n}x^{n}\\) 的收敛域为","opts":["\\((-1,1]\\)","\\([-1,1)\\)","\\((-1,1)\\)","\\([-1,1]\\)"],"ans":0,"sol":"<p>收敛半径 \\(R=1\\)；\\(x=1\\) 时为 \\(\\sum\\dfrac{(-1)^n}{n}\\) 收敛，\\(x=-1\\) 时为 \\(\\sum\\dfrac1n\\) 发散，故收敛域为 \\((-1,1]\\)。选 A。</p>","id":"c161"},{"ty":"choice","ch":12,"kp":"数项级数求和","src":"吉米多维奇精选","diff":2,"q":"级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{2n-1}{2^{n}}\\) 的和为","opts":["\\(3\\)","\\(2\\)","\\(\\dfrac{5}{2}\\)","\\(1\\)"],"ans":0,"sol":"<p>\\(\\displaystyle\\sum_{n\\ge1}\\dfrac{n}{2^n}=\\dfrac{x}{(1-x)^2}\\Big|_{x=1/2}=2\\)，\\(\\displaystyle\\sum_{n\\ge1}\\dfrac{1}{2^n}=1\\)，故和 \\(=2\\times2-1=3\\)。选 A。</p>","id":"c162"}];

window.XDBANK_OBJ.blank = [{"ty":"blank","ch":1,"kp":"等价无穷小","src":"教材经典","diff":1,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{e^{2x}-1}{\\sin 3x}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{2}{3}\\)","sol":"\\(e^{2x}-1\\sim 2x\\)，\\(\\sin 3x\\sim 3x\\)，极限 \\(=\\dfrac23\\)。","id":"b1"},{"ty":"blank","ch":1,"kp":"无穷间断点","src":"教材经典","diff":2,"q":"函数 \\(f(x)=\\dfrac{x^{2}-1}{x^{2}-3x+2}\\) 的无穷间断点为 \\(x=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"2","sol":"\\(f(x)=\\dfrac{(x-1)(x+1)}{(x-1)(x-2)}=\\dfrac{x+1}{x-2}\\)（\\(x\\ne1\\)）。\\(x=1\\) 处极限为 \\(-2\\)，是可去间断点；\\(x=2\\) 处分母为零分子非零，\\(f\\to\\infty\\)，为无穷间断点。","id":"b2"},{"ty":"blank","ch":1,"kp":"重要极限","src":"真题改编","diff":2,"q":"\\(\\lim\\limits_{x\\to\\infty}\\left(\\dfrac{x+3}{x-1}\\right)^{x}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(e^{4}\\)","sol":"原式 \\(=\\dfrac{\\left(1+\\frac3x\\right)^x}{\\left(1-\\frac1x\\right)^x}\\)，分子 \\(\\to e^3\\)，分母 \\(\\to e^{-1}\\)，故极限 \\(=e^4\\)。","id":"b3"},{"ty":"blank","ch":1,"kp":"待定系数求极限","src":"真题改编","diff":2,"q":"若 \\(\\lim\\limits_{x\\to 1}\\dfrac{x^{2}+ax+b}{1-x}=5\\)，则 \\(a=\\)\\(\\underline{\\hspace{2em}}\\)，\\(b=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(a=-7\\)，\\(b=6\\)","sol":"分母 \\(\\to 0\\) 而极限存在，故分子 \\(\\to 0\\)：\\(1+a+b=0\\)。于是 \\(x^2+ax+b=(x-1)(x+c)\\)，\\(\\dfrac{x^2+ax+b}{1-x}=-(x+c)\\to-(1+c)=5\\)，得 \\(c=-6\\)，故 \\(a=-7\\)，\\(b=6\\)。验证：\\(x^2-7x+6=(x-1)(x-6)\\)，商 \\(=-(x-6)\\to 5\\)。✓","id":"b4"},{"ty":"blank","ch":1,"kp":"极限计算","src":"吉米多维奇精选","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{e^{x}+e^{-x}-2}{x^{2}}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"1","sol":"两次洛必达：\\(\\dfrac{e^x-e^{-x}}{2x}\\to\\dfrac{e^x+e^{-x}}{2}\\to 1\\)；或用泰勒展开 \\(e^x+e^{-x}=2+x^2+o(x^2)\\)。","id":"b5"},{"ty":"blank","ch":1,"kp":"夹逼准则","src":"吉米多维奇精选","diff":3,"q":"\\(\\lim\\limits_{n\\to\\infty}\\sum\\limits_{k=1}^{n}\\dfrac{1}{\\sqrt{n^{2}+k}}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"1","sol":"对每个 \\(k\\)：\\(\\dfrac{n}{\\sqrt{n^2+n}}\\le\\displaystyle\\sum_{k=1}^{n}\\dfrac{1}{\\sqrt{n^2+k}}\\le\\dfrac{n}{\\sqrt{n^2+1}}\\)，两端均趋于 1，由夹逼准则极限为 1。","id":"b6"},{"ty":"blank","ch":2,"kp":"导数计算","src":"教材经典","diff":1,"q":"设 \\(f(x)=x^{2}e^{-x}\\)，则 \\(f'(1)=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(e^{-1}\\)（即 \\(\\dfrac{1}{e}\\)）","sol":"\\(f'(x)=(2x-x^2)e^{-x}\\)，\\(f'(1)=(2-1)e^{-1}=e^{-1}\\)。","id":"b7"},{"ty":"blank","ch":2,"kp":"切线方程","src":"教材经典","diff":1,"q":"曲线 \\(y=\\ln x\\) 上切线平行于直线 \\(y=x\\) 的点为\\(\\underline{\\hspace{2em}}\\)。","ans":"\\((1,0)\\)","sol":"\\(y'=\\dfrac{1}{x}=1\\) 得 \\(x=1\\)，\\(y=\\ln 1=0\\)，该点为 \\((1,0)\\)。","id":"b8"},{"ty":"blank","ch":2,"kp":"隐函数求导","src":"教材经典","diff":1,"q":"方程 \\(x^{2}+y^{2}=4\\) 确定 \\(y=y(x)\\)，则 \\(\\dfrac{dy}{dx}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(-\\dfrac{x}{y}\\)","sol":"两边对 \\(x\\) 求导：\\(2x+2yy'=0\\)，得 \\(y'=-\\dfrac{x}{y}\\)。","id":"b9"},{"ty":"blank","ch":2,"kp":"导数定义","src":"真题改编","diff":2,"q":"设 \\(f'(0)\\) 存在且 \\(f(0)=0\\)，则 \\(\\lim\\limits_{x\\to 0}\\dfrac{f(2x)}{x}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(2f'(0)\\)","sol":"原式 \\(=2\\lim\\limits_{x\\to0}\\dfrac{f(2x)-f(0)}{2x}=2f'(0)\\)。","id":"b10"},{"ty":"blank","ch":2,"kp":"高阶导数","src":"吉米多维奇精选","diff":3,"q":"设 \\(y=\\sin^{2}x\\)，则 \\(y^{(n)}=\\)\\(\\underline{\\hspace{2em}}\\)（\\(n\\ge 1\\)）。","ans":"\\(-2^{n-1}\\cos\\left(2x+\\dfrac{n\\pi}{2}\\right)\\)","sol":"\\(y=\\dfrac{1-\\cos 2x}{2}\\)，而 \\((\\cos 2x)^{(n)}=2^n\\cos\\left(2x+\\dfrac{n\\pi}{2}\\right)\\)，故 \\(y^{(n)}=-2^{n-1}\\cos\\left(2x+\\dfrac{n\\pi}{2}\\right)\\)。","id":"b11"},{"ty":"blank","ch":2,"kp":"参数方程求导","src":"吉米多维奇精选","diff":2,"q":"设 \\(\\begin{cases}x=\\ln(1+t^{2}),\\\\ y=t-\\arctan t,\\end{cases}\\) 则 \\(\\dfrac{dy}{dx}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{t}{2}\\)","sol":"\\(\\dfrac{dy}{dt}=1-\\dfrac{1}{1+t^2}=\\dfrac{t^2}{1+t^2}\\)，\\(\\dfrac{dx}{dt}=\\dfrac{2t}{1+t^2}\\)，故 \\(\\dfrac{dy}{dx}=\\dfrac{t}{2}\\)。","id":"b12"},{"ty":"blank","ch":3,"kp":"单调区间","src":"教材经典","diff":1,"q":"函数 \\(y=2x^{3}-6x^{2}+7\\) 的单调减少区间为\\(\\underline{\\hspace{2em}}\\)。","ans":"\\((0,2)\\)","sol":"\\(y'=6x^2-12x=6x(x-2)\\)，当 \\(0&lt;x<2\\) 时 \\(y'<0\\)，故单调减少区间为 \\((0,2)\\)。","id":"b13"},{"ty":"blank","ch":3,"kp":"拐点","src":"教材经典","diff":1,"q":"曲线 \\(y=x^{3}-3x^{2}+3x+1\\) 的拐点为\\(\\underline{\\hspace{2em}}\\)。","ans":"\\((1,2)\\)","sol":"\\(y''=6x-6\\)，\\(x=1\\) 处为零且两侧变号（\\(y'''=6\\ne0\\)），\\(y(1)=2\\)，拐点为 \\((1,2)\\)。","id":"b14"},{"ty":"blank","ch":3,"kp":"极值计算","src":"真题改编","diff":2,"q":"函数 \\(f(x)=x+\\dfrac{2}{x}\\)（\\(x>0\\)）的极小值为\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(2\\sqrt{2}\\)","sol":"\\(f'(x)=1-\\dfrac{2}{x^2}=0\\) 得 \\(x=\\sqrt2\\)；\\(f''(x)=\\dfrac{4}{x^3}>0\\)，为极小值 \\(f(\\sqrt2)=\\sqrt2+\\dfrac{2}{\\sqrt2}=2\\sqrt2\\)。（也可由均值不等式直接得 \\(x+\\dfrac2x\\ge 2\\sqrt2\\)。）","id":"b15"},{"ty":"blank","ch":3,"kp":"洛必达法则","src":"真题改编","diff":2,"q":"\\(\\lim\\limits_{x\\to 1}x^{\\frac{1}{x-1}}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(e\\)","sol":"取对数：\\(\\ln L=\\lim\\limits_{x\\to1}\\dfrac{\\ln x}{x-1}=\\lim\\limits_{x\\to1}\\dfrac{1/x}{1}=1\\)（洛必达），故 \\(L=e\\)。","id":"b16"},{"ty":"blank","ch":3,"kp":"极限计算","src":"吉米多维奇精选","diff":2,"q":"\\(\\lim\\limits_{x\\to 0}\\dfrac{x-\\arctan x}{x^{3}}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{3}\\)","sol":"由泰勒公式 \\(\\arctan x=x-\\dfrac{x^3}{3}+o(x^3)\\)，故 \\(x-\\arctan x\\sim\\dfrac{x^3}{3}\\)，极限为 \\(\\dfrac13\\)（也可用洛必达三次验证）。","id":"b17"},{"ty":"blank","ch":3,"kp":"罗尔定理","src":"吉米多维奇精选","diff":2,"q":"\\(f(x)=\\ln\\sin x\\) 在 \\(\\left[\\dfrac{\\pi}{6},\\dfrac{5\\pi}{6}\\right]\\) 上满足罗尔定理，则 \\(\\xi=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{\\pi}{2}\\)","sol":"\\(f\\left(\\frac\\pi6\\right)=f\\left(\\frac{5\\pi}6\\right)=\\ln\\dfrac12\\)，且 \\(f\\) 在该区间连续、可导。\\(f'(x)=\\cot x=0\\) 得 \\(x=\\dfrac{\\pi}{2}\\in\\left(\\dfrac\\pi6,\\dfrac{5\\pi}6\\right)\\)，即 \\(\\xi=\\dfrac\\pi2\\)。","id":"b18"},{"ty":"blank","ch":4,"kp":"换元积分","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\int\\dfrac{\\ln x}{x}\\,dx=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}\\ln^{2}x+C\\)","sol":"\\(\\displaystyle\\int\\ln x\\,d(\\ln x)=\\dfrac{1}{2}\\ln^2 x+C\\)。","id":"b19"},{"ty":"blank","ch":4,"kp":"有理函数积分","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\int\\dfrac{dx}{x^{2}+2x+5}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}\\arctan\\dfrac{x+1}{2}+C\\)","sol":"\\(x^2+2x+5=(x+1)^2+4\\)，原式 \\(=\\dfrac12\\displaystyle\\int\\dfrac{d(x+1)}{\\left(\\frac{x+1}{2}\\right)^2+1}=\\dfrac12\\arctan\\dfrac{x+1}{2}+C\\)。","id":"b20"},{"ty":"blank","ch":4,"kp":"分部积分","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\int x\\cos x\\,dx=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(x\\sin x+\\cos x+C\\)","sol":"分部：原式 \\(=\\displaystyle\\int x\\,d(\\sin x)=x\\sin x-\\displaystyle\\int\\sin x\\,dx=x\\sin x+\\cos x+C\\)。","id":"b21"},{"ty":"blank","ch":4,"kp":"不定积分应用","src":"教材经典","diff":1,"q":"曲线过点 \\((1,2)\\) 且其上任一点处的切线斜率为 \\(3x^{2}\\)，则曲线方程为 \\(y=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(x^{3}+1\\)","sol":"由 \\(y'=3x^2\\) 得 \\(y=x^3+C\\)；代入 \\((1,2)\\)：\\(1+C=2\\)，\\(C=1\\)，故 \\(y=x^3+1\\)。","id":"b22"},{"ty":"blank","ch":4,"kp":"不定积分概念","src":"真题改编","diff":2,"q":"\\(\\displaystyle\\int f'(2x)\\,dx=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}f(2x)+C\\)","sol":"\\(\\displaystyle\\int f'(2x)\\,dx=\\dfrac12\\displaystyle\\int f'(2x)\\,d(2x)=\\dfrac12 f(2x)+C\\)。验证：\\(\\left[\\dfrac12 f(2x)\\right]'=\\dfrac12\\cdot 2f'(2x)=f'(2x)\\)。✓","id":"b23"},{"ty":"blank","ch":4,"kp":"三角积分","src":"吉米多维奇精选","diff":2,"q":"\\(\\displaystyle\\int\\dfrac{dx}{1+\\cos x}=\\)\\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\tan\\dfrac{x}{2}+C\\)","sol":"\\(1+\\cos x=2\\cos^2\\dfrac{x}{2}\\)，原式 \\(=\\dfrac12\\displaystyle\\int\\sec^2\\dfrac{x}{2}\\,dx=\\tan\\dfrac{x}{2}+C\\)。","id":"b24"},{"ty":"blank","ch":5,"kp":"分部积分","src":"教材经典","diff":2,"q":"\\(\\int_0^{\\pi} x\\sin x\\,dx =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\pi\\)","sol":"<p>分部积分：\\(\\int_0^{\\pi}x\\sin x\\,dx = [-x\\cos x]_0^{\\pi}+\\int_0^{\\pi}\\cos x\\,dx = \\pi+0 = \\pi\\)。</p>","id":"b25"},{"ty":"blank","ch":5,"kp":"换元积分","src":"教材经典","diff":2,"q":"\\(\\int_0^{\\ln 2} e^x(1+e^x)^2\\,dx =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{19}{3}\\)","sol":"<p>令 \\(u=1+e^x\\)，\\(du=e^x dx\\)，\\(x:0\\to\\ln 2\\) 对应 \\(u:2\\to 3\\)。\\(\\int_2^3 u^2 du = \\dfrac{27-8}{3}=\\dfrac{19}{3}\\)。</p>","id":"b26"},{"ty":"blank","ch":5,"kp":"定积分定义","src":"真题改编","diff":3,"q":"\\(\\lim\\limits_{n\\to\\infty}\\sum\\limits_{i=1}^{n}\\dfrac{n}{n^2+i^2} =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{\\pi}{4}\\)","sol":"<p>\\(\\dfrac{n}{n^2+i^2}=\\dfrac{1}{n}\\cdot\\dfrac{1}{1+(i/n)^2}\\)，极限即 \\(\\int_0^1 \\dfrac{dx}{1+x^2}=\\dfrac{\\pi}{4}\\)。</p>","id":"b27"},{"ty":"blank","ch":5,"kp":"变限积分求导","src":"真题改编","diff":2,"q":"\\(\\dfrac{d}{dx}\\displaystyle\\int_0^{x^2}\\sqrt{1+t^3}\\,dt =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(2x\\sqrt{1+x^6}\\)","sol":"<p>由链式法则：\\(\\sqrt{1+(x^2)^3}\\cdot(x^2)' = 2x\\sqrt{1+x^6}\\)。</p>","id":"b28"},{"ty":"blank","ch":5,"kp":"奇偶对称性","src":"吉米多维奇精选","diff":2,"q":"\\(\\int_{-1}^{1}\\left(x+\\sqrt{1-x^2}\\right)^2 dx =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"2","sol":"<p>展开：\\(x^2+2x\\sqrt{1-x^2}+(1-x^2)=1+2x\\sqrt{1-x^2}\\)。第二项为奇函数，积分为 0，故原式 \\(=\\int_{-1}^{1}1\\,dx = 2\\)。</p>","id":"b29"},{"ty":"blank","ch":5,"kp":"反常积分","src":"吉米多维奇精选","diff":3,"q":"\\(\\int_1^{+\\infty}\\dfrac{dx}{x(1+x^2)} =\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}\\ln 2\\)","sol":"<p>\\(\\dfrac{1}{x(1+x^2)}=\\dfrac{1}{x}-\\dfrac{x}{1+x^2}\\)，原积分 \\(=\\left[\\ln x-\\dfrac{1}{2}\\ln(1+x^2)\\right]_1^{+\\infty} = 0-(-\\dfrac{1}{2}\\ln 2)=\\dfrac{1}{2}\\ln 2\\)。</p>","id":"b30"},{"ty":"blank","ch":6,"kp":"平面图形面积","src":"教材经典","diff":2,"q":"曲线 \\(y=x^3\\) 与直线 \\(y=x\\) 围成图形的面积为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}\\)","sol":"<p>交点 \\(x=-1,0,1\\)。由对称性 \\(S=2\\int_0^1 (x-x^3)dx = 2(\\dfrac{1}{2}-\\dfrac{1}{4})=\\dfrac{1}{2}\\)。</p>","id":"b31"},{"ty":"blank","ch":6,"kp":"极坐标面积","src":"教材经典","diff":2,"q":"心形线 \\(r=2a(1+\\cos\\theta)\\;(a>0)\\) 所围图形的面积为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(6\\pi a^2\\)","sol":"<p>\\(S=\\dfrac{1}{2}\\int_0^{2\\pi}4a^2(1+\\cos\\theta)^2 d\\theta = 2a^2(2\\pi+\\pi)=6\\pi a^2\\)（其中 \\(\\int_0^{2\\pi}\\cos^2\\theta\\,d\\theta=\\pi\\)）。</p>","id":"b32"},{"ty":"blank","ch":6,"kp":"弧长","src":"教材经典","diff":2,"q":"曲线 \\(y=\\dfrac{2}{3}x^{3/2}\\) 在 \\([0,3]\\) 上的弧长为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{14}{3}\\)","sol":"<p>\\(y'=x^{1/2}\\)，\\(s=\\int_0^3\\sqrt{1+x}\\,dx = \\dfrac{2}{3}(1+x)^{3/2}\\Big|_0^3 = \\dfrac{2}{3}(8-1)=\\dfrac{14}{3}\\)。</p>","id":"b33"},{"ty":"blank","ch":6,"kp":"旋转体体积","src":"教材经典","diff":1,"q":"曲线 \\(y=\\sqrt{x}\\) 在 \\([0,4]\\) 上绕 \\(x\\) 轴旋转一周所得旋转体体积为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(8\\pi\\)","sol":"<p>\\(V=\\pi\\int_0^4 (\\sqrt{x})^2 dx = \\pi\\int_0^4 x\\,dx = 8\\pi\\)。</p>","id":"b34"},{"ty":"blank","ch":6,"kp":"旋转体体积","src":"真题改编","diff":2,"q":"由曲线 \\(y=e^x\\)、直线 \\(x=0\\)、\\(x=1\\) 及 \\(x\\) 轴围成的图形绕 \\(x\\) 轴旋转一周所得体积为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{\\pi}{2}(e^2-1)\\)","sol":"<p>\\(V=\\pi\\int_0^1 e^{2x}dx = \\dfrac{\\pi}{2}[e^{2x}]_0^1 = \\dfrac{\\pi}{2}(e^2-1)\\)。</p>","id":"b35"},{"ty":"blank","ch":6,"kp":"变力做功","src":"真题改编","diff":2,"q":"一弹簧在压缩过程中所受弹力满足胡克定律 \\(F=kx\\)（\\(k=200\\,\\mathrm{N/m}\\)），将弹簧从原长压缩 \\(0.1\\,\\mathrm{m}\\) 所做的功为 \\(\\underline{\\hspace{2em}}\\) 焦耳。","ans":"1","sol":"<p>\\(W=\\int_0^{0.1}200x\\,dx = 100x^2\\Big|_0^{0.1} = 1\\) 焦耳。</p>","id":"b36"},{"ty":"blank","ch":7,"kp":"可分离变量","src":"教材经典","diff":1,"q":"微分方程 \\(y'+y\\tan x=0\\) 的通解为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(y=C\\cos x\\)","sol":"<p>分离变量 \\(\\dfrac{dy}{y}=-\\tan x\\,dx\\)，积分得 \\(\\ln|y|=\\ln|\\cos x|+C_1\\)，即 \\(y=C\\cos x\\)。</p>","id":"b37"},{"ty":"blank","ch":7,"kp":"直接积分","src":"教材经典","diff":2,"q":"方程 \\(y'''=\\sin x\\) 的通解为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(y=\\cos x+\\dfrac{C_1}{2}x^2+C_2x+C_3\\)","sol":"<p>逐次积分：\\(y''=-\\cos x+C_1\\)，\\(y'=-\\sin x+C_1x+C_2\\)，\\(y=\\cos x+\\dfrac{C_1}{2}x^2+C_2x+C_3\\)。</p>","id":"b38"},{"ty":"blank","ch":7,"kp":"二阶齐次方程","src":"教材经典","diff":2,"q":"微分方程 \\(y''+2y'+5y=0\\) 的通解为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(y=e^{-x}(C_1\\cos 2x+C_2\\sin 2x)\\)","sol":"<p>特征方程 \\(r^2+2r+5=0\\)，\\(r=-1\\pm 2i\\)，通解 \\(y=e^{-x}(C_1\\cos 2x+C_2\\sin 2x)\\)。</p>","id":"b39"},{"ty":"blank","ch":7,"kp":"初值问题","src":"真题改编","diff":2,"q":"方程 \\(y''=e^{2x}\\) 满足 \\(y(0)=0\\)、\\(y'(0)=0\\) 的特解为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(y=\\dfrac{e^{2x}-2x-1}{4}\\)","sol":"<p>\\(y'=\\dfrac{e^{2x}}{2}+C_1\\)，由 \\(y'(0)=0\\) 得 \\(C_1=-\\dfrac{1}{2}\\)；再积分 \\(y=\\dfrac{e^{2x}}{4}-\\dfrac{x}{2}+C_2\\)，由 \\(y(0)=0\\) 得 \\(C_2=-\\dfrac{1}{4}\\)。</p>","id":"b40"},{"ty":"blank","ch":7,"kp":"待定特解","src":"真题改编","diff":2,"q":"方程 \\(y''-y=e^x\\) 的一个特解为 \\(y^*=\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\dfrac{1}{2}xe^x\\)","sol":"<p>特征根 \\(r=\\pm 1\\)，\\(\\lambda=1\\) 为单根，设 \\(y^*=axe^x\\)。代入：\\(a(x+2)e^x-axe^x=2ae^x=e^x\\)，得 \\(a=\\dfrac{1}{2}\\)。</p>","id":"b41"},{"ty":"blank","ch":7,"kp":"一阶线性方程","src":"吉米多维奇精选","diff":2,"q":"微分方程 \\(y'+2xy=xe^{-x^2}\\) 的通解为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(y=\\left(\\dfrac{x^2}{2}+C\\right)e^{-x^2}\\)","sol":"<p>积分因子 \\(e^{x^2}\\)：\\((ye^{x^2})'=x\\)，\\(ye^{x^2}=\\dfrac{x^2}{2}+C\\)，故 \\(y=(\\dfrac{x^2}{2}+C)e^{-x^2}\\)。</p>","id":"b42"},{"ty":"blank","ch":8,"kp":"单位向量","src":"教材经典","diff":1,"q":"与向量 \\(\\vec{a}=(1,-2,2)\\) 同方向的单位向量为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\((\\dfrac{1}{3},-\\dfrac{2}{3},\\dfrac{2}{3})\\)","sol":"<p>\\(|\\vec{a}|=\\sqrt{1+4+4}=3\\)，单位向量 \\(\\vec{a}^{\\circ}=\\dfrac{\\vec{a}}{|\\vec{a}|}=(\\dfrac{1}{3},-\\dfrac{2}{3},\\dfrac{2}{3})\\)。</p>","id":"b43"},{"ty":"blank","ch":8,"kp":"平面方程","src":"教材经典","diff":2,"q":"过点 \\((1,0,2)\\) 且与向量 \\(\\vec{a}=(1,2,1)\\)、\\(\\vec{b}=(0,1,1)\\) 都平行的平面方程为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(x-y+z-3=0\\)","sol":"<p>\\(\\vec{n}=\\vec{a}\\times\\vec{b}=(1,-1,1)\\)，点法式 \\((x-1)-y+(z-2)=0\\)，即 \\(x-y+z-3=0\\)。</p>","id":"b44"},{"ty":"blank","ch":8,"kp":"平面截距","src":"教材经典","diff":1,"q":"平面 \\(x+2y-z+3=0\\) 在 \\(z\\) 轴上的截距为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(3\\)","sol":"<p>令 \\(x=y=0\\)：\\(-z+3=0\\)，\\(z=3\\)。</p>","id":"b45"},{"ty":"blank","ch":8,"kp":"向量平行","src":"真题改编","diff":1,"q":"若 \\(\\vec{a}=(2,-1,3)\\) 与 \\(\\vec{b}=(4,m,6)\\) 平行，则 \\(m=\\) \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(-2\\)","sol":"<p>由对应坐标成比例：\\(\\dfrac{4}{2}=\\dfrac{m}{-1}=\\dfrac{6}{3}=2\\)，故 \\(m=-2\\)。</p>","id":"b46"},{"ty":"blank","ch":8,"kp":"两平面夹角","src":"真题改编","diff":2,"q":"平面 \\(x-y+z-1=0\\) 与平面 \\(x+y-z+2=0\\) 的夹角为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\arccos\\dfrac{1}{3}\\)","sol":"<p>\\(\\vec{n}_1=(1,-1,1)\\)、\\(\\vec{n}_2=(1,1,-1)\\)，\\(\\cos\\theta=\\dfrac{|\\vec{n}_1\\cdot\\vec{n}_2|}{|\\vec{n}_1||\\vec{n}_2|}=\\dfrac{|1-1-1|}{3}=\\dfrac{1}{3}\\)，夹角 \\(\\theta=\\arccos\\dfrac{1}{3}\\)。</p>","id":"b47"},{"ty":"blank","ch":8,"kp":"球面截线","src":"吉米多维奇精选","diff":2,"q":"球面 \\(x^2+y^2+z^2=4\\) 被平面 \\(z=1\\) 截得的交线圆的半径为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\(\\sqrt{3}\\)","sol":"<p>球心到平面距离 \\(d=1\\)，球半径 \\(R=2\\)，交线圆半径 \\(r=\\sqrt{R^2-d^2}=\\sqrt{3}\\)。</p>","id":"b48"},{"ty":"blank","ch":9,"kp":"全微分","src":"教材经典","diff":2,"q":"设 \\(z=\\arctan\\dfrac{y}{x}\\)，则 \\(dz=\\underline{\\hspace{2em}}\\)。","ans":"\\dfrac{-y\\,dx+x\\,dy}{x^{2}+y^{2}}","sol":"<p>\\(z_x=\\dfrac{-y}{x^2+y^2}\\)，\\(z_y=\\dfrac{x}{x^2+y^2}\\)，故 \\(dz=\\dfrac{-y\\,dx+x\\,dy}{x^2+y^2}\\)。</p>","id":"b49"},{"ty":"blank","ch":9,"kp":"空间曲线切线","src":"教材经典","diff":1,"q":"曲线 \\(x=t,\\ y=t^{2},\\ z=t^{3}\\) 在点 \\((1,1,1)\\) 处的切线方向向量为 \\(\\underline{\\hspace{2em}}\\)。","ans":"(1,\\ 2,\\ 3)","sol":"<p>对应 \\(t=1\\)，切向量为 \\((x',y',z')=(1,2t,3t^2)\\big|_{t=1}=(1,2,3)\\)。</p>","id":"b50"},{"ty":"blank","ch":9,"kp":"复合函数求导","src":"教材经典","diff":2,"q":"设 \\(z=f\\left(xy,\\dfrac{x}{y}\\right)\\)，其中 \\(f\\) 可微，则 \\(\\dfrac{\\partial z}{\\partial x}=\\underline{\\hspace{2em}}\\)。","ans":"y f_1'+\\dfrac{1}{y}f_2'","sol":"<p>链式法则：\\(\\dfrac{\\partial z}{\\partial x}=f_1'\\cdot y+f_2'\\cdot\\dfrac1y=y f_1'+\\dfrac{1}{y}f_2'\\)。</p>","id":"b51"},{"ty":"blank","ch":9,"kp":"无条件极值","src":"教材经典","diff":1,"q":"函数 \\(z=x^{2}+y^{2}-2x+4y+6\\) 的极小值为 \\(\\underline{\\hspace{2em}}\\)。","ans":"1","sol":"<p>\\(z_x=2x-2=0,\\ z_y=2y+4=0\\) 得驻点 \\((1,-2)\\)；\\(AC-B^2=2\\times2=4>0\\) 且 \\(A=2>0\\)，取极小值 \\(z=1+4-2-8+6=1\\)。</p>","id":"b52"},{"ty":"blank","ch":9,"kp":"隐函数求导","src":"真题改编","diff":2,"q":"设 \\(z=z(x,y)\\) 由方程 \\(x^{2}+y^{2}+z^{2}=4z\\) 确定，则 \\(\\dfrac{\\partial z}{\\partial x}=\\underline{\\hspace{2em}}\\)。","ans":"\\dfrac{x}{2-z}","sol":"<p>两边对 \\(x\\) 求导：\\(2x+2z\\,z_x=4z_x\\)，解得 \\(z_x=\\dfrac{x}{2-z}\\)。</p>","id":"b53"},{"ty":"blank","ch":9,"kp":"梯度","src":"真题改编","diff":2,"q":"函数 \\(u=\\ln(x^{2}+y^{2}+z^{2})\\) 在点 \\((1,2,-2)\\) 处的梯度 \\(\\left.\\operatorname{grad}u\\right|_{(1,2,-2)}=\\underline{\\hspace{2em}}\\)。","ans":"\\dfrac{1}{9}(2,\\ 4,\\ -4)","sol":"<p>\\(\\operatorname{grad}u=\\left(\\dfrac{2x}{r^2},\\dfrac{2y}{r^2},\\dfrac{2z}{r^2}\\right)\\)，在 \\((1,2,-2)\\) 处 \\(r^2=9\\)，故梯度为 \\(\\dfrac19(2,4,-4)\\)。</p>","id":"b54"},{"ty":"blank","ch":10,"kp":"交换次序","src":"教材经典","diff":2,"q":"交换积分次序：\\(\\displaystyle\\int_{0}^{1}dy\\int_{y}^{\\sqrt{y}}f(x,y)\\,dx=\\underline{\\hspace{2em}}\\)。","ans":"\\int_{0}^{1}dx\\int_{x^{2}}^{x}f(x,y)\\,dy","sol":"<p>区域为 \\(0\\le y\\le1,\\ y\\le x\\le\\sqrt y\\)，改写为 \\(0\\le x\\le1,\\ x^2\\le y\\le x\\)。</p>","id":"b55"},{"ty":"blank","ch":10,"kp":"直角坐标计算","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\iint_D xy\\,d\\sigma=\\underline{\\hspace{2em}}\\)，其中 \\(D\\) 由 \\(y=x\\)、\\(y=1\\) 与 \\(x=0\\) 围成。","ans":"\\dfrac{1}{8}","sol":"<p>\\(\\displaystyle\\int_0^1 x\\,dx\\int_x^1 y\\,dy=\\int_0^1 x\\cdot\\dfrac{1-x^2}{2}\\,dx=\\dfrac12\\left(\\dfrac12-\\dfrac14\\right)=\\dfrac18\\)。</p>","id":"b56"},{"ty":"blank","ch":10,"kp":"球坐标计算","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\iiint_\\Omega \\sqrt{x^{2}+y^{2}+z^{2}}\\,dV=\\underline{\\hspace{2em}}\\)，其中 \\(\\Omega\\) 为上半球体 \\(x^{2}+y^{2}+z^{2}\\le1,\\ z\\ge0\\)。","ans":"\\dfrac{\\pi}{2}","sol":"<p>球坐标：\\(\\displaystyle\\int_0^{2\\pi}\\!\\!d\\theta\\int_0^{\\frac\\pi2}\\!\\sin\\varphi\\,d\\varphi\\int_0^1\\rho\\cdot\\rho^2\\,d\\rho=2\\pi\\times1\\times\\dfrac14=\\dfrac\\pi2\\)。</p>","id":"b57"},{"ty":"blank","ch":10,"kp":"体积计算","src":"教材经典","diff":1,"q":"由锥面 \\(z=\\sqrt{x^{2}+y^{2}}\\) 与平面 \\(z=1\\) 围成的立体体积为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\dfrac{\\pi}{3}","sol":"<p>底面半径 1、高 1 的圆锥体，\\(V=\\dfrac13\\pi r^2h=\\dfrac\\pi3\\)；或 \\(\\displaystyle\\iint_D(1-\\sqrt{x^2+y^2})\\,d\\sigma=\\pi-\\dfrac{2\\pi}{3}=\\dfrac\\pi3\\)。</p>","id":"b58"},{"ty":"blank","ch":10,"kp":"质心","src":"教材经典","diff":3,"q":"面密度为常数的均匀薄片占有区域 \\(D:\\ x^{2}+y^{2}\\le1\\)（第一象限部分），则其质心坐标 \\((\\bar x,\\bar y)=\\underline{\\hspace{2em}}\\)。","ans":"\\left(\\dfrac{4}{3\\pi},\\ \\dfrac{4}{3\\pi}\\right)","sol":"<p>\\(\\displaystyle\\iint_D x\\,d\\sigma=\\int_0^1 x\\sqrt{1-x^2}\\,dx=\\dfrac13\\)，面积 \\(=\\dfrac\\pi4\\)，故 \\(\\bar x=\\dfrac{1/3}{\\pi/4}=\\dfrac{4}{3\\pi}\\)；由对称性 \\(\\bar y=\\dfrac{4}{3\\pi}\\)。</p>","id":"b59"},{"ty":"blank","ch":10,"kp":"极坐标计算","src":"真题改编","diff":2,"q":"\\(\\displaystyle\\iint_D \\ln(1+x^{2}+y^{2})\\,d\\sigma=\\underline{\\hspace{2em}}\\)，其中 \\(D:\\ x^{2}+y^{2}\\le1\\)。","ans":"\\pi(2\\ln 2-1)","sol":"<p>极坐标：\\(2\\pi\\displaystyle\\int_0^1 r\\ln(1+r^2)\\,dr\\)，令 \\(u=1+r^2\\) 得 \\(\\dfrac12[(1+r^2)\\ln(1+r^2)-(1+r^2)]_0^1=\\ln2-\\dfrac12\\)，故积分为 \\(\\pi(2\\ln2-1)\\)。</p>","id":"b60"},{"ty":"blank","ch":11,"kp":"第一类线积分","src":"教材经典","diff":1,"q":"计算 \\(\\displaystyle\\int_L (x+y)\\,ds\\)，其中 \\(L\\) 为连接点 \\((1,0)\\) 与 \\((0,1)\\) 的直线段，其值为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\sqrt{2}","sol":"<p>直线段 \\(x+y=1\\ (x\\ge0,y\\ge0)\\) 上被积函数恒为 1，线段长 \\(\\sqrt2\\)，故积分为 \\(\\sqrt2\\)。</p>","id":"b61"},{"ty":"blank","ch":11,"kp":"格林公式","src":"教材经典","diff":2,"q":"\\(\\displaystyle\\oint_L y\\,dx=\\underline{\\hspace{2em}}\\)，其中 \\(L\\) 为圆周 \\(x^{2}+y^{2}=1\\) 取正向。","ans":"-\\pi","sol":"<p>由格林公式（\\(P=y,\\ Q=0\\)）：\\(\\displaystyle\\oint_L y\\,dx=\\iint_D\\left(\\dfrac{\\partial Q}{\\partial x}-\\dfrac{\\partial P}{\\partial y}\\right)d\\sigma=\\iint_D(-1)\\,d\\sigma=-\\pi\\)。</p>","id":"b62"},{"ty":"blank","ch":11,"kp":"第一类面积分","src":"教材经典","diff":2,"q":"计算 \\(\\displaystyle\\iint_\\Sigma z\\,dS=\\underline{\\hspace{2em}}\\)，其中 \\(\\Sigma\\) 为上半球面 \\(z=\\sqrt{a^{2}-x^{2}-y^{2}}\\ (a>0)\\)。","ans":"\\pi a^{3}","sol":"<p>\\(dS=\\dfrac{a}{\\sqrt{a^2-x^2-y^2}}\\,dx\\,dy\\)，故 \\(\\displaystyle\\iint_\\Sigma z\\,dS=\\iint_{x^2+y^2\\le a^2}a\\,dx\\,dy=\\pi a^3\\)。</p>","id":"b63"},{"ty":"blank","ch":11,"kp":"高斯公式","src":"教材经典","diff":2,"q":"设 \\(\\Sigma\\) 为球面 \\(x^{2}+y^{2}+z^{2}=a^{2}\\) 的外侧，则 \\(\\displaystyle\\oiint_\\Sigma x\\,dy\\,dz+y\\,dz\\,dx+z\\,dx\\,dy=\\underline{\\hspace{2em}}\\)。","ans":"4\\pi a^{3}","sol":"<p>散度 \\(=1+1+1=3\\)，由高斯公式积分为 \\(3\\times\\dfrac43\\pi a^3=4\\pi a^3\\)。</p>","id":"b64"},{"ty":"blank","ch":11,"kp":"第二类线积分","src":"吉米多维奇精选","diff":3,"q":"计算 \\(\\displaystyle\\int_\\Gamma (y^{2}-z^{2})\\,dx+2yz\\,dy-x^{2}\\,dz\\)，其中 \\(\\Gamma:\\ x=t,\\ y=t^{2},\\ z=t^{3}\\)，\\(t\\) 从 0 到 1，其值为 \\(\\underline{\\hspace{2em}}\\)。","ans":"\\dfrac{1}{35}","sol":"<p>代入得 \\(\\displaystyle\\int_0^1\\left[(t^4-t^6)+2t^2t^3\\cdot2t-t^2\\cdot3t^2\\right]dt=\\int_0^1(3t^6-2t^4)\\,dt=\\dfrac37-\\dfrac25=\\dfrac{1}{35}\\)。</p>","id":"b65"},{"ty":"blank","ch":11,"kp":"高斯公式","src":"吉米多维奇精选","diff":3,"q":"\\(\\displaystyle\\oiint_\\Sigma (x^{2}\\cos\\alpha+y^{2}\\cos\\beta+z^{2}\\cos\\gamma)\\,dS=\\underline{\\hspace{2em}}\\)，其中 \\(\\Sigma\\) 为锥体 \\(x^{2}+y^{2}\\le z^{2},\\ 0\\le z\\le h\\) 的整个表面外侧。","ans":"\\dfrac{\\pi h^{4}}{2}","sol":"<p>由高斯公式，积分 \\(=2\\displaystyle\\iiint_\\Omega(x+y+z)\\,dV\\)。由对称性 \\(x\\)、\\(y\\) 两项为 0，\\(2\\displaystyle\\int_0^h z\\cdot\\pi z^2\\,dz=\\dfrac{2\\pi h^4}{4}=\\dfrac{\\pi h^4}{2}\\)。</p>","id":"b66"},{"ty":"blank","ch":12,"kp":"数项级数求和","src":"教材经典","diff":1,"q":"\\(\\displaystyle\\sum_{n=1}^{\\infty}\\left(\\dfrac{1}{\\sqrt n}-\\dfrac{1}{\\sqrt{n+1}}\\right)=\\underline{\\hspace{2em}}\\)。","ans":"1","sol":"<p>部分和 \\(S_N=1-\\dfrac{1}{\\sqrt{N+1}}\\to1\\)。</p>","id":"b67"},{"ty":"blank","ch":12,"kp":"收敛域","src":"教材经典","diff":1,"q":"幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{x^{n}}{n^{2}}\\) 的收敛域为 \\(\\underline{\\hspace{2em}}\\)。","ans":"[-1,\\ 1]","sol":"<p>收敛半径 \\(R=1\\)；\\(x=\\pm1\\) 时均为 \\(p=2>1\\) 的 \\(p\\)-级数（或其变号形式），绝对收敛，故收敛域为 \\([-1,1]\\)。</p>","id":"b68"},{"ty":"blank","ch":12,"kp":"幂级数展开","src":"教材经典","diff":2,"q":"将 \\(f(x)=\\dfrac{1}{x}\\) 展开成 \\((x-3)\\) 的幂级数：\\(\\dfrac{1}{x}=\\underline{\\hspace{2em}}\\)（需注明收敛范围）。","ans":"\\sum_{n=0}^{\\infty}\\dfrac{(-1)^{n}}{3^{n+1}}(x-3)^{n},\\ |x-3|<3","sol":"<p>\\(\\dfrac1x=\\dfrac13\\cdot\\dfrac{1}{1+\\frac{x-3}{3}}=\\dfrac13\\displaystyle\\sum_{n=0}^{\\infty}\\left(-\\dfrac{x-3}{3}\\right)^n=\\sum\\limits_{n=0}^{\\infty}\\dfrac{(-1)^n}{3^{n+1}}(x-3)^n\\)，收敛范围 \\(\\left|\\dfrac{x-3}{3}\\right|<1\\) 即 \\(|x-3|<3\\)。</p>","id":"b69"},{"ty":"blank","ch":12,"kp":"傅里叶系数","src":"教材经典","diff":2,"q":"设 \\(f(x)=|x|\\ (-\\pi\\le x\\le\\pi)\\) 展开为傅里叶级数，则其傅里叶系数 \\(a_0=\\underline{\\hspace{2em}}\\)。","ans":"\\pi","sol":"<p>\\(a_0=\\dfrac1\\pi\\displaystyle\\int_{-\\pi}^{\\pi}|x|\\,dx=\\dfrac2\\pi\\int_0^\\pi x\\,dx=\\dfrac2\\pi\\cdot\\dfrac{\\pi^2}{2}=\\pi\\)。</p>","id":"b70"},{"ty":"blank","ch":12,"kp":"必要条件","src":"真题改编","diff":3,"q":"利用级数收敛的必要条件，求极限 \\(\\displaystyle\\lim_{n\\to\\infty}\\dfrac{2^{n}n!}{n^{n}}=\\underline{\\hspace{2em}}\\)。","ans":"0","sol":"<p>对 \\(\\sum\\dfrac{2^n n!}{n^n}\\) 用比值判别法：\\(\\lim\\dfrac{2^{n+1}(n+1)!}{(n+1)^{n+1}}\\cdot\\dfrac{n^n}{2^n n!}=\\lim\\dfrac{2n^n}{(n+1)^n}=\\dfrac2e<1\\)，级数收敛，故通项趋于 0，极限为 0。</p>","id":"b71"},{"ty":"blank","ch":12,"kp":"收敛域","src":"真题改编","diff":2,"q":"幂级数 \\(\\displaystyle\\sum_{n=1}^{\\infty}\\dfrac{(x-2)^{n}}{n\\cdot 2^{n}}\\) 的收敛域为 \\(\\underline{\\hspace{2em}}\\)。","ans":"[0,\\ 4)","sol":"<p>收敛半径 \\(R=2\\)，收敛区间 \\((0,4)\\)；\\(x=0\\) 时为 \\(\\sum\\dfrac{(-1)^n}{n}\\) 收敛，\\(x=4\\) 时为 \\(\\sum\\dfrac1n\\) 发散，故收敛域为 \\([0,4)\\)。</p>","id":"b72"}];

